/* El orden de las pestañas: primero las de trabajo, después las de consulta.
   Y el color de cada solapa, para distinguir los dos grupos de un vistazo. */
const FMT_ORDEN = ['RESUMEN', 'ALUMNADO', 'MATRÍCULA', 'AVISOS', 'AVISOS INFORMES', 'DISCREPANCIAS',
                   'PRIMARIA', 'SECUNDARIA', 'NEAE', 'JEFATURA', 'OFERTA', 'HISTORIAL'];
const FMT_COLOR_SOLAPA = {
  'RESUMEN': '#1F4E79',                                            // el panel, azul oscuro
  'ALUMNADO': '#2E7D32', 'AVISOS': '#2E7D32',                      // trabajo, verde
  'AVISOS INFORMES': '#2E7D32', 'DISCREPANCIAS': '#2E7D32', 'MATRÍCULA': '#2E7D32',
  'PRIMARIA': '#9E9E9E', 'SECUNDARIA': '#9E9E9E', 'NEAE': '#9E9E9E',
  'JEFATURA': '#9E9E9E', 'OFERTA': '#9E9E9E', 'HISTORIAL': '#9E9E9E'    // consulta, gris
};

/*** ================= EL RÓTULO DE LA FILA 1 ================= ***/

/* Cambia la frase larga de A1 por un rótulo corto, y guarda la frase entera
   como nota de esa casilla. Así se sigue pudiendo leer, pero deja de mandar
   sobre el ancho de la columna A. */
function acortarRotulo_(hoja, nombre) {
  const celda = hoja.getRange(1, 1);
  const texto = String(celda.getValue() === null || celda.getValue() === undefined
                       ? '' : celda.getValue()).trim();
  if (!texto) return;
  if (texto.length <= 70) return;              // ya está acortado de otra vez

  celda.setNote(texto);

  /* La fecha se saca de la propia frase, que siempre acaba en
     "Actualizado: 6/9/2026, 12:31:05". */
  let fecha = '';
  const m = texto.match(/Actualizado:\s*(.+)$/);
  if (m) fecha = String(m[1]).trim();

  celda.setValue(nombre + (fecha ? ' · ' + fecha : ''))
       .setFontWeight('bold')
       .setFontStyle('normal')
       .setFontColor('#666666')
       .setWrap(false);
}

/*** ================= AUXILIARES ================= ***/

/* Dónde está cada columna, por su título. Devuelve el número de columna
   (la primera es la 1), o 0 si esa columna no existe en la pestaña. */
function fmtColumnaDe_(titulos, titulo) {
  for (let c = 0; c < titulos.length; c++) {
    if (String(titulos[c] === null || titulos[c] === undefined ? '' : titulos[c]).trim() === titulo) {
      return c + 1;
    }
  }
  return 0;
}

/* El número de columna (1, 2, 3...) en letras (A, B, C... AA, AB...), sin
   preguntarle nada a Google: hace falta para construir a mano las
   referencias A1 que agrupan columnas con getRangeList, sin gastar una
   llamada por columna solo para saber su letra. */
function fmtLetraColumna_(col) {
  let letras = '';
  while (col > 0) {
    const resto = (col - 1) % 26;
    letras = String.fromCharCode(65 + resto) + letras;
    col = Math.floor((col - 1) / 26);
  }
  return letras;
}

/*** ================= 5. FILAS ALTERNAS Y COLORES ================= ***/

/* Filas alternas suaves. Con 668 filas y 30 columnas, seguir una fila con la
   vista cansa. Hay que quitar las bandas de la vez anterior: Google no deja
   dos bandas encima del mismo sitio. */
function fmtFilasAlternas_(hoja, filaCab, ultimaFila, ancho) {
  const anteriores = hoja.getBandings();
  for (let i = 0; i < anteriores.length; i++) {
    try { anteriores[i].remove(); } catch (e) { /* si no se puede, se sigue */ }
  }
  const nDatos = ultimaFila - filaCab;
  if (nDatos <= 1) return;
  try {
    hoja.getRange(filaCab + 1, 1, nDatos, ancho)
        .applyRowBanding(SpreadsheetApp.BandingTheme.LIGHT_GREY, false, false);
  } catch (e) { /* las bandas son un lujo, no se para por ellas */ }
}

/* Los colores que señalan solos lo que hay que mirar.
   Se borran siempre los de la vez anterior: si no, se van acumulando. */
function fmtColoresAutomaticos_(hoja, nombre, filaCab, ultimaFila, ancho, titulos) {
  hoja.setConditionalFormatRules([]);
  const nDatos = ultimaFila - filaCab;
  if (nDatos <= 0) return;
  const primera = filaCab + 1;
  const reglas = [];

  /* Una columna concreta, cuando su texto es exactamente X. */
  const siDice = function (titulo, texto, color) {
    const c = fmtColumnaDe_(titulos, titulo);
    if (!c) return;
    reglas.push(SpreadsheetApp.newConditionalFormatRule()
      .whenTextEqualTo(texto).setBackground(color)
      .setRanges([hoja.getRange(primera, c, nDatos, 1)]).build());
  };

  /* Una columna concreta, cuando está vacía. */
  const siVacia = function (titulo, color) {
    const c = fmtColumnaDe_(titulos, titulo);
    if (!c) return;
    reglas.push(SpreadsheetApp.newConditionalFormatRule()
      .whenCellEmpty().setBackground(color)
      .setRanges([hoja.getRange(primera, c, nDatos, 1)]).build());
  };

  /* La fila entera, cuando la columna de mando NO está vacía. */
  const filaSiMarcada = function (titulo, color) {
    const c = fmtColumnaDe_(titulos, titulo);
    if (!c) return;
    const letra = hoja.getRange(1, c).getA1Notation().replace(/[0-9]/g, '');
    reglas.push(SpreadsheetApp.newConditionalFormatRule()
      .whenFormulaSatisfied('=$' + letra + primera + '<>""').setBackground(color)
      .setRanges([hoja.getRange(primera, 1, nDatos, ancho)]).build());
  };

  if (nombre === 'ALUMNADO') {
    /* Lo que todavía no sabemos. */
    siDice('Asignaturas pendientes', SIN_DATO, FMT_AMBAR);
    siDice('MAT NO SUP.', SIN_DATO, FMT_AMBAR);
    /* Sabemos que repitió, pero no de qué curso. En Primaria solo lo dice el
       expediente; en ESO, un HISTORIAL de una versión anterior. */
    siDice('Cursos repetidos en Primaria', SIN_DATO, FMT_AMBAR);
    siDice('Cursos repetidos en ESO', SIN_DATO, FMT_AMBAR);
    /* Repeticiones de Primaria estimadas por edad: hay que revisarlas a mano. */
    siDice('Fuente Primaria', 'EDAD', FMT_AMBAR);
    /* La matrícula que no cuadra, en ámbar. Es justo lo que hay que arreglar
       en Séneca. Una casilla vacía no se pinta. */
    const cMatri = fmtColumnaDe_(titulos, 'MATRÍCULA');
    if (cMatri) {
      const letraM = hoja.getRange(1, cMatri).getA1Notation().replace(/[0-9]/g, '');
      reglas.push(SpreadsheetApp.newConditionalFormatRule()
        .whenFormulaSatisfied('=AND($' + letraM + primera + '<>"",$' + letraM + primera +
                              '<>"' + MATRICULA_OK + '")')
        .setBackground(FMT_AMBAR)
        .setRanges([hoja.getRange(primera, cMatri, nDatos, 1)]).build());
    }
    /* EL ARQUEO DE ASIGNATURAS. En rojo las dos casillas cuando el número que
       tiene en Séneca no es el que le toca por su curso. Si alguna de las dos
       está vacía no se pinta: es que no se ha podido saber. */
    const cNum = fmtColumnaDe_(titulos, 'Nº asignaturas');
    const cDebe = fmtColumnaDe_(titulos, 'Debería tener');
    if (cNum && cDebe) {
      const lN = hoja.getRange(1, cNum).getA1Notation().replace(/[0-9]/g, '');
      const lD = hoja.getRange(1, cDebe).getA1Notation().replace(/[0-9]/g, '');
      reglas.push(SpreadsheetApp.newConditionalFormatRule()
        .whenFormulaSatisfied('=AND($' + lN + primera + '<>"",$' + lD + primera + '<>"",$' +
                              lN + primera + '<>$' + lD + primera + ')')
        .setBackground(FMT_ROJO)
        .setRanges([hoja.getRange(primera, cNum, nDatos, 1),
                    hoja.getRange(primera, cDebe, nDatos, 1)]).build());
    }
    /* Repeticiones que hubo pero no sabemos dónde. Cuentan para el PIL, y
       conviene mirarlas una a una: puede que el alumno vaya retrasado por
       otro motivo. Aquí el valor es un número, no un texto. */
    const cSinLoc = fmtColumnaDe_(titulos, 'Rep. sin localizar');
    if (cSinLoc) {
      reglas.push(SpreadsheetApp.newConditionalFormatRule()
        .whenNumberGreaterThan(0).setBackground(FMT_AMBAR)
        .setRanges([hoja.getRange(primera, cSinLoc, nDatos, 1)]).build());
    }
    /* Sin unidad en Séneca: este alumno no sale en ningún informe. */
    siVacia('Unidad', FMT_ROJO);
    /* Los PIL, para localizarlos de un vistazo. No es un problema: es un dato.
       Son dos columnas: la de este curso, que va al papel, y la de la etapa. */
    const PERMANENCIA = ['PIL', 'No podrá repetir este curso',
                         'Ha agotado las dos permanencias'];
    for (let q = 0; q < PERMANENCIA.length; q++) {
      siDice(PERMANENCIA[q], 'SÍ', FMT_AZUL);
      /* En ámbar lo que se apoya en una suposición por edad, y lo que no
         sabemos: hay que comprobarlo antes de dárselo a nadie. */
      siDice(PERMANENCIA[q], PIL_POR_EDAD, FMT_AMBAR);
      siDice(PERMANENCIA[q], SIN_DATO, FMT_AMBAR);
    }
    /* De dónde viene el alumno: en ámbar lo que no sabemos. */
    siDice('Curso el año pasado', SIN_DATO, FMT_AMBAR);
    siDice('Repetía el año pasado', SIN_DATO, FMT_AMBAR);
    siDice('Suspensos el año pasado', SIN_DATO, FMT_AMBAR);
  } else if (nombre === 'HISTORIAL') {
    siDice('Fuente Primaria', 'EDAD', FMT_AMBAR);
  } else if (nombre === 'SECUNDARIA') {
    siDice('Unidad', 'NO ESTÁ EN ALUMNADO', FMT_ROJO);
  } else if (nombre === 'PRIMARIA') {
    siDice('Rep. Primaria (expediente)', 'expediente incompleto', FMT_AMBAR);
    siDice('Unidad', 'NO ESTÁ EN ALUMNADO', FMT_ROJO);
  } else if (nombre === 'DISCREPANCIAS' || nombre === 'AVISOS' ||
             nombre === 'AVISOS INFORMES' || nombre === 'MATRÍCULA') {
    /* En verde lo que ya has marcado. Lo que queda en blanco es lo que falta,
       y es justo lo que cuenta el panel. */
    filaSiMarcada('Estado', FMT_VERDE);
  }

  if (reglas.length) hoja.setConditionalFormatRules(reglas);
}

/*** ================= 6. LOS DESPLEGABLES ================= ***/

/* La columna "Estado" pasa a ser una lista de opciones.
   IMPORTANTE: dejarla VACÍA sigue queriendo decir "pendiente". El panel y la
   portada del PDF cuentan las filas con Estado vacío, así que no se pone
   ninguna opción que signifique "todavía no". */
function fmtDesplegables_(hoja, def, filaCab, ultimaFila, titulos) {
  if (!def.estado) return;
  const c = fmtColumnaDe_(titulos, def.estado.columna);
  if (!c) return;
  const nDatos = ultimaFila - filaCab;
  if (nDatos <= 0) return;

  const regla = SpreadsheetApp.newDataValidation()
    .requireValueInList(def.estado.opciones, true)
    .setAllowInvalid(false)
    .setHelpText(def.estado.ayuda ||
                 'Elige una opción. Si lo dejas vacío, cuenta como pendiente.')
    .build();
  hoja.getRange(filaCab + 1, c, nDatos, 1).setDataValidation(regla);
}

/*** ================= 7. EL AVISO AL ESCRIBIR ================= ***/

/* Las columnas que reescribe el programa quedan protegidas "con aviso": se
   puede escribir en ellas, pero Google pregunta antes. No bloquea nada; solo
   evita que Francisco pierda una nota sin enterarse.

   Se protegen por tramos seguidos de columnas, no una a una, para no hacer
   veinte llamadas por pestaña. Y se quitan siempre las protecciones de la vez
   anterior. */
function fmtProtegerCalculadas_(hoja, def, filaCab, ultimaFila, titulos) {
  const nDatos = ultimaFila - filaCab;
  if (nDatos <= 0) {
    const vacias = hoja.getProtections(SpreadsheetApp.ProtectionType.RANGE);
    for (let i = 0; i < vacias.length; i++) {
      try { vacias[i].remove(); } catch (e) { /* si no se puede, se sigue */ }
    }
    return;
  }

  /* Los tramos que hacen falta, EN NOTACIÓN A1, calculados antes de tocar
     ninguna protección. Son las columnas seguidas que ni son manuales ni
     están libres para escribir. */
  const libres = def.manuales.concat(def.noProteger || []);
  const tramos = [];
  let inicio = -1;
  for (let c = 0; c <= titulos.length; c++) {
    const fin = c === titulos.length;
    const titulo = fin ? '' : String(titulos[c] === null || titulos[c] === undefined
                                     ? '' : titulos[c]).trim();
    const esLibre = fin || libres.indexOf(titulo) !== -1;
    if (!esLibre) {
      if (inicio === -1) inicio = c;
      continue;
    }
    if (inicio !== -1) {
      tramos.push(fmtLetraColumna_(inicio + 1) + (filaCab + 1) + ':' +
                  fmtLetraColumna_(c) + ultimaFila);
      inicio = -1;
    }
  }

  /* Si las protecciones que ya hay son EXACTAMENTE esos mismos rangos, todas
     con aviso y no bloqueo, no se borra ni se crea nada: son ocho protecciones
     por pestaña que casi nunca cambian de una actualización a la siguiente. */
  const previas = hoja.getProtections(SpreadsheetApp.ProtectionType.RANGE);
  if (previas.length === tramos.length) {
    const actuales = previas.map(function (p) { return p.getRange().getA1Notation(); }).sort();
    const esperados = tramos.slice().sort();
    let iguales = true;
    for (let i = 0; i < actuales.length; i++) {
      if (actuales[i] !== esperados[i]) { iguales = false; break; }
    }
    if (iguales && previas.every(function (p) { return p.isWarningOnly(); })) return;
  }

  for (let i = 0; i < previas.length; i++) {
    try { previas[i].remove(); } catch (e) { /* si no se puede, se sigue */ }
  }
  for (let i = 0; i < tramos.length; i++) {
    try {
      hoja.getRange(tramos[i])
          .protect()
          .setWarningOnly(true)
          .setDescription('Lo escribe el programa. Lo que pongas aquí se pierde ' +
                          'en la próxima actualización.');
    } catch (e) { /* si Google no deja proteger, se sigue */ }
  }
}

/*** ================= 8. ORDEN Y COLOR DE LAS PESTAÑAS ================= ***/

/* Primero las de trabajo, después las de consulta. Las pestañas que no estén
   en la lista se quedan donde estén. */
function fmtOrdenarPestanas_() {
  const libro = libroActivo_();
  let pos = 1;
  for (let i = 0; i < FMT_ORDEN.length; i++) {
    const hoja = libro.getSheetByName(FMT_ORDEN[i]);
    if (!hoja) continue;

    /* El color, solo si no es ya el que le toca. */
    const colorQueToca = FMT_COLOR_SOLAPA[FMT_ORDEN[i]] || null;
    if (hoja.getTabColor() !== colorQueToca) {
      try { hoja.setTabColor(colorQueToca); } catch (e) { }
    }

    /* Y la posición, solo si no está ya en la que le toca. Cuando las
       pestañas ya están en orden (lo normal, salvo la primera vez o si
       alguien las ha movido a mano), esto se ahorra el setActiveSheet y el
       moveActiveSheet de las ocho pestañas. */
    if (hoja.getIndex() === pos) {
      pos++;
      continue;
    }
    try {
      libro.setActiveSheet(hoja);
      libro.moveActiveSheet(pos);
      pos++;
    } catch (e) { /* si no se puede mover, se queda donde está */ }
  }
}

/*** ================= FORMATEAR UNA PESTAÑA ================= ***/

/* Devuelve true si la ha tocado. Si la pestaña no existe o está vacía, no
   hace nada y devuelve false. */
function formatearHoja_(nombre) {
  const def = FORMATO_HOJAS[nombre];
  if (!def) return false;
  const hoja = libroActivo_().getSheetByName(nombre);
  if (!hoja) return false;

  const filaCab = def.cabecera;
  const ultimaFila = hoja.getLastRow();
  const ancho = hoja.getLastColumn();
  if (ancho < 1 || ultimaFila < filaCab) return false;

  /* 1. El rótulo de la fila 1, en las pestañas que lo llevan. */
  if (filaCab === 2) acortarRotulo_(hoja, nombre);

  /* 2. Columna a columna: ancho fijo, ajuste de texto y alineación.
        El ancho se decide por el TÍTULO de la columna, no por su posición,
        así que reordenarlas no rompe nada.

        El ancho de cada columna suele ser distinto, pero las que quedan
        seguidas con el mismo ancho se agrupan y se ponen con una sola
        llamada (setColumnWidths), más abajo. El ajuste de texto y la
        alineación solo tienen tres combinaciones posibles (C, I, W), así que
        en vez de tocar cada columna por separado se apuntan en tres grupos y
        se aplican al final con getRangeList: tres llamadas en total en vez de
        una por columna. Con 20-30 columnas por pestaña y ocho pestañas, son
        varios cientos de llamadas menos cada vez que se pulsa "Actualizar
        los datos". */
  const titulos = hoja.getRange(filaCab, 1, 1, ancho).getValues()[0];
  const nDatos = ultimaFila - filaCab;

  /* La explicación de cada columna va como nota de la celda del título. Se
     ponen todas de una vez al terminar el recorrido, que es mucho más rápido
     que casilla por casilla. Una columna sin explicación recibe nota vacía,
     así se borra la que hubiera de una versión anterior. */
  const notasFila = [];
  const grupoRangos = { W: [], I: [], C: [] };
  const anchosPorColumna = [];

  for (let c = 0; c < ancho; c++) {
    const titulo = String(titulos[c] === null || titulos[c] === undefined
                          ? '' : titulos[c]).trim();
    const conf = def.cols[titulo] || [ANCHO_DEFECTO, 'C'];
    anchosPorColumna.push(conf[0]);
    notasFila.push(def.notas && def.notas[titulo] ? def.notas[titulo] : '');
    if (nDatos <= 0) continue;

    const tipo = grupoRangos[conf[1]] ? conf[1] : 'C';
    const letra = fmtLetraColumna_(c + 1);
    grupoRangos[tipo].push(letra + (filaCab + 1) + ':' + letra + (filaCab + nDatos));
  }

  /* Los anchos: se agrupan las columnas seguidas que llevan el mismo ancho y
     se ponen con una sola llamada por tramo (setColumnWidths), en vez de una
     llamada por columna. En una pestaña de 20-30 columnas son varias
     llamadas menos, y hay ocho pestañas cada vez que se pulsa "Actualizar
     los datos". */
  let desdeTramo = 0;
  for (let c = 1; c <= ancho; c++) {
    if (c < ancho && anchosPorColumna[c] === anchosPorColumna[desdeTramo]) continue;
    hoja.setColumnWidths(desdeTramo + 1, c - desdeTramo, anchosPorColumna[desdeTramo]);
    desdeTramo = c;
  }

  if (nDatos > 0) {
    if (grupoRangos.W.length) {
      hoja.getRangeList(grupoRangos.W)
          .setWrap(true).setHorizontalAlignment('left').setVerticalAlignment('top');
    }
    if (grupoRangos.I.length) {
      hoja.getRangeList(grupoRangos.I)
          .setWrap(false).setHorizontalAlignment('left').setVerticalAlignment('top');
    }
    if (grupoRangos.C.length) {
      hoja.getRangeList(grupoRangos.C)
          .setWrap(false).setHorizontalAlignment('center').setVerticalAlignment('top');
    }
  }

  hoja.getRange(filaCab, 1, 1, ancho).setNotes([notasFila]);

  /* 3. La cabecera: centrada, con ajuste de texto y sitio para tres líneas.
        Hay títulos largos, como "Cursos repetidos en Primaria". */
  hoja.getRange(filaCab, 1, 1, ancho)
      .setWrap(true).setHorizontalAlignment('center').setVerticalAlignment('middle');
  hoja.setRowHeight(filaCab, 48);

  /* 4. Filas alternas. Va antes del amarillo, aunque daría igual: un color
        puesto a mano siempre gana a las bandas. */
  fmtFilasAlternas_(hoja, filaCab, ultimaFila, ancho);

  /* 5. Las columnas que rellena Francisco, en amarillo. */
  if (nDatos > 0) {
    for (let i = 0; i < def.manuales.length; i++) {
      const c = fmtColumnaDe_(titulos, def.manuales[i]);
      if (c) hoja.getRange(filaCab + 1, c, nDatos, 1).setBackground(AMARILLO_MANUAL);
    }
  }

  /* 6. Congelar. Nunca más columnas de las que tiene la pestaña. */
  hoja.setFrozenRows(filaCab);
  hoja.setFrozenColumns(Math.min(def.congelar, ancho));

  /* 7. El filtro. Hay que quitar el que hubiera antes: Google no deja tener
        dos, ni ampliar uno ya puesto. */
  const filtro = hoja.getFilter();
  if (filtro) filtro.remove();
  hoja.getRange(filaCab, 1, ultimaFila - filaCab + 1, ancho).createFilter();

  /* 8. Los colores automáticos, los desplegables y el aviso al escribir. */
  fmtColoresAutomaticos_(hoja, nombre, filaCab, ultimaFila, ancho, titulos);
  fmtDesplegables_(hoja, def, filaCab, ultimaFila, titulos);
  fmtProtegerCalculadas_(hoja, def, filaCab, ultimaFila, titulos);

  return true;
}

/*** ================= FORMATEAR TODAS ================= ***/

/* Lo llama Panel.gs al final de "Actualizar los datos".
   Si una pestaña falla, se anota y se sigue con las demás: el formato nunca
   debe tumbar una actualización que ya ha salido bien. */
function arreglarFormatoDeTodo_() {
  const orden = ['HISTORIAL', 'ALUMNADO', 'JEFATURA', 'DISCREPANCIAS', 'MATRÍCULA',
                 'NEAE', 'PRIMARIA', 'SECUNDARIA', 'AVISOS', 'AVISOS INFORMES'];
  let hojas = 0;
  const fallos = [];
  for (let i = 0; i < orden.length; i++) {
    /* EL RELOJ (Codigo.gs): el formato es lo último y lo más prescindible. Si
       no queda tiempo para otra pestaña, se para: las que falten se arreglan
       la próxima vez que se pulse "1". Los datos ya están escritos; lo que se
       queda a medias es el ancho de las columnas y los colores. */
    if (!quedaTiempo_(10)) { fallos.push(orden[i] + ': sin tiempo'); continue; }
    paso_('formato-' + orden[i]);   // instrucción 81: una cifra por pestaña
    try {
      if (formatearHoja_(orden[i])) hojas++;
    } catch (e) {
      fallos.push(orden[i] + ': ' + e.message);
    }
  }
  paso_('formato-orden');
  try {
    fmtOrdenarPestanas_();
  } catch (e) {
    fallos.push('orden de las pestañas: ' + e.message);
  }
  return { hojas: hojas, fallos: fallos };
}

/*** ================= LAS ANOTACIONES DE AVISOS =================
 *
 * La pestaña AVISOS se reescribe entera en cada actualización, y hasta la
 * BD v21 las columnas "Estado" y "Observaciones" se quedaban vacías. Lo que
 * Francisco anotaba ahí se perdía al pulsar el botón.
 *
 * Cada aviso se reconoce por lo que dicen sus cinco primeras columnas:
 * curso, grupo, alumno, aviso y detalle. Si el detalle ha cambiado un poco
 * (lleva nombres de fichero y fechas), se prueba con una clave más corta:
 * alumno y tipo de aviso. Esa segunda clave solo se usa cuando hay alumno,
 * para no colocarle a un aviso la nota de otro.
 * ======================================================== ***/


function claveAvisoLarga_(fila) {
  return normalizar(fila[0]) + '|' + normalizar(fila[1]) + '|' + normalizar(fila[2]) +
         '|' + normalizar(fila[3]) + '|' + normalizar(fila[4]);
}

/* Lleva el curso delante porque dos alumnos distintos pueden llamarse igual y
   sus anotaciones no se pueden mezclar. */
function claveAvisoCorta_(fila) {
  return normalizar(fila[0]) + '|' + normalizar(fila[2]) + '|' + normalizar(fila[3]);
}

/* Se llama ANTES de reconstruir la pestaña. Devuelve un mapa de anotaciones. */
function notasDeAvisos_() {
  const hoja = libroActivo_().getSheetByName(HOJA_AVISOS);
  const previos = {};
  if (!hoja || hoja.getLastRow() < 2 || hoja.getLastColumn() < COL_AV_OBS) return previos;

  const datos = hoja.getRange(2, 1, hoja.getLastRow() - 1, COL_AV_OBS).getValues();
  for (let f = 0; f < datos.length; f++) {
    const estado = String(datos[f][COL_AV_ESTADO - 1] || '').trim();
    const obs = String(datos[f][COL_AV_OBS - 1] || '').trim();
    if (!estado && !obs) continue;
    const valor = [datos[f][COL_AV_ESTADO - 1], datos[f][COL_AV_OBS - 1]];
    previos[claveAvisoLarga_(datos[f])] = valor;
    if (String(datos[f][2] || '').trim()) previos[claveAvisoCorta_(datos[f])] = valor;
  }
  return previos;
}

/* Se llama DESPUÉS de reconstruir la pestaña. Devuelve cuántas filas ha
   podido recuperar. */
function restaurarNotasAvisos_(previos) {
  if (!previos) return 0;
  const hoja = libroActivo_().getSheetByName(HOJA_AVISOS);
  if (!hoja || hoja.getLastRow() < 2) return 0;

  const n = hoja.getLastRow() - 1;
  const datos = hoja.getRange(2, 1, n, 5).getValues();
  const salida = [];
  let recuperados = 0;

  for (let f = 0; f < n; f++) {
    let v = previos[claveAvisoLarga_(datos[f])];
    if (!v && String(datos[f][2] || '').trim()) v = previos[claveAvisoCorta_(datos[f])];
    if (v) {
      salida.push([v[0], v[1]]);
      recuperados++;
    } else {
      salida.push(['', '']);
    }
  }
  hoja.getRange(2, COL_AV_ESTADO, n, 2).setValues(salida);
  return recuperados;
}

/*** ================= LAS ANOTACIONES DE AVISOS INFORMES =================
 *
 * La pestaña AVISOS INFORMES tiene desde la BD v24 sus columnas "Estado" y
 * "Observaciones". La escribe InformesPdfBotones.gs, que también la reconstruye entera
 * cada vez, así que hace falta el mismo cuidado que con AVISOS.
 *
 * Aquí no hay dos pasos como allí. InformesPdfBotones.gs llama a esta función ANTES de
 * limpiar la pestaña, se guarda el mapa, y al escribir cada fila busca en él
 * lo que hubiera anotado Francisco.
 *
 * Cada incidencia se reconoce por sus cuatro columnas: grupo, pestaña, aviso
 * y detalle. Estas incidencias no llevan nombres de fichero ni fechas, así
 * que el texto se repite igual de una vez a otra y no hace falta una segunda
 * clave más corta.
 * ======================================================== ***/


/* Devuelve un mapa: clave de la incidencia -> [Estado, Observaciones].
   Si la pestaña todavía no tiene esas dos columnas, devuelve un mapa vacío y
   no pasa nada: la primera vez sale en blanco. */
function notasDeAvisosInformes_() {
  const previos = {};
  const hoja = libroActivo_().getSheetByName(HOJA_AV_INF);
  if (!hoja || hoja.getLastRow() < 3 || hoja.getLastColumn() < 6) return previos;

  const datos = hoja.getRange(3, 1, hoja.getLastRow() - 2, 6).getValues();
  for (let f = 0; f < datos.length; f++) {
    const estado = String(datos[f][4] || '').trim();
    const obs = String(datos[f][5] || '').trim();
    if (!estado && !obs) continue;
    previos[claveAvisoInforme_(datos[f])] = [datos[f][4], datos[f][5]];
  }
  return previos;
}

/*** Codigo.gs ***/
/*** ================= CONFIGURACIÓN ================= ***/
const VERSION = 'BD v71';

/*** ================= EL RELOJ: LOS SEIS MINUTOS DE GOOGLE =================
 *
 * Google corta en seco cualquier script que pase de seis minutos, con un
 * cartel rojo ("Se ha superado el tiempo máximo de ejecución") y sin dejar
 * nada escrito: ni el panel, ni los tiempos, ni saber por dónde iba. Le pasó
 * a Francisco el 11-sep-2026 al pulsar "1. Actualizar los datos".
 *
 * Desde la BD v67 el programa se mira el reloj. Antes de empezar cada trozo
 * largo pregunta si le queda tiempo; si no le queda, no lo empieza: lo apunta
 * como pendiente y termina bien, escribiendo el panel con los tiempos de cada
 * fase. Volver a pulsar "1" lo remata, porque lo que ya está hecho no se
 * repite (los informes que no han cambiado se saltan solos).
 *
 * Así nunca se pierde el trabajo hecho y siempre se sabe en qué se ha ido el
 * tiempo.
 * ======================================================================== ***/

/* Los minutos que da Google, y lo que se reserva para escribir el panel. */
const MINUTOS_DE_GOOGLE = 6;
const SEGUNDOS_PARA_CERRAR = 80;
let ARRANQUE_ = 0;
let SE_ACABO_EL_TIEMPO_ = false;

/* Se llama al principio de "Actualizar los datos". */
function arrancarReloj_() {
  ARRANQUE_ = Date.now();
  SE_ACABO_EL_TIEMPO_ = false;
}

/* ¿Queda tiempo para un trozo que puede tardar 'segundos'? Sin reloj
   arrancado (por ejemplo si alguien llama a una función suelta desde el
   editor) siempre dice que sí, para no cambiar nada de cómo se comporta. */
function quedaTiempo_(segundos) {
  if (!ARRANQUE_) return true;
  const gastado = Date.now() - ARRANQUE_;
  const tope = (MINUTOS_DE_GOOGLE * 60 - SEGUNDOS_PARA_CERRAR - (segundos || 0)) * 1000;
  if (gastado < tope) return true;
  SE_ACABO_EL_TIEMPO_ = true;
  return false;
}
/* El curso escolar ya no es una constante: lo da cursoEscolar_() (Cursos.gs),
   desde la pestaña oculta "_cursos" (instrucción 10, docs/FASE-1-WEB.md). */
const MARCA = 'MATR';
const PEND = 'PEND';
/* EDAD_TEORICA vive desde la instrucción 108 en PilRegla.gs (la regla del PIL, común al servidor y al navegador). */
/* EN PRIMARIA SOLO SE PUEDE REPETIR UNA VEZ EN TODA LA ETAPA.
   Artículo 15 del Real Decreto 157/2022: la permanencia un año más "solo se
   podrá adoptar una vez durante la etapa" y tiene "carácter excepcional".
   Añadido en la BD v35, cuando se lo dijeron a Francisco.

   Esto pone un techo a la estimación por edad: un alumno que va dos años por
   detrás NO puede haber repetido dos veces en Primaria. Como mucho una, y el
   año que sobra es otra cosa (repitió en otro instituto, o se incorporó tarde
   al sistema educativo español). Ese año que sobra se va solo a la columna
   'Rep. sin localizar', así que las repeticiones totales no cambian y el PIL
   tampoco: lo que cambia es que ya no se le atribuye a Primaria algo que no
   puede haber pasado en Primaria. */
const MAX_REP_PRIMARIA = 1;

/* CUÁNTAS ASIGNATURAS SUSPENSAS DEJAN PROMOCIONAR.
   Añadido en la BD v36, a partir de una observación de Francisco: un alumno
   que el año pasado estaba repitiendo y este año está en el curso siguiente
   NO tiene por qué haber promocionado por imperativo legal. Puede haber
   aprobado. Con dos suspensas o menos promociona por sus propios medios; con
   más de dos, si no podía repetir, la ley lo sube igualmente, y ESO es el PIL.
   Se cuentan todas las materias con evaluación negativa, incluidas las
   pendientes de cursos anteriores: es la columna "Suspensos" de las hojas EV
   del cuaderno de notas. */
/* MAX_SUSPENSOS_PROMOCION, PIL_POR_EDAD, esNumero y aNumero viven desde la instrucción 64 en PilRegla.gs (la regla del PIL la usa también la mesa). */
const ESTADOS_QUE_NO_CUENTAN = ['anulada', 'trasladada'];
const COL_AMBITOS = 'Ámbito Científico-Tecnológico';
const NIVELES_ESO = ['1º', '2º', '3º', '4º'];
/* Cómo se llama este centro dentro del campo "Centro" de los expedientes de Séneca (lo que se BUSCA) y cómo se ESCRIBE en el cuadro de la trayectoria: salen de la
   configuración del centro (Centro.gs, instrucción 56: centroNombreCorto_() y centroNombre_()). */

/* La etapa que trae hoy el sistema. Se escribe detrás del curso, para que no
   haya que adivinar de qué "2º" se está hablando. Cuando entren los
   Bachilleratos habrá que saber la etapa alumno por alumno. */
const ETAPA_ACTUAL = 'ESO';

const TITULOS_ALUMNADO = [
  /* Quién es */
  'Alumno/a', 'Unidad', 'Curso', 'Edad a 31/12',
  /* De dónde viene */
  'Curso el año pasado', 'Repetía el año pasado', 'Repetía el año pasado (corregido)',
  'Suspensos el año pasado',
  'Repite el curso actual',
  /* Qué ha repetido */
  'Repeticiones en ESO', 'Cursos repetidos en ESO', 'Fuente ESO',
  'Rep. Primaria (calculado)', 'Cursos repetidos en Primaria', 'Fuente Primaria',
  'Rep. sin localizar',
  'Rep. Primaria (corregido)', 'Motivo de la corrección',
  'Repeticiones totales',
  /* Y qué puede pasar. Las tres van en orden de tiempo: el año pasado, este
     junio, y el resto de la etapa. Delante de la primera va la casilla en la
     que el equipo directivo puede decidir a mano. */
  'PIL (a mano)', 'PIL', 'No podrá repetir este curso', 'Ha agotado las dos permanencias',
  'Trayectoria',
  /* Lo que debe */
  'MAT NO SUP.', 'Nº pendientes', 'Asignaturas pendientes',
  /* Los apoyos que recibe */
  'Diversificación', 'NEAE', 'MEDIDAS Y RECURSOS',
  /* Lo que cursa este año. Las dos últimas son solo de Bachillerato: en la
     ESO se quedan vacías, y al revés con las de la ESO. Ver Bachillerato.gs. */
  'OPT', 'FR -> ALCT', 'MAT', 'OPC1', 'OPC2', 'OPC3', 'OPC4', 'REL/Atedu',
  'MODALIDAD', 'MAT. MODALIDAD', 'OPTATIVAS', 'MATRÍCULA',
  /* El arqueo: cuántas asignaturas tiene en Séneca y cuántas le tocan por su
     curso. Ver asignaturasQueLeTocan_ en Matricula.gs. */
  'Nº asignaturas', 'Debería tener',
  /* Lo tuyo */
  'Observaciones',
  /* Instrucción 108: lo que la web necesita para recalcular el PIL al corregir una repetición y no se saca de otra columna (PilRegla.gs, `pilBaseTexto_`). */
  'Base del PIL'];
/* Amarillas: las escribe Francisco y el programa nunca las pisa. Desde la instrucción 95 ya no queda ninguna: las seis columnas se corrigen en la ficha de la web
   (`_correcciones`, Correcciones.gs) y «Observaciones» sale de las notas de la ficha (Observaciones.gs). */
const COLS_MANUALES_ALUMNADO = [];
/* COLS_CONSERVADAS vive en BaseHojas.gs (instrucción 50: la web pequeña la usa). */
/* La fecha de nacimiento la usa el censo NEAE para deshacer empates entre
   alumnos con las mismas iniciales. "Cursos repetidos en ESO" va la última
   para no mover de sitio nada de lo que ya leía componerAlumnado. */
const TITULOS_HISTORIAL = ['Alumno/a', 'Nº Id. Escolar', 'Unidad', 'Curso', 'Edad a 31/12',
  'Repite el curso actual', 'Repeticiones en ESO', 'Rep. Primaria (calculado)', 'Fuente Primaria',
  'Fecha de nacimiento', 'Cursos repetidos en ESO',
  'Curso el año pasado', 'Repetía el año pasado', 'Años en la ESO'];

/*** El menú lo crea Actualizador.gs, no este fichero. ***/

/* 2024 -> "24-25". Un año académico escrito con cuatro cifras obliga al lector
   a acordarse de que "2024" quiere decir el curso 2024-2025. Escrito así se
   entiende de un vistazo. Si lo que llega no es un año, se devuelve igual. */
function anoAcademico_(ano) {
  const n = parseInt(ano, 10);
  if (!n) return '';
  if (n < 1900 || n > 2200) return String(ano);
  return String(n).slice(-2) + '-' + String(n + 1).slice(-2);
}

function nivelESO(texto) {
  const m = String(texto || '').trim().match(/^([1-4])\s*º?\s*(de\s+)?E\.?\s*S\.?\s*O\.?/i);
  return m ? m[1] + 'º' : '';
}

/* Deja un número de repeticiones de Primaria dentro de lo que permite la ley:
   ni menos de cero ni más de una. Solo se aplica a los números ESTIMADOS por
   edad; lo que dice el expediente de un alumno se respeta tal cual, porque es
   un hecho, y si dijera más de una se anota en AVISOS. */
function topeRepPrimaria_(v) {
  if (v === '' || v === null || v === undefined || !esNumero(v)) return v;
  const n = aNumero(v);
  if (n < 0) return 0;
  if (n > MAX_REP_PRIMARIA) return MAX_REP_PRIMARIA;
  return n;
}

/* El año de nacimiento, venga como fecha de verdad o como texto DD/MM/AAAA,
   que son las dos formas en las que puede estar en la pestaña HISTORIAL. */
function anoDeNacimiento_(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (v instanceof Date) return v.getFullYear();
  const m = String(v).match(/(\d{4})/);
  return m ? parseInt(m[1], 10) : 0;
}

/*** ================= LÓGICA: HISTÓRICO ================= ***/
function calcularHistorial(tabla) {
  const cab = tabla[0].map(normalizar);
  const iNombre = cab.indexOf(normalizar('Alumno/a'));
  const iId = cab.indexOf(normalizar('Nº Id. Escolar'));
  const iCurso = cab.indexOf(normalizar('Curso'));
  const iUnidad = cab.indexOf(normalizar('Unidad'));
  const iAno = cab.indexOf(normalizar('Año de la matrícula'));
  const iEdad = cab.indexOf(normalizar('Edad a 31/12 del año de matrícula'));
  const iEstado = cab.indexOf(normalizar('Estado Matrícula'));
  const iFecNac = cab.indexOf(normalizar('Fecha de nacimiento'));
  if (iNombre === -1 || iId === -1 || iCurso === -1 || iAno === -1 || iEdad === -1) {
    throw new Error('Al histórico le faltan columnas necesarias.');
  }

  let ultimo = 0;
  for (let f = 1; f < tabla.length; f++) {
    const a = parseInt(tabla[f][iAno], 10);
    if (a && a > ultimo) ultimo = a;
  }

  const actuales = {};
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    if (parseInt(fila[iAno], 10) !== ultimo) continue;
    if (!nivelESO(fila[iCurso])) continue;
    const id = String(fila[iId] || '').trim();
    if (id) actuales[id] = fila;
  }

  const anos = {};
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    const id = String(fila[iId] || '').trim();
    if (!actuales[id]) continue;
    const niv = nivelESO(fila[iCurso]);
    if (!niv) continue;
    const estado = iEstado === -1 ? '' : normalizar(fila[iEstado]);
    if (ESTADOS_QUE_NO_CUENTAN.indexOf(estado) !== -1) continue;
    if (!anos[id]) anos[id] = {};
    if (!anos[id][niv]) anos[id][niv] = {};
    anos[id][niv][String(fila[iAno]).trim()] = parseInt(fila[iEdad], 10);
  }

  const filas = [];
  for (const id in actuales) {
    const fila = actuales[id];
    const niv = nivelESO(fila[iCurso]);
    const porNivel = anos[id] || {};
    let repESO = 0;
    for (const n in porNivel) repESO += Object.keys(porNivel[n]).length - 1;
    const repite = Object.keys(porNivel[niv] || {}).length > 1 ? 'SÍ' : 'NO';

    /* QUÉ cursos de ESO ha repetido, y en qué años.
       RegAlum.csv trae una línea por alumno y por año de matrícula, así que
       esto ya estaba calculado aquí arriba: un curso que aparece en dos años
       distintos es un curso repetido. Hasta la BD v27 el programa se quedaba
       solo con el NÚMERO y tiraba el curso y los años.

       OJO: RegAlum es el registro de matrículas DE NUESTRO CENTRO. Si un
       alumno repitió en otro instituto y llegó aquí después, esa repetición
       no aparece: se le cuela en la estimación por edad de Primaria. */
    const repetidos = [];
    for (let k = 0; k < NIVELES_ESO.length; k++) {
      const anosNivel = porNivel[NIVELES_ESO[k]];
      if (!anosNivel) continue;
      const lista = Object.keys(anosNivel).sort();
      if (lista.length < 2) continue;
      repetidos.push(NIVELES_ESO[k] + ' (' +
        lista.map(function (a) { return anoAcademico_(a); }).join(', ') + ')');
    }
    const cursosESO = repetidos.join('; ');

    /* EN QUÉ CURSO ESTABA EL AÑO PASADO, Y SI LO ESTABA REPITIENDO.
       Añadido en la BD v34. RegAlum trae una línea por alumno y por año, así
       que esto ya estaba aquí calculado y se tiraba. Hace falta para saber si
       el alumno promocionó al curso de ahora por imperativo legal, que es la
       columna PIL que quiere el equipo directivo.
       Si el alumno no estaba en este centro el año pasado, las dos casillas
       se quedan vacías y más adelante se convierten en interrogante. */
    /* En qué curso estuvo cada año, en este centro. Es la materia prima de la
       columna Trayectoria de ALUMNADO, que cuenta la historia del alumno año
       por año en una sola casilla. Formato: "2024:1º; 2025:2º; 2026:3º". */
    const parejas = [];
    for (const n in porNivel) {
      for (const anoN in porNivel[n]) parejas.push([parseInt(anoN, 10), n]);
    }
    parejas.sort(function (x, y) { return x[0] - y[0]; });
    const anosESO = parejas.map(function (x) { return x[0] + ':' + x[1]; }).join('; ');

    const anoAnterior = ultimo - 1;
    let cursoPasado = '', repetiaPasado = '';
    for (const n in porNivel) {
      if (porNivel[n][String(anoAnterior)] === undefined) continue;
      cursoPasado = n;
      const anosDeEseNivel = Object.keys(porNivel[n]);
      repetiaPasado = 'NO';
      for (let q = 0; q < anosDeEseNivel.length; q++) {
        if (parseInt(anosDeEseNivel[q], 10) < anoAnterior) repetiaPasado = 'SÍ';
      }
    }

    const edad = parseInt(fila[iEdad], 10);
    let repPrim = '', fuente = '';
    const primero = porNivel['1º'];
    if (primero) {
      let menor = null;
      for (const a in primero) { const e = primero[a]; if (menor === null || e < menor) menor = e; }
      repPrim = menor - 12; fuente = '1ºESO';
    } else if (!isNaN(edad)) {
      repPrim = edad - EDAD_TEORICA[niv] - repESO; fuente = 'EDAD';
    }
    /* Las dos son cuentas de edad, y la ley les pone techo y suelo. */
    repPrim = topeRepPrimaria_(repPrim);
    filas.push([String(fila[iNombre]).trim(), id, iUnidad === -1 ? '' : String(fila[iUnidad] || '').trim(),
                niv, isNaN(edad) ? '' : edad, repite, repESO, repPrim, fuente,
                iFecNac === -1 ? '' : String(fila[iFecNac] || '').trim(), cursosESO,
                cursoPasado, repetiaPasado, anosESO]);
  }
  filas.sort(function (a, b) { return normalizar(a[0]) < normalizar(b[0]) ? -1 : 1; });
  return { filas: filas, ano: ultimo };
}

/*** ================= LÓGICA: MATRÍCULA ================= ***/
function leerMatricula(tabla, curso) {
  const cab = tabla[0].map(function (t) { return String(t).trim(); });
  const cabN = cab.map(normalizar);
  const iNombre = cabN.indexOf(normalizar('Alumno/a'));
  const iUnidad = cabN.indexOf(normalizar('Unidad'));
  const iAmb = cabN.indexOf(normalizar(COL_AMBITOS));

  /* Qué es cada columna: una materia de este curso (con su línea de la
     pestaña OFERTA, si la tiene), una pendiente de un curso anterior, o nada.
     Ver clasificarColumnas_ en Matricula.gs. */
  const C = clasificarColumnas_(cab, curso, iNombre, iUnidad);
  const existe = {};
  let conColumna = 0;
  for (let c = 0; c < C.clase.length; c++) {
    const k = C.clase[c];
    if (!k || k.tipo !== 'MATERIA') continue;
    if (k.lineas.length) { existe[normalizar(k.lineas[0].materia)] = true; conColumna++; }
  }
  /* Instrucción 110: las columnas de materia del CSV tal cual y, de cada alumno, cuáles tiene marcadas: con eso la página rehace la cuenta de la matrícula si cambia la oferta (MatriculaReglas.gs). */
  const colsMateria = C.clase.filter(function (k) { return k && k.tipo === 'MATERIA'; }).map(function (k) { return k.titulo; });

  const pendCols = [];
  for (let c = 0; c < cab.length; c++) {
    const m = cab[c].match(/^(.*?)\s*\(([1-4])º de E\.S\.O\.\)$/);
    if (m) pendCols.push({ i: c, asig: m[1].trim(), niv: m[2] });
  }

  const alumnos = [], sinUnidad = [];
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    const nombre = String(fila[iNombre] || '').trim();
    if (!nombre) continue;
    const unidad = iUnidad === -1 ? '' : String(fila[iUnidad] || '').trim();
    if (!unidad) sinUnidad.push(nombre);
    const esAmb = iAmb !== -1 && String(fila[iAmb] || '').trim().toUpperCase() === MARCA;

    /* Lo que tiene en Séneca, y en qué columna de ALUMNADO se enseña cada
       cosa. 'tiene' guarda el título del CSV, para poder escribirlo si la
       materia no está en la oferta. */
    const valores = {}, tiene = {}, crudo = { cols: colsMateria, curso: curso, t: [], ap: [] };
    for (let c = 0; c < C.clase.length; c++) {
      const k = C.clase[c];
      if (!k || k.tipo !== 'MATERIA') continue;
      if (!celdaMatriculada_(fila[c])) continue;
      crudo.t.push(k.titulo);
      const l = k.lineas.length ? k.lineas[0] : null;
      const clave = l ? normalizar(l.materia) : normalizar(k.titulo);
      tiene[clave] = l ? l.materia : k.titulo;
      if (l && l.columna) {
        valores[l.columna] = valores[l.columna] ? valores[l.columna] + ' / ' + l.abrev : l.abrev;
      }
    }

    const pend = [];
    for (let p = 0; p < pendCols.length; p++) {
      const pc = pendCols[p];
      if (String(fila[pc.i] || '').trim().toUpperCase() === PEND) {
        pend.push(abreviar(pc.asig) + ' ' + pc.niv + 'º');
      }
    }
    alumnos.push({ nombre: nombre, unidad: unidad, curso: curso, valores: valores,
                   pend: pend, diver: esAmb, tiene: tiene, existe: existe, modalidad: '', crudo: crudo });
  }
  const avisoNombres = avisoNombresDeMaterias_(curso, '', C, tabla, celdaMatriculada_);
  return { alumnos: alumnos, sinUnidad: sinUnidad, conColumna: conColumna,
           avisoNombres: avisoNombres };
}

/*** Trayectoria.gs ***/
/*** ================= LÓGICA: NOTAS ================= ***/
function leerNotas(valores) {
  const cab = valores[0].map(function (v) { return String(v === null || v === undefined ? '' : v).trim(); });
  let iSus = -1;
  for (let c = 0; c < cab.length; c++) {
    if (normalizar(cab[c]).indexOf('suspensos') === 0) { iSus = c; break; }
  }
  if (iSus === -1) return null;

  /* MAT NO SUP. son solo las materias del curso que el alumno repite.
     Las columnas cuyo título acaba en " 1º", " 2º"... son pendientes de
     cursos anteriores y son otra cosa: no entran aquí. Se corta en la primera.
     La columna "Suspensos" de la hoja tampoco sirve: suma las dos cosas. */
  let fin = iSus;
  for (let c = 2; c < iSus; c++) {
    if (/\s[1-4]º$/.test(cab[c])) { fin = c; break; }
  }
  const alumnos = {};
  for (let f = 1; f < valores.length; f++) {
    const fila = valores[f];
    const nombre = String(fila[0] === null || fila[0] === undefined ? '' : fila[0]).trim();
    if (!nombre) continue;
    const susp = [];
    const todas = [];   // instrucción 45: TODAS las notas del curso (también las aprobadas), para las materias de la ficha
    for (let c = 2; c < fin; c++) {
      const v = fila[c];
      if (esNumero(v) && aNumero(v) < 5) susp.push(cab[c]);
      if (cab[c] && v !== '' && v !== null && v !== undefined) todas.push([cab[c], esNumero(v) ? aNumero(v) : String(v).trim()]);
    }
    const decl = esNumero(fila[iSus]) ? aNumero(fila[iSus]) : susp.length;
    alumnos[normalizar(nombre)] = { lista: susp, n: susp.length, declarado: decl, todas: todas };
  }
  return alumnos;
}

/* BUSCAR A UN ALUMNO EN UNA HOJA DE NOTAS. Añadido en la BD v37.

   Normalmente basta con el nombre, porque las hojas EV ya vienen separadas
   por curso. Pero en el cuaderno de notas hay alumnos a los que les falta el
   SEGUNDO APELLIDO: Séneca escribe "Apellido1 El Apellido2, Nombre" y la hoja pone
   "Apellido1, Nombre". Sin esto, esos alumnos se quedaban sin sus suspensos del
   año pasado y sin sus materias no superadas, y su PIL salía con interrogante.
   Lo encontró Francisco el 8-sep-2026.

   Cómo se busca cuando el nombre exacto no está: mismo nombre de pila, y los
   apellidos de la hoja tienen que ser el principio de los apellidos de Séneca.
   Solo se da por bueno si hay UN ÚNICO candidato en esa hoja. Si hay dos, no
   se coge ninguno: más vale una interrogante que atribuirle a un alumno las
   notas de otro. */
function notaDeAlumno_(mapa, nombre) {
  if (!mapa) return null;
  if (mapa[nombre]) return mapa[nombre];
  const coma = nombre.indexOf(', ');
  if (coma === -1) return null;
  const apellidos = nombre.substring(0, coma);
  const pila = nombre.substring(coma + 2);
  if (!apellidos || !pila) return null;
  let encontrado = null, cuantos = 0;
  for (const k in mapa) {
    const c = k.indexOf(', ');
    if (c === -1) continue;
    if (k.substring(c + 2) !== pila) continue;
    const apCorto = k.substring(0, c);
    if (!apCorto || apellidos.indexOf(apCorto + ' ') !== 0) continue;
    cuantos++;
    encontrado = mapa[k];
    encontrado.nombreEnLaHoja = k;
  }
  return cuantos === 1 ? encontrado : null;
}

/*** ================= EL CUADRO DE LA TRAYECTORIA =================
 *
 * Lo pidió Francisco el 8-sep-2026: "necesitamos algo que nos muestre de una
 * forma muy esquemática la historia ordenada de las matrículas de un alumno,
 * con su decisión de promoción, su número de pendientes... Una especie de
 * cuadro sinóptico que nos diga de una sola pasada la información que tenemos
 * cierta, la que nos falta, la dudosa."
 *
 * Sale en la columna Trayectoria de ALUMNADO, una línea por año académico.
 * LA REFERENCIA TEMPORAL VA SIEMPRE DELANTE, que es como lo quiere leer él.
 * Lo que no se sabe lleva una interrogante, y el veredicto va en la última
 * línea, marcada con una flecha.
 *
 * No calcula nada nuevo: junta en una casilla lo que ya está repartido por
 * seis columnas.
 *
 * BD v47, 9-sep-2026. Lo pidió Francisco: el cuadro ponía "2º" y "aquí", y
 * había que adivinar que eran "2º de la ESO" y "el instituto". Ahora
 * el curso lleva siempre su etapa detrás y el centro se escribe con su nombre.
 * Es lo mismo, escrito para que se entienda sin conocer el sistema por dentro.
 * ======================================================== ***/

/* centroCorto_(centro): ahora en Centro.gs (instrucción 56). */

/* "2º" -> "2º ESO". El curso se escribe siempre con su etapa detrás, para que
   nadie tenga que adivinar de qué segundo se habla. Si el texto ya trae la
   etapa escrita, se deja como está. */
function cursoConEtapa_(curso) {
  const t = String(curso || '').trim();
  if (!t) return SIN_DATO;
  if (/eso|bachiller|primaria/i.test(t)) return t;
  return t + ' ' + ETAPA_ACTUAL;
}

function trayectoria_(d) {
  const L = [];

  /* 1. Primaria. Va primero porque es lo primero en el tiempo. */
  const exp = d.exp;
  if (exp && exp.anoPrimero && exp.anoSexto && exp.repeticiones !== '') {
    L.push(anoAcademico_(exp.anoPrimero) + ' a ' + anoAcademico_(exp.anoSexto) + '  Primaria · ' +
      ((exp.cursosRepetidos || []).length
        ? 'repitió ' + exp.cursosRepetidos.join(', ') + ' de Primaria'
        : 'sin repetir') + ' · expediente');
  } else if (exp && exp.anoSexto) {
    L.push('hasta ' + anoAcademico_(exp.anoSexto) + '  Primaria · expediente incompleto (?)');
  } else if (esNumero(d.repPrim)) {
    const n = aNumero(d.repPrim);
    L.push('Primaria  ' + (n > 0 ? (n + (n === 1 ? ' repetición' : ' repeticiones'))
                                 : 'sin repetir') +
      (d.fuenteP === 'EXPEDIENTE' ? ' · expediente' : ' · estimado por edad (?)'));
  }

  /* 2. Los años de la ESO. Del expediente si lo hay, y si no del histórico de
        este centro, que no ve los años en otros institutos. */
  const filas = [];
  if (d.expSec && d.expSec.porAno) {
    for (const ano in d.expSec.porAno) {
      const x = d.expSec.porAno[ano];
      filas.push({ ano: parseInt(ano, 10), curso: x.curso, centro: x.centro,
                   estado: x.estado, susp: x.suspensos });
    }
  } else if (d.anosESO) {
    const trozos = String(d.anosESO).split(';');
    for (let i = 0; i < trozos.length; i++) {
      const m = trozos[i].trim().match(/^(\d{4})\s*:\s*([1-4]º)$/);
      if (m) filas.push({ ano: parseInt(m[1], 10), curso: m[2], centro: '', estado: '', susp: '' });
    }
  }
  filas.sort(function (x, y) { return x.ano - y.ano; });

  /* 3. El hueco que no explica nadie, delante del primer año que conocemos. */
  if (filas.length && esNumero(d.sinLocalizar) && aNumero(d.sinLocalizar) > 0) {
    const n = aNumero(d.sinLocalizar);
    L.push('antes de ' + anoAcademico_(filas[0].ano) + '  ? · falta ' + n +
           (n === 1 ? ' año' : ' años') + ' que nada explica');
  }

  const ultimo = filas.length ? filas[filas.length - 1].ano : 0;
  for (let i = 0; i < filas.length; i++) {
    const f = filas[i];
    const partes = [cursoConEtapa_(f.curso), centroCorto_(f.centro)];
    if (f.ano === ultimo) {
      partes.push('en curso');
    } else {
      /* La decisión la dice el expediente. Si no lo hay, se deduce: si al año
         siguiente sigue en el mismo curso, es que repitió. */
      let decision = String(f.estado || '').trim().toLowerCase();
      if (!decision) {
        decision = (filas[i + 1] && filas[i + 1].curso === f.curso) ? 'repite' : 'promociona';
      }
      partes.push(decision === 'repite' ? 'REPITE' : decision);
      let susp = f.susp;
      if (!esNumero(susp) && f.ano === ultimo - 1 && esNumero(d.suspPasado)) susp = d.suspPasado;
      partes.push(esNumero(susp)
        ? (aNumero(susp) + (aNumero(susp) === 1 ? ' suspensa' : ' suspensas'))
        : '? suspensas');
    }
    L.push(anoAcademico_(f.ano) + '  ' + partes.join(' · '));
  }

  /* 4. El veredicto, en la última línea. */
  if (d.aMano) {
    L.push('→ PIL ' + d.pil + ' · lo ha decidido el equipo directivo');
  } else if (d.pil === 'SÍ') {
    L.push('→ PIL SÍ · comprobado');
  } else if (d.pil === PIL_POR_EDAD) {
    L.push('→ PIL SÍ, pero sin comprobar: sale de una cuenta de edad');
  } else if (d.pil === SIN_DATO) {
    L.push('→ PIL ? · falta información para decidirlo');
  } else if (d.pil === 'NO') {
    L.push('→ no es PIL');
  }

  return L.join('\n');
}

/*** ComponerAlumnado.gs ***/
/*** ================= LÓGICA: COMPOSICIÓN ================= ***/
function componerAlumnado(alumnosPorCurso, historial, notasPorCurso, manuales, jefatura, neae, primaria, secundaria) {
  /* Todos los cruces del sistema van por nombre Y curso. Dos alumnos distintos
     pueden llamarse igual: si la clave fuera solo el nombre, los datos de uno se
     aplicarían también al otro. El curso los separa. La columna 3 del historial
     es el curso. */
  const hist = {};
  for (let i = 0; i < historial.length; i++) {
    hist[normalizar(historial[i][0]) + '|' + historial[i][3]] = historial[i];
  }

  /* Respaldo por nombre suelto. Sirve para cuando el histórico está descargado
     de antes que la matrícula y el alumno todavía figura en el curso anterior:
     sin esto se quedaría sin edad, sin repeticiones y sin PIL. Solo se usa
     cuando no hay ninguna duda, es decir cuando ese nombre es único. */
  const histPorNombre = {};
  for (let i = 0; i < historial.length; i++) {
    const nomH = normalizar(historial[i][0]);
    if (!histPorNombre[nomH]) histPorNombre[nomH] = [];
    histPorNombre[nomH].push(historial[i]);
  }
  const enOtroCurso = [];
  const jef = jefatura || {};
  const censo = neae || {};
  const prim = primaria || {};
  const sec = secundaria || {};
  const filas = [], avisos = [];

  /* Qué cursos trae el censo NEAE que se ha descargado. En los cursos que el
     censo cubre, el censo manda: si un alumno no aparece en él, es que no tiene
     NEAE, y su casilla se queda vacía. Si se conservara lo que había, un dato
     equivocado se quedaría escrito para siempre. En los cursos que el censo no
     trae, porque la descarga de Séneca fue solo de un curso, sí se conserva lo
     que hubiera, para no borrar datos buenos. */
  const cursosDelCenso = {};
  for (const kc in censo) {
    if (censo[kc] && censo[kc].curso) cursosDelCenso[censo[kc].curso] = true;
  }
  const cursosConCenso = Object.keys(cursosDelCenso).sort();
  if (cursosConCenso.length) {
    const sinCenso = [];
    for (const cc in alumnosPorCurso) {
      /* Bachillerato no entra en esta cuenta: el censo NEAE todavía no se lee
         para Bachillerato, así que decir que "le falta" sería ruido. */
      if (esBachillerato_(cc)) continue;
      if (!cursosDelCenso[cc]) sinCenso.push(cc);
    }
    if (sinCenso.length) {
      avisos.push({ curso: '', grupo: '', alumno: '',
        aviso: 'El censo NEAE no trae todos los cursos',
        detalle: 'RegAluNEE.csv solo trae fichas de ' + cursosConCenso.join(', ') + '. En ' +
          sinCenso.sort().join(', ') + ' se conserva lo que ya estaba escrito, que puede estar ' +
          'anticuado. Vuelve a descargar de Séneca el censo NEAE con los cuatro cursos y pulsa ' +
          'otra vez el botón para que se recalcule todo.' });
    }
  }
  const todos = [];
  for (const curso in alumnosPorCurso) {
    const lista = alumnosPorCurso[curso];
    for (let i = 0; i < lista.length; i++) todos.push(lista[i]);
  }
  todos.sort(function (a, b) {
    const ka = a.unidad + ' ' + normalizar(a.nombre), kb = b.unidad + ' ' + normalizar(b.nombre);
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  });

  for (let i = 0; i < todos.length; i++) {
    const a = todos[i];
    const v = a.valores;
    const clave = normalizar(a.nombre) + '|' + a.curso;
    const soloNombre = normalizar(a.nombre);
    let h = hist[clave];
    if (!h && histPorNombre[soloNombre] && histPorNombre[soloNombre].length === 1) {
      h = histPorNombre[soloNombre][0];
      enOtroCurso.push(a.nombre + ' (' + a.curso + ')');
    }
    const man = (manuales && manuales[clave]) || ['', '', '', '', '', '', ''];

    /* BACHILLERATO SE VA POR SU CAMINO. Todo lo que viene debajo es la
       maquinaria de la ESO: repeticiones de Primaria, edad teórica, PIL y las
       dos permanencias de la enseñanza obligatoria. En Bachillerato nada de
       eso existe, así que aplicárselo daría números inventados. Sus casillas
       se quedan vacías, que quiere decir "aquí no aplica". Ver
       Bachillerato.gs. */
    if (esBachillerato_(a.curso)) {
      const vb = valoresDeBachillerato_(a, man, censo[clave], cursosDelCenso);
      filas.push(TITULOS_ALUMNADO.map(function (t) {
        return vb[t] === undefined ? '' : vb[t];
      }));
      continue;
    }

    const E = componerAlumnoESO_(a, h, man, clave, soloNombre, { prim: prim, sec: sec, avisos: avisos, notasPorCurso: notasPorCurso });
    const exp = E.exp, expSec = E.expSec;
    let edad = E.edad, repite = E.repite, repESO = E.repESO, repPrim = E.repPrim, fuente = E.fuente, total = E.total, mns = E.mns, sinLocalizar = E.sinLocalizar, cursosESO = E.cursosESO, cursosPrim = E.cursosPrim;
    let pil = E.pil, noPodra = E.noPodra, agotadas = E.agotadas, cursoPasado = E.cursoPasado, repetiaPasado = E.repetiaPasado, suspPasado = E.suspPasado, fuenteESO = E.fuenteESO, baseDelPil = E.baseDelPil;
    if (!a.unidad) {
      avisos.push({ curso: a.curso, grupo: '', alumno: a.nombre, aviso: 'Sin unidad asignada',
        detalle: 'No aparecerá en ningún informe de grupo' });
    }

    /* Las pendientes. En 2º, 3º y 4º salen de las columnas PEND del CSV de
       Séneca, que están siempre: una casilla vacía ahí quiere decir que el
       alumno no debe nada.

       En 1º es distinto. Séneca no trae nada, y las materias que el alumno
       suspendió en 6º de Primaria salen de su expediente, que Francisco va
       descargando uno a uno. Mientras no esté descargado el de un alumno, no
       sabemos si debe algo o no: ahí va la interrogante.

       EXCEPCIÓN, decidida por Francisco el 6-sep-2026: un alumno que REPITE 1º
       no arrastra nada de Primaria. Está volviendo a cursar el año entero, y lo
       que le quedó sale en NO SUPERADAS. Su expediente de Primaria ya se miró
       el curso pasado, cuando llegó al centro. Así que su casilla se queda
       vacía y no pide un expediente que no hace falta descargar. Si aun así el
       expediente está descargado, se muestra lo que diga. */
    let pend = a.pend;
    let pendTexto = pend.length ? (pend.length + ': ' + pend.join(', ')) : '';
    if (a.curso === '1º') {
      if (exp && exp.anoSexto) {
        pend = a.pend.concat(exp.pendientes);
        pendTexto = pend.length ? (pend.length + ': ' + pend.join(', ')) : '';
      } else if (!pend.length && repite !== 'SÍ') {
        pendTexto = SIN_DATO;
      }
    }

    /* Diversificación. En 4º Séneca la marca con los ámbitos. En 1º, 2º y 3º
       Séneca no la trae, así que solo la sabemos por el fichero de Jefatura. */
    /* LA ÚLTIMA PALABRA LA TIENE EL EQUIPO DIRECTIVO. Añadido en la BD v41,
       a petición del director: quiere poder marcar a mano si un alumno es PIL
       o no, cuando no esté de acuerdo con lo que decide el programa.

       Se escribe SÍ o NO en la columna amarilla 'PIL (a mano)' y manda sobre
       todo lo demás, incluida la interrogante. Va también al informe en papel.
       Dejarla vacía quiere decir "decide tú", que es lo normal.

       Solo afecta a la columna PIL. Las otras dos columnas de permanencia
       siguen diciendo lo que dicen los datos: contestan a otras preguntas y no
       son cosa de una decisión. */
    /* A QUIÉN LE HACE FALTA EL EXPEDIENTE DE SECUNDARIA. Descargarlos es un
       trabajo de uno en uno, así que el programa dice exactamente de quién
       merece la pena. Hace falta cuando su trayectoria de ESO no cuadra y el
       histórico de este centro no puede explicarlo:
         - le faltan años que ninguna fuente explica, o
         - no sabemos en qué curso estaba el año pasado, o
         - su PIL se ha quedado en interrogante.
       En 1º no hace falta: no ha estado antes en la ESO. */
    /* Instrucción 109: el aviso vive en AvisosRegla.gs (también lo usa el navegador). */
    const avHaceFalta = avisoHaceFaltaSecundaria_(a, { expSec: !!expSec, cursoPasadoSinDato: cursoPasado === SIN_DATO, sinLocalizar: sinLocalizar, pil: pil });
    if (avHaceFalta) avisos.push(avHaceFalta);

    const decisionAMano = String(man[6] || '').trim().toUpperCase();
    if (decisionAMano === 'SÍ' || decisionAMano === 'SI') {
      pil = 'SÍ';
    } else if (decisionAMano === 'NO') {
      pil = 'NO';
    }

    /* El cuadro de la trayectoria. Se arma al final, cuando ya está todo
       decidido, porque su última línea es el veredicto. */
    const cuadro = trayectoria_({
      exp: exp, expSec: expSec,
      anosESO: h ? h[13] : '',
      repPrim: repPrim, fuenteP: fuente,
      sinLocalizar: sinLocalizar, suspPasado: suspPasado,
      pil: pil, aMano: (decisionAMano === 'SÍ' || decisionAMano === 'SI' || decisionAMano === 'NO')
    });

    const divSeneca = (v['MAT'] === 'ÁMB') || a.diver === true;
    const divJefatura = !!(jef[clave] && jef[clave].div === 'SÍ');
    const diver = divSeneca ? 'SÍ' : (divJefatura ? 'SÍ (solo Jefatura)' : 'NO');

    /* La fila se monta por TÍTULO, no por posición. Así, cambiar el orden de
       las columnas es cambiar solo la lista TITULOS_ALUMNADO, y no hay forma de
       que los datos se descoloquen respecto a los rótulos. */
    const valores = {
      'Alumno/a': a.nombre,
      'Unidad': a.unidad,
      'Curso': a.curso,
      'Repite el curso actual': repite,
      'Curso el año pasado': cursoPasado,
      'Repetía el año pasado': repetiaPasado,
      'Repetía el año pasado (corregido)': man[5] || '',
      'Suspensos el año pasado': suspPasado,
      'Diversificación': diver,
      'OPT': v['OPT'] || '',
      'FR -> ALCT': v['FR -> ALCT'] || '',
      'MAT': v['MAT'] || '',
      'OPC1': v['OPC1'] || '',
      'OPC2': v['OPC2'] || '',
      'OPC3': v['OPC3'] || '',
      'OPC4': v['OPC4'] || '',
      'REL/Atedu': v['REL/Atedu'] || '',
      'MATRÍCULA': v['MATRÍCULA'] || '',
      'Nº asignaturas': v['Nº asignaturas'] === undefined ? '' : v['Nº asignaturas'],
      'Debería tener': v['Debería tener'] === undefined ? '' : v['Debería tener'],
      'Nº pendientes': pend.length ? pend.length : '',
      'Asignaturas pendientes': pendTexto,
      'Edad a 31/12': edad,
      'MAT NO SUP.': mns,
      'Repeticiones en ESO': repESO,
      'Cursos repetidos en ESO': cursosESO,
      'Fuente ESO': fuenteESO,
      'Rep. Primaria (calculado)': repPrim,
      'Cursos repetidos en Primaria': cursosPrim,
      'Fuente Primaria': fuente,
      'Rep. sin localizar': sinLocalizar,
      'Rep. Primaria (corregido)': man[0] || '',
      'Motivo de la corrección': man[1] || '',
      'Repeticiones totales': total,
      'PIL (a mano)': man[6] || '',
      'PIL': pil,
      'No podrá repetir este curso': noPodra,
      'Ha agotado las dos permanencias': agotadas,
      'Trayectoria': cuadro,
      /* NEAE y MEDIDAS Y RECURSOS salen del censo de Séneca. En los cursos que
         el censo trae, el censo manda: quien no aparece en él se queda con la
         casilla vacía, salvo lo corregido en la ficha de la web (instrucción 50:
         vive en `_correcciones`, con quién y cuándo, y se puede quitar). */
      'NEAE': censo[clave] ? censo[clave].neae : (man[2] || ''),
      'MEDIDAS Y RECURSOS': censo[clave] ? censo[clave].medidas : (man[3] || ''),
      'Observaciones': man[4] || '',
      'Base del PIL': baseDelPil
    };
    filas.push(TITULOS_ALUMNADO.map(function (t) {
      return valores[t] === undefined ? '' : valores[t];
    }));
  }
  if (enOtroCurso.length) {
    avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'El histórico va por detrás de la matrícula',
      detalle: enOtroCurso.length + ' alumnos figuran en RegAlum.csv en un curso distinto del que ' +
        'tienen matriculado ahora. He usado su fila del histórico igualmente. Si son muchos, ' +
        'vuelve a descargar RegAlum.csv de Séneca. Por ejemplo: ' + enOtroCurso.slice(0, 5).join('; ') });
  }
  return { filas: filas, avisos: avisos };
}

/*** ComponerAlumnadoESO.gs ***/
/*** ================= LÓGICA: LO QUE SABE LA TABLA DE UN ALUMNO DE ESO (INSTRUCCIÓN 108) =================
 *
 * Partido de ComponerAlumnado.gs (la regla de las 400 líneas) SIN CAMBIAR NI UNA CONDICIÓN: lo que cuenta la fila de un alumno de ESO a partir de su fila del histórico (`h`), los expedientes de Primaria y de
 * Secundaria, las notas del curso pasado y lo corregido en la ficha (`man`). `ctx`: { prim, sec, avisos, notasPorCurso }; los avisos que genera se añaden a `ctx.avisos`. La regla del PIL y sus cuentas
 * viven en PilRegla.gs (común al servidor y al navegador).
 *
 * ======================================================== ***/

function componerAlumnoESO_(a, h, man, clave, soloNombre, ctx) {
  const exp = ctx.prim[clave];                     // su expediente de Primaria, si lo hay
  const expSec = ctx.sec[clave];                   // su expediente de Secundaria, si lo hay
  let edad = '', repite = '', repESO = '', repPrim = '', fuente = '', total = '', mns = '';
  let sinLocalizar = '';
  let cursosESO = SIN_DATO, cursosPrim = SIN_DATO;
  /* Las tres columnas de permanencia. Ver el comentario grande de arriba. */
  let pil = '', noPodra = '', agotadas = '';
  /* De dónde viene el alumno. */
  let cursoPasado = '', repetiaPasado = '', suspPasado = '', repetiaCorregido = false;
  let repetiaBase = '', baseDelPil = '';   // instrucción 108: la columna «Base del PIL» (solo la tienen quienes constan en el histórico)
  let fuenteESO = 'HISTÓRICO';

  if (!h) {
    fuente = 'No consta en el histórico';
    ctx.avisos.push({ curso: a.curso, grupo: a.unidad, alumno: a.nombre,
      aviso: 'No está en el histórico de matrículas', detalle: 'No se pueden calcular sus repeticiones' });
  } else {
    edad = h[4]; repite = h[5]; repESO = h[6]; repPrim = h[7]; fuente = h[8];

    /* Qué cursos de ESO ha repetido. Lo trae el histórico desde la BD v27.
       Si la pestaña HISTORIAL es de una versión anterior, esa columna no
       existe: entonces, si el alumno tiene repeticiones, va la interrogante,
       y si no tiene ninguna la casilla se queda vacía. */
    /* En qué curso estaba el año pasado. Lo trae el histórico desde la
       BD v34. En 1º no puede traerlo: el curso pasado fue 6º de Primaria,
       y eso solo lo dice el expediente. */
    cursoPasado = String(h[11] === null || h[11] === undefined ? '' : h[11]).trim();
    repetiaPasado = String(h[12] === null || h[12] === undefined ? '' : h[12]).trim();

    cursosESO = String(h[10] === null || h[10] === undefined ? '' : h[10]).trim();
    if (!cursosESO) cursosESO = (esNumero(repESO) && aNumero(repESO) > 0) ? SIN_DATO : '';

    /* EL EXPEDIENTE DE SECUNDARIA MANDA SOBRE EL HISTÓRICO. Añadido en la
       BD v42. El histórico solo ve las matrículas de este centro; el
       expediente ve toda la ESO del alumno, en el instituto que sea. Cuando
       está descargado, se usa él para todo lo de Secundaria. Ver
       Secundaria.gs. */
    if (expSec) {
      fuenteESO = 'EXPEDIENTE';
      if (esNumero(expSec.repeticiones)) repESO = aNumero(expSec.repeticiones);
      cursosESO = (expSec.cursosRepetidos || []).join('; ');
      if (!cursosESO) cursosESO = '';
      if (expSec.cursoPasado) {
        cursoPasado = expSec.cursoPasado;
        repetiaPasado = expSec.repetiaPasado || '';
        /* Si el curso pasado es el mismo en el que está ahora, es que lo
           está repitiendo, aunque el año pasado lo cursara en otro centro. */
        if (expSec.cursoPasado === a.curso) repite = 'SÍ';
      }
    }

    /* La ley solo deja repetir una vez en toda la Primaria. Si el número
       estimado por edad se pasa, el año que sobra no puede ser de Primaria:
       se recorta aquí y más abajo se recoge en 'Rep. sin localizar'. Se hace
       también aquí, y no solo al leer el histórico, para que valga aunque la
       pestaña HISTORIAL venga de una versión anterior. */
    repPrim = topeRepPrimaria_(repPrim);

    /* El expediente de Primaria lo dice negro sobre blanco, así que manda
       sobre la estimación por edad. Ver Primaria.gs. */
    if (exp && exp.repeticiones !== '' && exp.repeticiones !== undefined) {
      repPrim = exp.repeticiones;
      fuente = 'EXPEDIENTE';
      /* Un expediente no se recorta: es un hecho. Pero si dice más de una
         repetición en Primaria, algo no encaja con la ley española y hay
         que mirarlo. */
      if (esNumero(repPrim) && aNumero(repPrim) > MAX_REP_PRIMARIA) {
        ctx.avisos.push({ curso: a.curso, grupo: a.unidad, alumno: a.nombre,
          aviso: 'Más de una repetición en Primaria',
          detalle: 'Su expediente dice que repitió ' + repPrim + ' cursos de Primaria (' +
            (exp.cursosRepetidos || []).join(', ') + '), y la ley solo permite uno en toda ' +
            'la etapa. O el alumno estudió parte de Primaria fuera del sistema educativo ' +
            'español, o hay un error en Séneca. He dejado el número que dice el expediente.' });
      }
    }

    /* REPETICIONES SIN LOCALIZAR. Añadido en la BD v32.

       Las dos fuentes que tenemos son incompletas por naturaleza:
       RegAlum.csv solo trae las matrículas DE ESTE CENTRO, y el expediente
       de Primaria solo cuenta lo que pasó en Primaria. Un alumno que
       repitió en otro instituto no sale en ninguna de las dos.

       Pero se ve en la edad. Si el alumno va más años por detrás de lo que
       explican sus repeticiones conocidas, esos años son repeticiones que
       existieron aunque no sepamos dónde. Cuentan para el PIL igual que
       las demás.

       Por qué hace falta esta columna: hasta la BD v31 esos años iban
       dentro de la estimación por edad de las repeticiones de Primaria.
       En cuanto llegaba el expediente de Primaria, la estimación se
       sustituía por el número exacto y esos años DESAPARECÍAN, así que un
       alumno podía dejar de ser PIL sin ningún motivo. Pasó al empezar a
       descargar expedientes de alumnado de 2º, 3º y 4º. */

    /* ================= DE QUÉ NOS FIAMOS (BD v33) =================

       Lo pidió Francisco el 8-sep-2026, y tiene razón: que un alumno vaya
       por detrás de su edad NO demuestra que haya repetido. Puede haberse
       incorporado tarde al sistema educativo español. Hasta la BD v32 el
       programa daba PIL en los dos casos igual, sin decir cuál era.

       Ahora se separa lo que está documentado de lo que es una suposición:

         - Las repeticiones en ESO salen del histórico de Séneca. Son un
           hecho.
         - Las de Primaria son un hecho si vienen del expediente, o si
           Francisco ha escrito el número a mano. Si vienen de la edad, son
           una suposición. Si son cero, no sostienen ningún PIL y da igual.
         - Los años sin localizar son una suposición, SALVO que podamos
           descartar la incorporación tardía. Y eso se puede descartar
           cuando tenemos su expediente completo de Primaria y empezó 1º de
           Primaria en el curso que le tocaba por su fecha de nacimiento:
           entonces estaba aquí desde el principio y los años perdidos son
           repeticiones de verdad, hechas en otro centro. */
    let incorporacionNormal = false;
    if (exp && exp.completo && exp.anoPrimero) {
      const anoNac = anoDeNacimiento_(h[9]);
      if (anoNac && Number(exp.anoPrimero) - anoNac === 6) incorporacionNormal = true;
    }
    /* Instrucción 108: las repeticiones totales y de qué nos fiamos se calculan en PilRegla.gs (`pilTotalesDe_`), que es también lo que usa el navegador para recalcular el PIL al corregir una repetición. */
    const rTotales = pilTotalesDe_({ curso: a.curso, edad: edad, repESO: repESO, repPrim: repPrim, fuenteExpediente: fuente === 'EXPEDIENTE', incorporacionNormal: incorporacionNormal }, man[0]);
    const primaria2 = rTotales.primaria2, totalSeguro = rTotales.totalSeguro;
    sinLocalizar = rTotales.sinLocalizar;
    total = rTotales.total;
    /* Instrucción 109: este aviso y los otros dos que dependen de lo corregido en la ficha viven en AvisosRegla.gs (también los usa el navegador). */
    const avDetras = avisoVaPorDetras_(a, sinLocalizar, incorporacionNormal);
    if (avDetras) ctx.avisos.push(avDetras);

    /* ¿De dónde viene? En 1º el curso pasado fue 6º de Primaria, así que la
       respuesta está en su expediente y no en el histórico de Séneca. */
    if (a.curso === '1º' && repite !== 'SÍ') {
      cursoPasado = '6º de Primaria';
      repetiaPasado = (exp && exp.completo)
        ? ((exp.cursosRepetidos || []).indexOf('6º') !== -1 ? 'SÍ' : 'NO')
        : SIN_DATO;
    } else if (!cursoPasado) {
      /* No estaba en este centro el año pasado. */
      cursoPasado = SIN_DATO;
      repetiaPasado = SIN_DATO;
    } else if (!repetiaPasado) {
      repetiaPasado = SIN_DATO;
    }

    /* LO QUE ESCRIBE FRANCISCO MANDA. Añadido en la BD v40.
       El histórico de Séneca solo trae las matrículas de este centro, así
       que un alumno que repitió el año pasado en otro instituto figura aquí
       como si no lo hubiera repetido. Si Francisco lo averigua, escribe SÍ
       en la columna amarilla y el programa se fía de él. */
    /* Instrucción 108: la regla de lo corregido vive en PilRegla.gs (`pilRepetiaDe_`). Se guarda lo que decía la tabla antes de corregir: el navegador lo necesita para recalcular el PIL al quitar la corrección. */
    repetiaBase = repetiaPasado;
    const rRepetia = pilRepetiaDe_(repetiaPasado, man[5]);
    repetiaPasado = rRepetia.repetiaPasado; repetiaCorregido = rRepetia.repetiaCorregido;

    /* CUÁNTAS SUSPENDIÓ EL AÑO PASADO.
       En 2º, 3º y 4º sale de la hoja EV de su curso del año pasado, columna
       "Suspensos", que suma las del propio curso y las pendientes: son todas
       las materias con evaluación negativa, que es lo que cuenta para
       promocionar. Las hojas ya vienen separadas por curso, así que aquí la
       clave es solo el nombre.
       En 1º el curso pasado fue 6º de Primaria y no hay hoja EV: se usan las
       materias que suspendió en 6º según su expediente. */
    if (expSec && esNumero(expSec.suspensosPasado)) {
      /* El expediente de Secundaria trae las notas de todos los centros, así
         que aquí manda sobre el cuaderno de notas de este instituto. */
      suspPasado = aNumero(expSec.suspensosPasado);
    } else if (a.curso === '1º' && repite !== 'SÍ') {
      suspPasado = (exp && exp.anoSexto) ? (exp.pendientes || []).length : SIN_DATO;
    } else if (cursoPasado && cursoPasado !== SIN_DATO) {
      const notasPasado = ctx.notasPorCurso[cursoPasado];
      const nPasado = notaDeAlumno_(notasPasado, soloNombre);
      if (nPasado && nPasado.nombreEnLaHoja && nPasado.nombreEnLaHoja !== soloNombre) {
        ctx.avisos.push({ curso: a.curso, grupo: a.unidad, alumno: a.nombre,
          aviso: 'Nombre incompleto en el cuaderno de notas',
          detalle: 'En la hoja "EV ' + cursoPasado + ' ESO" figura como "' + nPasado.nombreEnLaHoja +
            '", sin el segundo apellido. He dado por hecho que es el mismo alumno, porque no ' +
            'hay ningún otro que encaje. Si lo corriges en el cuaderno de notas, este aviso ' +
            'desaparece.' });
      }
      suspPasado = (nPasado && esNumero(nPasado.declarado)) ? aNumero(nPasado.declarado) : SIN_DATO;
    } else {
      suspPasado = SIN_DATO;
    }

    /* Las tres columnas de permanencia. Ver el comentario grande de arriba. */

    /* 3. Ha agotado las dos permanencias de la etapa. */
    agotadas = (total !== '' && total >= 2) ? (totalSeguro >= 2 ? 'SÍ' : PIL_POR_EDAD) : 'NO';

    /* 2. No podrá repetir este curso otra vez. Estar repitiéndolo ahora lo
       dice el histórico de Séneca, así que ese caso nunca es una suposición
       aunque el de la etapa sí lo sea. */
    noPodra = (repite === 'SÍ') ? 'SÍ' : agotadas;

    /* La regla del PIL vive en PilRegla.gs (instrucción 64): la usa también la mesa del curso que viene. Aquí solo se escribe el aviso. */
    const rPil = pilDeAlumno_({ curso: a.curso, repite: repite, repetiaPasado: repetiaPasado, repetiaCorregido: repetiaCorregido,
      total: total, totalSeguro: totalSeguro, sinLocalizar: sinLocalizar, suspPasado: suspPasado });
    pil = rPil.pil;
    baseDelPil = pilBaseTexto_(repetiaBase, incorporacionNormal, !!expSec, cursoPasado === SIN_DATO);
    const avPil = avisoPuedeSerPil_(a, rPil.puedeSerPil, suspPasado, sinLocalizar);
    if (avPil) ctx.avisos.push(avPil);

    /* QUÉ cursos de Primaria repitió. Solo lo dice el expediente, y solo
       hay expedientes de alumnado de 1º. Si el alumno no repitió ninguno,
       no hay nada que poner y la casilla va vacía; si repitió pero no
       sabemos cuál, va la interrogante. */
    if (exp && exp.repeticiones !== '' && exp.repeticiones !== undefined) {
      cursosPrim = (exp.cursosRepetidos || []).join(', ');
    } else if (primaria2 === 0) {
      cursosPrim = '';
    } else {
      cursosPrim = SIN_DATO;
    }

    if (repite === 'SÍ') {
      const notas = ctx.notasPorCurso[a.curso];
      /* Las notas ya vienen separadas por curso (notasPorCurso), así que aquí
         la clave es solo el nombre. */
      const n = notaDeAlumno_(notas, soloNombre);
      /* "5 de 2º: FYQ, GEH, LCL" : cuántas son, de qué curso, y cuáles.
         Lleva el curso para que no se confunda con las pendientes.
         Los dos puntos ocupan menos que la raya larga, y en estas columnas
         cada punto de ancho se nota. */
      if (n) mns = n.n ? (n.n + ' de ' + a.curso + ': ' + n.lista.join(', ')) : '';
      else {
        /* Repite, pero no sabemos qué suspendió: eso no es lo mismo que no
           deber nada, así que va la interrogante. */
        mns = SIN_DATO;
        ctx.avisos.push({ curso: a.curso, grupo: a.unidad, alumno: a.nombre,
          aviso: 'Repetidor sin notas del curso pasado',
          detalle: 'No aparece en la pestaña EV de su curso. En el informe sale "' +
                   SIN_DATO + '" en vez de quedarse en blanco.' });
      }
    }
    if (h[2] && a.unidad && normalizar(h[2]) !== normalizar(a.unidad)) {
      ctx.avisos.push({ curso: a.curso, grupo: a.unidad, alumno: a.nombre, aviso: 'Unidad distinta en el histórico',
        detalle: 'Matrícula: ' + a.unidad + ' / Histórico: ' + h[2] });
    }
  }
  return { exp: exp, expSec: expSec, edad: edad, repite: repite, repESO: repESO, repPrim: repPrim, fuente: fuente, total: total, mns: mns, sinLocalizar: sinLocalizar, cursosESO: cursosESO, cursosPrim: cursosPrim,
    pil: pil, noPodra: noPodra, agotadas: agotadas, cursoPasado: cursoPasado, repetiaPasado: repetiaPasado, suspPasado: suspPasado, repetiaCorregido: repetiaCorregido, fuenteESO: fuenteESO, baseDelPil: baseDelPil };
}

/*** LeerFicheros.gs ***/
/*** ================= LECTURA FILTRADA (para ficheros grandes) ================= ***/
function textoATablaFiltrada(texto, nombres) {
  texto = texto.replace(/^﻿/, '');
  const lineas = texto.split(/\r?\n/);
  let primeraIdx = -1;
  for (let i = 0; i < lineas.length; i++) { if (lineas[i].trim()) { primeraIdx = i; break; } }
  if (primeraIdx === -1) return [];
  const primera = lineas[primeraIdx];
  const sep = (primera.split(';').length - 1) > (primera.split(',').length - 1) ? ';' : ',';
  const cab = partirLineaCsv(primera, sep);
  const cabN = cab.map(normalizar);
  const idx = [], titulos = [];
  for (let n = 0; n < nombres.length; n++) {
    const i = cabN.indexOf(normalizar(nombres[n]));
    if (i !== -1) { idx.push(i); titulos.push(cab[i]); }
  }
  const tabla = [titulos];
  for (let i = primeraIdx + 1; i < lineas.length; i++) {
    if (!lineas[i].trim()) continue;
    const campos = partirLineaCsv(lineas[i], sep);
    const fila = [];
    for (let k = 0; k < idx.length; k++) fila.push(campos[idx[k]] === undefined ? '' : campos[idx[k]]);
    tabla.push(fila);
  }
  return tabla;
}

function textoDeArchivo(archivo) {
  const blob = archivo.getBlob();
  let texto = blob.getDataAsString('UTF-8');
  if (texto.indexOf('�') !== -1) texto = blob.getDataAsString('ISO-8859-1');
  return texto;
}

/* Los ficheros de matrícula de BACHILLERATO que hay en la carpeta.
   buscarCsvsMatricula() los descarta para no leerlos como si fueran de la ESO,
   pero descartar algo en silencio es justo lo que no se debe hacer: Francisco
   los habrá dejado ahí a propósito y tiene que ver que el programa los ha
   encontrado y que todavía no los usa. Devuelve solo los nombres. */
function ficherosDeBachillerato_() {
  const nombres = [];
  const listas = ficherosPorCarpeta_();
  for (let c = 0; c < listas.length; c++) {
    const ficheros = listas[c];
    for (let i = 0; i < ficheros.length; i++) {
      const n = ficheros[i].getName();
      if (!/\.csv$/i.test(n)) continue;
      if (normalizar(n).indexOf('matomcmatr') !== 0) continue;
      if (n.indexOf(cursoEscolar_()) === -1) continue;
      if (normalizar(n).indexOf('bach') === -1) continue;
      if (nombres.indexOf(n) === -1) nombres.push(n);
    }
  }
  return nombres;
}

function buscarCsvsMatricula() {
  const encontrados = {};
  const listas = ficherosPorCarpeta_();
  for (let c = 0; c < listas.length; c++) {
    const ficheros = listas[c];
    for (let i = 0; i < ficheros.length; i++) {
      const f = ficheros[i];
      const n = f.getName();
      /* LOS CSV DE BACHILLERATO SE DESCARTAN AQUÍ, A PROPÓSITO.
         Se llaman igual que los de la ESO y también llevan un "1º" o un "2º"
         en el nombre; sin descartarlos se leerían como si fueran de la ESO y,
         al quedarse solo con el MÁS RECIENTE de cada curso, sustituirían a los
         de la ESO sin que nadie se enterase. Van aparte (Bachillerato.gs).
         Instrucción 144: qué es cada fichero lo dice identidadMatricula_
         (IdentidadFichero.gs), la misma regla para ESO y Bachillerato. */
      const id = identidadMatricula_(n);
      if (!id || id.etapa !== 'ESO') continue;
      const curso = id.curso;
      if (!encontrados[curso] || f.getLastUpdated().getTime() > encontrados[curso].getLastUpdated().getTime()) {
        encontrados[curso] = f;
      }
    }
    /* Tampoco se para al completar los cuatro cursos: puede que en la carpeta
       de descargas haya uno más nuevo que el que ya está ordenado. */
  }
  return encontrados;
}

function libroDeNotas() {
  try {
    const idNotas = centroIdNotas_();
    const l = idNotas ? SpreadsheetApp.openById(idNotas) : null;
    if (l) return l;
  } catch (e) { /* seguimos buscando por nombre */ }
  const listas = ficherosPorCarpeta_();
  for (let c = 0; c < listas.length; c++) {
    const ficheros = listas[c];
    for (let i = 0; i < ficheros.length; i++) {
      const f = ficheros[i];
      if (f.getMimeType() !== MimeType.GOOGLE_SHEETS) continue;
      if (normalizar(f.getName()).indexOf('propuesta') !== -1) return SpreadsheetApp.openById(f.getId());
    }
  }
  return null;
}

/*** ================= CÓMO SE AVISA AL TERMINAR =================
 *
 * Antes se usaba un cuadro de diálogo que había que aceptar. El 6-sep-2026 ese
 * cuadro dejó de poder mostrarse: Google respondía "El motor de JavaScript ha
 * notificado un error inesperado. Código de error: INTERNAL", y como el script
 * se queda esperando a que alguien pulse Aceptar, la ejecución quedaba
 * "En pausa" para siempre aunque el trabajo ya estuviera hecho.
 *
 * Desde BD v15 no se usa ningún cuadro que haya que aceptar. El resumen se
 * escribe en la pestaña RESUMEN y se anuncia con un aviso flotante, que no
 * detiene nada. Un clic menos por operación.
 * ======================================================== ***/
const HOJA_RESUMEN = 'RESUMEN';

function avisar_(titulo, texto) {
  const libro = libroActivo_();
  const lineas = String(texto === null || texto === undefined ? '' : texto).split('\n');
  try {
    let hoja = libro.getSheetByName(HOJA_RESUMEN);
    if (!hoja) hoja = libro.insertSheet(HOJA_RESUMEN, 0);
    hoja.clear();
    hoja.getRange(1, 1).setValue(titulo).setFontWeight('bold').setFontSize(13);
    hoja.getRange(2, 1).setValue('Terminado el ' + new Date().toLocaleString('es-ES'))
        .setFontStyle('italic');
    const filas = [];
    for (let i = 0; i < lineas.length; i++) filas.push([lineas[i]]);
    if (filas.length) hoja.getRange(4, 1, filas.length, 1).setValues(filas);
    hoja.setColumnWidth(1, 620);
    libro.setActiveSheet(hoja);
  } catch (e) { /* si no se puede escribir la pestaña, al menos sale el aviso */ }
  try { libro.toast(titulo, 'Terminado. Míralo en la pestaña ' + HOJA_RESUMEN, 20); }
  catch (e) { /* sin interfaz, tampoco pasa nada */ }
}

/*** IdentidadFichero.gs ***/
/* Instrucción 144 (docs/CADA-ALUMNO-UNA-SOLA-VEZ.md): un fichero de matrícula de Séneca se reconoce por lo que ES
   (etapa, curso y, en Bachillerato, modalidad), no por cómo esté escrito su nombre. Dos ficheros con la misma identidad
   son el mismo fichero y solo se lee el más reciente. Lo usan buscarCsvsMatricula (ESO) y ficherosBachilleratoPorCurso_. */

/* { etapa: 'ESO' | 'BACH', curso: '2º' | '2º BACH', modalidad: '' | MODALIDAD_*, clave } o null si no es de matrícula.
   Vale cualquier forma del nombre: «MatOMCMatr2ºBACH-c-26-27», «MatOMCMatr 2º BACH-c 26-27», … La clave de un fichero
   de Bachillerato cuya modalidad no sale del nombre queda vacía: quien llama la completa abriendo la cabecera. */
function identidadMatricula_(nombre) {
  const n = String(nombre || '');
  if (!/\.csv$/i.test(n)) return null;
  const nn = normalizar(n);
  if (nn.indexOf('matomcmatr') !== 0) return null;
  if (n.indexOf(cursoEscolar_()) === -1) return null;
  if (nn.indexOf('bach') === -1) {
    const m = n.match(/([1-4])\s*º/);
    if (!m) return null;
    return { etapa: 'ESO', curso: m[1] + 'º', modalidad: '', clave: 'ESO|' + m[1] + 'º' };
  }
  const mc = n.match(/^[^0-9]*([12])\s*º/);
  if (!mc) return null;
  const curso = mc[1] + 'º BACH';
  const mm = n.match(/bach[^a-z0-9]*([ch])(?:[^a-z0-9]|$)/i);
  const modalidad = !mm ? '' : (mm[1].toLowerCase() === 'c' ? MODALIDAD_CIENCIAS : MODALIDAD_HUMANIDADES);
  return { etapa: 'BACH', curso: curso, modalidad: modalidad, clave: modalidad ? 'BACH|' + curso + '|' + modalidad : '' };
}

/* Lo que hay en la carpeta, agrupado por identidad: { clave: { hay, leido, sinLeer, nombres } }, solo cifras y nombres de
   fichero. `leidos` son las claves que los lectores de verdad han tomado. Sirve a la comprobación `ficheros-una-copia`. */
function inventarioCopiasMatricula_() {
  const grupos = {};
  const listas = ficherosPorCarpeta_();
  for (let c = 0; c < listas.length; c++) {
    for (let i = 0; i < listas[c].length; i++) {
      const id = identidadMatricula_(listas[c][i].getName());
      if (!id) continue;
      const k = id.clave || ('BACH|' + id.curso + '|sin modalidad');
      grupos[k] = grupos[k] || { hay: 0, nombres: [] };
      grupos[k].hay++;
      if (grupos[k].nombres.indexOf(listas[c][i].getName()) === -1) grupos[k].nombres.push(listas[c][i].getName());
    }
  }
  const leidos = {};
  const eso = buscarCsvsMatricula();
  Object.keys(eso).forEach(function (cu) { leidos['ESO|' + cu] = 1; });
  const bac = ficherosBachilleratoPorCurso_();
  Object.keys(bac).forEach(function (cu) {
    bac[cu].forEach(function (m) {
      const k = m.deNombre ? 'BACH|' + cu + '|' + m.deNombre : 'BACH|' + cu + '|sin modalidad';
      leidos[k] = (leidos[k] || 0) + 1;
    });
  });
  Object.keys(grupos).forEach(function (k) {
    grupos[k].leido = leidos[k] || 0;
    grupos[k].sinLeer = Math.max(0, grupos[k].hay - grupos[k].leido);
  });
  return grupos;
}

/*** PiezasAlumnado.gs ***/
/*** ================= BOTÓN 1: HISTÓRICO ================= ***/
function cargarHistorico() {
  const archivo = buscarCsv('RegAlum');
  if (!archivo) {
    avisar_('No he encontrado el histórico',
      'No hay ningún fichero que empiece por "RegAlum" ni en la carpeta de datos ni en la de arriba.');
    return;
  }
  let res;
  try {
    const tabla = textoATablaFiltrada(textoDeArchivo(archivo),
      ['Alumno/a', 'Nº Id. Escolar', 'Curso', 'Unidad', 'Año de la matrícula',
       'Edad a 31/12 del año de matrícula', 'Estado Matrícula', 'Fecha de nacimiento']);
    res = calcularHistorial(tabla);
    /* Instrucción 45: la misma lectura recuerda el histórico de cursos de cada alumno (Historico.gs) para la ficha. */
    try {
      paqueteGuardar_('regalum', 'historico', archivo.getId() + '|' + archivo.getLastUpdated().getTime(),
        historicoRegAlumDeTabla_(tabla));
    } catch (e2) { /* sin caché, la ficha lo calcula al actualizar: no pasa nada */ }
  } catch (e) {
    avisar_('No he podido leer el histórico', e.message);
    return;
  }

  escribirHojaHistorial_(res.filas, 'Origen: ' + archivo.getName() + '. Año de matrícula más reciente: ' + res.ano);
  /* No se ajusta el ancho aquí: arreglarFormatoDeTodo_ (Formato.gs) le pone a
     esta pestaña un ancho fijo por columna justo después, así que ajustarlo
     antes solo tardaba tiempo para nada. Ver el comentario grande al principio
     de Formato.gs. */

  /* AQUÍ NO SE LE PIDE A NADIE QUE PULSE NADA. Este aviso decía "Ahora pulsa
     2. Construir la tabla ALUMNADO", que era el segundo de los tres botones de
     entonces. Ese botón ya no existe desde la BD v15, y además esta función se
     llama DENTRO de "1. Actualizar los datos" (Panel.gs), así que el cartel
     salía a media ejecución mandando pulsar algo que no está. Lo vio Francisco
     el 10-sep-2026 mirando la pantalla mientras el programa trabajaba.
     Es un cartel de paso: la pestaña RESUMEN se reescribe entera al terminar. */
  avisar_('Histórico cargado (' + VERSION + ')',
    'Fichero: ' + archivo.getName() + '\nAño más reciente: ' + res.ano +
    '\nAlumnos de ESO matriculados ese año: ' + res.filas.length);
}

/* Escribe la pestaña HISTORIAL con las filas dadas (instrucción 91: la usan `cargarHistorico` y la tabla desde la ficha). `origen`: lo que dice la primera línea de dónde sale. */
function escribirHojaHistorial_(filas, origen) {
  const hoja = hojaPlana_(HOJA_HISTORIAL, TITULOS_HISTORIAL.length);   // instrucción 83: sin pintar
  hoja.getRange(1, 1).setValue('Histórico de matrículas. ' + origen +
    '. Actualizado: ' + new Date().toLocaleString('es-ES'))
    .setFontStyle('italic');
  hoja.getRange(2, 1, 1, TITULOS_HISTORIAL.length).setValues([TITULOS_HISTORIAL]).setFontWeight('bold');
  if (filas.length) hoja.getRange(3, 1, filas.length, TITULOS_HISTORIAL.length).setValues(filas);
  hoja.setFrozenRows(2);
  hoja.volcar();
}

/*** ================= LAS PIEZAS: LO QUE SALE DE LEER LOS FICHEROS (INSTRUCCIÓN 90) =================
 *
 * docs/NUCLEO-BD-2-LA-TABLA-EN-SOMBRA.md, punto 3.1. Los pasos que leen los ficheros de Séneca (el histórico, los listados de matrícula, el censo NEAE y los expedientes) viven aquí y devuelven sus
 * PIEZAS: `historial`, `porCurso`, `N` (censo), `P` (Primaria) y `S` (Secundaria), con los avisos de cada una y el resumen. `construirAlumnado` (ConstruirAlumnado.gs) las usa y sigue con lo demás.
 * FichaTabla.gs fabrica las mismas piezas desde la ficha del Centro de datos. Lo que viene después de las piezas (componer, comprobar la matrícula) no sabe de dónde salieron.
 *
 * Devuelve `{ parada: true }` si hay que parar (falta el histórico o los listados no son el informe de matrícula; el aviso ya está dado), o
 * `{ historial, porCurso, cursosEso (los cursos de ESO con listado), N, P, S, avisosMatricula, resumen }`; los avisos de N, S y P van dentro de cada una (`N.avisos`, `S.avisos`, `P.avisos`).
 * ======================================================== ***/
function piezasDeLosFicheros_() {
  paso_('historico-hoja');   // instrucción 81: un reloj por paso (ActualizacionPasos.gs); cada paso dura hasta la marca siguiente
  const libro = libroActivo_();

  let hHist = libro.getSheetByName(HOJA_HISTORIAL);
  if (!hHist || hHist.getLastRow() < 3) {
    avisar_('Falta el histórico', 'Antes tienes que pulsar "1. Leer el histórico de matrículas".');
    return { parada: true };
  }

  /* Una pestaña HISTORIAL hecha con una versión anterior no trae algunas
     columnas, y esos datos solo están en RegAlum.csv. Se relee el histórico
     una vez y ya queda. */
  const COLS_QUE_OBLIGAN_A_RELEER = ['Cursos repetidos en ESO', 'Curso el año pasado',
                                     'Repetía el año pasado', 'Años en la ESO'];
  try {
    const titulosH = hHist.getRange(2, 1, 1, hHist.getLastColumn()).getValues()[0].map(normalizar);
    let falta = false;
    for (let q = 0; q < COLS_QUE_OBLIGAN_A_RELEER.length; q++) {
      if (titulosH.indexOf(normalizar(COLS_QUE_OBLIGAN_A_RELEER[q])) === -1) falta = true;
    }
    if (falta) {
      cargarHistorico();
      hHist = libro.getSheetByName(HOJA_HISTORIAL);
      if (!hHist || hHist.getLastRow() < 3) {
        avisar_('Falta el histórico', 'No he podido releer RegAlum.csv.');
        return { parada: true };
      }
    }
  } catch (e) { /* si no se puede mirar, se sigue con lo que haya */ }

  /* Se lee lo que haya y se rellena el resto, en vez de reventar. */
  const anchoHist = Math.min(TITULOS_HISTORIAL.length, Math.max(1, hHist.getLastColumn()));
  const historial = hHist.getRange(3, 1, hHist.getLastRow() - 2, anchoHist).getValues();
  if (anchoHist < TITULOS_HISTORIAL.length) {
    for (let f = 0; f < historial.length; f++) {
      while (historial[f].length < TITULOS_HISTORIAL.length) historial[f].push('');
    }
  }

  paso_('csv-matricula');
  const ficheros = buscarCsvsMatricula();
  const cursos = Object.keys(ficheros);
  if (!cursos.length) {
    avisar_('No hay ficheros de matrícula',
      'No he encontrado ninguno del curso ' + cursoEscolar_() +
      '.\nDeben llamarse MatOMCMatr...' + cursoEscolar_() + '.csv');
    return { parada: true };
  }

  const porCurso = {}, avisos = [], resumen = [];
  const ficherosSinMaterias = [];

  /* EL BACHILLERATO. Va por su cuenta, en Bachillerato.gs, porque sus reglas
     no son las de la ESO. Sus alumnos entran en el mismo montón, con el curso
     escrito "1º BACH" y "2º BACH", así que no pueden confundirse con los de
     1º y 2º de la ESO. */
  paso_('bachillerato');
  const bac = alumnadoDeBachillerato_();
  for (const cb in bac.porCurso) porCurso[cb] = bac.porCurso[cb];
  bac.avisos.forEach(function (x) { avisos.push(x); });
  bac.resumen.forEach(function (x) { resumen.push(x); });
  paso_('csv-matricula');
  for (let i = 0; i < cursos.length; i++) {
    const curso = cursos[i];
    const r = leerMatricula(textoATabla(textoDeArchivo(ficheros[curso])), curso);
    porCurso[curso] = r.alumnos;
    resumen.push(curso + ' ESO: ' + r.alumnos.length + ' alumnos (' + ficheros[curso].getName() + ')');

    /* Si en el CSV no aparece NINGUNA materia de la oferta de este curso, ese
       fichero no es el informe de matrícula. */
    if (!r.conColumna) {
      ficherosSinMaterias.push(curso + ' ESO (' + ficheros[curso].getName() + ')');
    }
    if (r.avisoNombres) avisos.push(r.avisoNombres);
  }

  /* PARADA DE SEGURIDAD. Si en el CSV de un curso no aparece NINGUNA de sus
     asignaturas, ese fichero no es el informe de matrícula: es otro listado de
     Séneca con el mismo nombre. Si siguiéramos, la tabla ALUMNADO se quedaría
     sin optativas, sin religión y sin matemáticas, y la comparación con
     Jefatura sacaría miles de diferencias falsas. Pasó el 7-sep-2026.
     Mejor no actualizar nada y decir qué fichero hay que volver a descargar. */
  if (ficherosSinMaterias.length) {
    avisar_('No he actualizado nada: falta información en los ficheros de matrícula',
      'Estos ficheros no traen las asignaturas:\n\n' + ficherosSinMaterias.join('\n') +
      '\n\nTienen el nombre correcto, pero dentro solo llevan el alumno y su unidad. ' +
      'Son otro listado de Séneca, no el informe de matrícula.\n\n' +
      'Vuelve a descargar de Séneca el informe de matrícula que trae UNA COLUMNA POR ASIGNATURA, ' +
      'déjalo en la carpeta con el mismo nombre, y pulsa otra vez "Actualizar los datos".\n\n' +
      'No he tocado la base de datos: sigue como estaba.');
    return { parada: true };
  }

  /* Cuarta fuente: el censo NEAE de Séneca. Rellena solas las columnas
     NEAE y MEDIDAS Y RECURSOS. Ver NEAE.gs. */
  paso_('neae');
  const N = datosNeae_(historial, 0, 3, TITULOS_HISTORIAL.indexOf('Fecha de nacimiento'));
  

  /* Quinta fuente: los expedientes de Primaria (ahora para cualquier curso).
     Rellenan las pendientes de 6º y las repeticiones. Ver Primaria.gs. */
  paso_('expedientes-primaria');
  const cursosDeAlumno = {};
  for (const c in porCurso) {
    for (let i = 0; i < porCurso[c].length; i++) {
      const nom = normalizar(porCurso[c][i].nombre);
      if (!cursosDeAlumno[nom]) cursosDeAlumno[nom] = [];
      cursosDeAlumno[nom].push(c);
    }
  }
  const P = datosPrimaria_(cursosDeAlumno);
  /* Sexta fuente, opcional: los expedientes de Secundaria. Solo hacen falta
     los del alumnado avisado. Ver Secundaria.gs. */
  paso_('expedientes-secundaria');
  const S = datosSecundaria_(cursosDeAlumno);

  return { parada: false, historial: historial, porCurso: porCurso, cursosEso: cursos, N: N, P: P, S: S, avisosMatricula: avisos, resumen: resumen };
}

/*** ConstruirAlumnado.gs ***/
/*** ================= BOTÓN 2: ALUMNADO ================= ***/
function construirAlumnado() {
  /* Instrucción 91: si el interruptor (FichaInterruptor.gs) dijo «desde la ficha», las piezas salen de la ficha del Centro de datos; si no, de leer los ficheros (PiezasAlumnado.gs). */
  const via = (typeof FICHA_VIA_ !== 'undefined' && FICHA_VIA_ && FICHA_VIA_.desdeFicha && FICHA_VIA_.fab) ? FICHA_VIA_ : null;
  const pz = via ? fichaPiezasDeLaFicha_(via) : piezasDeLosFicheros_();   // instrucción 90: los pasos que leen los ficheros, en PiezasAlumnado.gs
  if (pz.parada) return false;
  const libro = libroActivo_();
  const historial = pz.historial, porCurso = pz.porCurso, cursos = pz.cursosEso, N = pz.N, P = pz.P, S = pz.S, resumen = pz.resumen;
  const avisos = pz.avisosMatricula.slice();

  paso_('libro-notas');
  /* Instrucción 84: el cuaderno de notas se lee solo si ha cambiado desde la última vez (ActualizacionMemoria.gs). */
  const leidoNotas = notasDelCuaderno_(cursos);
  const notas = leidoNotas.notas;
  leidoNotas.avisos.forEach(function (x) { avisos.push(x); });

  /* Tercera fuente: el reparto definitivo de la mesa de agrupamiento, no ya
     el Excel de Jefatura (instrucción 12, docs/FASE-1-WEB.md: adiós al Excel
     «AGRUPAMIENTOS»). jefaturaDesdeModelo_ (JefaturaModelo.gs) da la misma
     forma que daba leerJefatura_, así que emparejarConJefatura_ (Jefatura.gs)
     sigue sirviendo igual: como los nombres ya vienen de la propia BD, el
     emparejamiento sale siempre exacto. */
  /* Instrucción 28: antes de leer el modelo, el Excel de Jefatura (si existe) lo pone al día. */
  paso_('excel-jefatura-1');
  let sincro = { avisos: [] };
  try { sincro = jefaturaSincronizarExcel_(); }
  catch (e) {
    sincro.avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'No he podido releer el Excel de Jefatura',
      detalle: e.message });
  }
  paso_('modelo-mesa');
  const J = jefaturaDesdeModelo_();
  J.avisos = J.avisos.concat(sincro.avisos);
  paso_('emparejar');
  const alumnosSenecaTodos = [];
  for (const c in porCurso) {
    for (let i = 0; i < porCurso[c].length; i++) alumnosSenecaTodos.push(porCurso[c][i]);
  }
  const EMP = emparejarConJefatura_(alumnosSenecaTodos, J.alumnos);
  const jefPorNombre = EMP.jefPorSeneca;
  for (let i = 0; i < J.avisos.length; i++) {
    const a = J.avisos[i];
    if (typeof a === 'string') avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'Fichero de Jefatura', detalle: a });
    else avisos.push(a);
  }

  const avisosComunes = avisos.slice(pz.avisosMatricula.length);   // los de las notas y los de Jefatura: los mismos vengan las piezas de donde vengan
  /* Los avisos del censo, de los expedientes de Secundaria y de los de Primaria, en este orden. */
  for (let i = 0; i < N.avisos.length; i++) avisos.push(N.avisos[i]);
  for (let i = 0; i < S.avisos.length; i++) avisos.push(S.avisos[i]);
  for (let i = 0; i < P.avisos.length; i++) avisos.push(P.avisos[i]);

  /* LA MATRÍCULA, COMPROBADA. Una sola cuenta por alumno: lo que debe tener
     según la oferta del centro y lo que quiere Jefatura, contra lo que tiene
     en Séneca. Deja en cada alumno su columna MATRÍCULA y devuelve las filas
     de la pestaña MATRÍCULA. Ver Matricula.gs. */
  paso_('comprobar-matriculas');
  const nAvisosAntes = avisos.length;
  const cursosJef = {};
  for (let i = 0; i < J.alumnos.length; i++) if (J.alumnos[i].curso) cursosJef[J.alumnos[i].curso] = true;
  let M = { filas: [], eso: 0, bac: 0 };
  try { M = comprobarMatriculas_(porCurso, jefPorNombre, cursosJef); }
  catch (e) { avisos.push({ curso: '', grupo: '', alumno: '',
    aviso: 'No he podido comprobar las matrículas', detalle: e.message }); }
  try {
    if (leerOferta_().sembrada) {
      avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'He escrito la pestaña OFERTA',
        detalle: 'Es la única lista de materias del sistema, sacada de las hojas de oferta educativa ' +
          'del centro. Repásala: a partir de ahora manda lo que ponga ahí. La pestaña MATERIAS ' +
          'OBLIGATORIAS ya no se usa y se puede borrar.' });
    }
  } catch (e) { /* si no se puede mirar, no pasa nada */ }

  paso_('componer-tabla');
  const manuales = leerManualesAlumnado(libro);
  correccionesAvisos_().forEach(function (a) { avisos.push(a); });
  const avisosPosteriores = avisos.slice(nAvisosAntes);   // el error de la matrícula, la oferta sembrada y las correcciones: iguales por los dos caminos
  const R = componerAlumnado(porCurso, historial, notas, manuales, jefPorNombre, N.porNombre,
                             P.porNombre, S.porNombre);
  R.avisos.forEach(function (a) { avisos.push(a); });

  /* Instrucción 90: la sombra. La tabla que vale y se escribe es la de arriba; esta monta la misma desde la ficha del Centro de datos, en memoria, y cuenta en qué se diferencian
     (FichaSombra.gs). No escribe nada y, pase lo que pase, la actualización sigue. */
  if (!via) fichaSombraDeLaTabla_({ avisosAlComponer: avisos.slice(0, avisos.length - R.avisos.length), R: R, M: M, porCurso: porCurso, historial: historial, N: N, P: P, S: S, notas: notas,
    manuales: manuales, J: J, cursosJef: cursosJef, avisosComunes: avisosComunes, avisosPosteriores: avisosPosteriores });

  paso_('escribir-alumnado');
  escribirAlumnado(R.filas);
  paso_('avisos-nombres-repetidos');

  /* La pestaña NEAE deja ver a quién se ha asignado cada ficha del censo,
     que en el fichero de Séneca solo viene con las iniciales. */
  const ind = indicesDeAlumnado_(R.filas);
  const unidadesPorNombre = ind.unidadesPorNombre, enAlumnado = ind.enAlumnado;
  avisosNombresRepetidos_(ind.mismoNombre).forEach(function (a) { avisos.push(a); });
  paso_('escribir-neae');
  try { escribirNeae_(N.porNombre, unidadesPorNombre, N.nombre); }
  catch (e) { avisos.push({ curso: '', grupo: '', alumno: '',
    aviso: 'No he podido escribir la pestaña NEAE', detalle: e.message }); }

  /* Un expediente de Primaria cuyo nombre de fichero no case con ningún alumno
     de la tabla no sirve de nada, y hay que verlo. Casi siempre es una errata
     en el nombre del fichero. */
  const sinAlumno = avisosExpedientesSinAlumno_(P, enAlumnado);
  const expSinAlumno = sinAlumno.n;
  sinAlumno.avisos.forEach(function (a) { avisos.push(a); });
  if (via) via.fab.avisosSinAlumno.forEach(function (a) { avisos.push(a); });   // instrucción 91: los expedientes sin alumno que la ficha ya trae avisados
  paso_('escribir-secundaria');
  try { escribirSecundaria_(S.porNombre, unidadesPorNombre, enAlumnado); }
  catch (e) { avisos.push({ curso: '', grupo: '', alumno: '',
    aviso: 'No he podido escribir la pestaña SECUNDARIA', detalle: e.message }); }

  paso_('escribir-primaria');
  try { escribirPrimaria_(P.porNombre, unidadesPorNombre, enAlumnado); }
  catch (e) { avisos.push({ curso: '', grupo: '', alumno: '',
    aviso: 'No he podido escribir la pestaña PRIMARIA', detalle: e.message }); }

  /* Instrucción 45: el histórico de cursos y las materias de cada año de cada alumno, para la ficha
     (pestañas ocultas _historico y _materias del cuaderno central; HistoricoActualizar.gs). */
  paso_('historico-ficha');
  try { escribirHistoricoYMaterias_(porCurso, notas, S.porNombre, historial); }
  catch (e) { avisos.push({ curso: '', grupo: '', alumno: '',
    aviso: 'No he podido guardar el histórico y las materias de la ficha', detalle: e.message }); }

  /* La caché de expedientes de Séneca (Cache.gs) se guarda ya aquí, por si
     construirAlumnado se ejecuta ella sola, y para que un fallo al leerla o
     guardarla pueda salir en esta misma pestaña AVISOS. Panel.gs la vuelve a
     llamar más tarde, justo antes de escribir el panel; si aquí ya se ha
     guardado todo, esa segunda llamada no hace nada. */
  paso_('cache-expedientes');
  guardarCacheDeFicheros_();
  if (avisoDeCacheExpedientes_()) {
    avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Caché de expedientes',
      detalle: avisoDeCacheExpedientes_() });
  }

  paso_('escribir-avisos');
  escribirAvisos(avisos);

  /* La pestaña JEFATURA y DISCREPANCIAS ya no se escriben (instrucción 12,
     punto 4.4): el reparto definitivo se ve en la mesa, y sus diferencias
     con Séneca, en CAMBIOS SÉNECA (MesaCambios.gs, instrucción 9), que hace
     la misma comparación mejor (alumno a alumno, no solo personas y grupos). */
  paso_('escribir-matricula');
  let nMatric = 0;
  try { nMatric = escribirMatricula_(M.filas); try { escribirMatriculaBase_(M); } catch (eBase) { /* sin la base la página no recalcula la matrícula; la tabla no se resiente */ } }
  catch (e) { /* la pestaña se queda como estaba; el aviso ya está arriba */ }

  paso_('resumen-tabla');
  const iPil = TITULOS_ALUMNADO.indexOf('PIL');
  const iNoPodra = TITULOS_ALUMNADO.indexOf('No podrá repetir este curso');
  const iPilE = TITULOS_ALUMNADO.indexOf('Ha agotado las dos permanencias');
  const iMns = TITULOS_ALUMNADO.indexOf('MAT NO SUP.');
  const iPen = TITULOS_ALUMNADO.indexOf('Nº pendientes');
  const iAsi = TITULOS_ALUMNADO.indexOf('Asignaturas pendientes');
  const iCur = TITULOS_ALUMNADO.indexOf('Curso');
  const iRep = TITULOS_ALUMNADO.indexOf('Repite el curso actual');
  const iDiv = TITULOS_ALUMNADO.indexOf('Diversificación');
  const iFue = TITULOS_ALUMNADO.indexOf('Fuente Primaria');
  const iCPr = TITULOS_ALUMNADO.indexOf('Cursos repetidos en Primaria');
  const esPil = function (v) { return String(v).indexOf('SÍ') === 0; };
  const pil = R.filas.filter(function (f) { return esPil(f[iPil]); }).length;
  const noPodra = R.filas.filter(function (f) { return esPil(f[iNoPodra]); }).length;
  const pilEtapa = R.filas.filter(function (f) { return esPil(f[iPilE]); }).length;
  /* De esos, los que salen apoyados en una suposición por edad. */
  const pilPorEdad = R.filas.filter(function (f) {
    return f[iPil] === PIL_POR_EDAD || f[iNoPodra] === PIL_POR_EDAD ||
           f[iPilE] === PIL_POR_EDAD;
  }).length;
  /* Y aquellos de los que no sabemos en qué curso estaban el año pasado,
     casi siempre porque llegaron este año de otro centro. */
  const pilSinSaber = R.filas.filter(function (f) { return f[iPil] === SIN_DATO; }).length;
  /* Los que ha decidido a mano el equipo directivo. */
  const iMano = TITULOS_ALUMNADO.indexOf('PIL (a mano)');
  const pilAMano = R.filas.filter(function (f) { return String(f[iMano]).trim() !== ''; }).length;
  const necesitanSec = avisos.filter(function (a) {
    return a.aviso === 'Hace falta su expediente de Secundaria';
  }).length;
  /* Los que el año pasado no podían repetir pero promocionaron aprobando: por
     eso NO son PIL. Antes de la BD v36 el programa los contaba como PIL. */
  const iSus = TITULOS_ALUMNADO.indexOf('Suspensos el año pasado');
  const iRepPas = TITULOS_ALUMNADO.indexOf('Repetía el año pasado');
  const promocionaronSolos = R.filas.filter(function (f) {
    return f[iRepPas] === 'SÍ' && f[iRep] !== 'SÍ' && esNumero(f[iSus]) &&
           aNumero(f[iSus]) <= MAX_SUSPENSOS_PROMOCION;
  }).length;
  const mns = R.filas.filter(function (f) { return f[iMns] !== '' && f[iMns] !== SIN_DATO; }).length;
  const pen = R.filas.filter(function (f) { return f[iPen] !== ''; }).length;
  const div = R.filas.filter(function (f) { return String(f[iDiv]).indexOf('SÍ') === 0; }).length;
  const porEdad = R.filas.filter(function (f) { return f[iFue] === 'EDAD'; }).length;
  /* Alumnado que va por detrás de su edad más de lo que explican las
     repeticiones que conocemos. Casi siempre repitió en otro centro. */
  const iSin = TITULOS_ALUMNADO.indexOf('Rep. sin localizar');
  const sinLocalizar = R.filas.filter(function (f) {
    return esNumero(f[iSin]) && aNumero(f[iSin]) > 0;
  }).length;
  /* Los que están repitiendo ahora y es su PRIMERA repetición: son PIL de este
     curso, pero todavía les queda una permanencia para un curso posterior.
     Es justo el grupo en el que se separan las dos lecturas del PIL. */
  const soloEsteCurso = R.filas.filter(function (f) {
    return esPil(f[iNoPodra]) && !esPil(f[iPilE]);
  }).length;
  /* Alumnado del que sabemos que repitió en Primaria pero no de qué curso. */
  const primariaSinCurso = R.filas.filter(function (f) { return f[iCPr] === SIN_DATO; }).length;
  /* Los repetidores de 1º no necesitan expediente de Primaria, así que no
     cuentan ni como pendientes de descargar ni como interrogantes. */
  const enPrimero = R.filas.filter(function (f) {
    return f[iCur] === '1º' && f[iRep] !== 'SÍ';
  }).length;
  const repetidores1 = R.filas.filter(function (f) {
    return f[iCur] === '1º' && f[iRep] === 'SÍ';
  }).length;
  const sinExpediente = R.filas.filter(function (f) {
    return f[iCur] === '1º' && f[iAsi] === SIN_DATO;
  }).length;
  const sinNotas = R.filas.filter(function (f) { return f[iMns] === SIN_DATO; }).length;

  avisar_('Tabla ALUMNADO construida (' + VERSION + ')',
    resumen.join('\n') +
    '\n\nTotal de alumnos: ' + R.filas.length +
    '\n\nLAS TRES COLUMNAS DE PERMANENCIA' +
    '\nPIL, promocionaron por imperativo legal al curso de ahora: ' + pil +
    '   (es la que va al papel)' +
    '\nNo podrán repetir este curso otra vez: ' + noPodra +
    '\nHan agotado las dos permanencias de la etapa: ' + pilEtapa +
    '\nRepiten ahora y es su primera vez (por eso se separan las dos últimas): ' + soloEsteCurso +
    '\nSin comprobar, salen "' + PIL_POR_EDAD + '": ' + pilPorEdad +
    '\nCon "' + SIN_DATO + '" en PIL porque falta su curso pasado o sus notas: ' + pilSinSaber +
    '\nDecididos a mano por el equipo directivo: ' + pilAMano +
    '\n\nEXPEDIENTES DE SECUNDARIA' +
    '\nFicheros leídos: ' + S.total + ' de ' + S.ficheros +
    '\nAlumnos que necesitan el suyo (salen en AVISOS): ' + necesitanSec +
    '\nNo son PIL porque promocionaron aprobando: ' + promocionaronSolos +
    '\n\nCon materias no superadas (repetidores): ' + mns +
    '\nCon asignaturas pendientes: ' + pen +
    '\nEn diversificación: ' + div +
    '\nCon censo NEAE: ' + N.total +
    '\n\nEXPEDIENTES DE PRIMARIA' +
    '\nFicheros leídos: ' + P.total + ' de ' + P.ficheros +
    (expSinAlumno ? ' (' + expSinAlumno + ' sin alumno en la tabla)' : '') +
    '\nAlumnos de 1º que necesitan expediente: ' + enPrimero +
    ' (los ' + repetidores1 + ' repetidores de 1º no lo necesitan)' +
    '\nDe esos, ya tienen el suyo: ' + (enPrimero - sinExpediente) +
    '\nTodavía salen con "' + SIN_DATO + '" porque falta su expediente: ' + sinExpediente +
    '\nRepeticiones de Primaria todavía estimadas por edad: ' + porEdad +
    '\nRepitieron en Primaria pero no sabemos qué curso: ' + primariaSinCurso +
    '\nRepeticiones que hubo pero no sabemos dónde (alumnos): ' + sinLocalizar +
    (sinNotas ? '\nRepetidores que salen con "' + SIN_DATO +
                '" porque no aparecen en las notas: ' + sinNotas : '') +
    '\n\nReparto definitivo de la mesa de agrupamiento: ' + J.alumnos.length + ' alumnos' +
    (J.alumnos.length ? '' : ' (todavía sin ningún curso con modelo definitivo)') +
    '\n\nMATRÍCULAS QUE NO CUADRAN EN SÉNECA: ' + nMatric +
    ' (ESO ' + M.eso + ' · Bachillerato ' + M.bac + ')' +
    (nMatric ? '\nMíralas en la pestaña "' + HOJA_MATRICULA + '": qué falta y qué sobra, alumno por alumno.' : '') +
    '\n\nAvisos anotados: ' + avisos.length);

  /* Se ha llegado al final: las pestañas están escritas. Quien la llama
     (Panel.gs) mira este valor para saber si puede seguir con los informes.
     Las paradas de arriba devuelven false. */
  return true;
}

/* leerManualesAlumnado vive ahora en Correcciones.gs (instrucción 50): lee de la pestaña oculta `_correcciones`. */


/*** ================= LOS AVISOS Y LOS ÍNDICES QUE SALEN DE LA TABLA YA COMPUESTA (INSTRUCCIÓN 90) =================
 *
 * Eran un trozo de `construirAlumnado`; ahora son funciones para que la sombra (FichaSombra.gs) saque los mismos avisos de su tabla con el mismo código.
 * ======================================================== ***/

/* Los índices por «nombre normalizado|curso» de las filas de ALUMNADO: la unidad de cada uno, quién está, y los que comparten nombre (por nombre solo). */
function indicesDeAlumnado_(filas) {
  const iNomA = TITULOS_ALUMNADO.indexOf('Alumno/a'), iUniA = TITULOS_ALUMNADO.indexOf('Unidad');
  const iCurA = TITULOS_ALUMNADO.indexOf('Curso');
  const unidadesPorNombre = {}, enAlumnado = {}, mismoNombre = {};
  for (let f = 0; f < filas.length; f++) {
    const k = normalizar(filas[f][iNomA]) + '|' + filas[f][iCurA];
    unidadesPorNombre[k] = filas[f][iUniA];
    enAlumnado[k] = true;
    const soloNom = normalizar(filas[f][iNomA]);
    if (!mismoNombre[soloNom]) mismoNombre[soloNom] = [];
    mismoNombre[soloNom].push(filas[f]);
  }
  return { unidadesPorNombre: unidadesPorNombre, enAlumnado: enAlumnado, mismoNombre: mismoNombre };
}

/* Dos alumnos distintos pueden llamarse igual. El sistema los separa por el curso, así que conviene tenerlos localizados: si algún día coincidieran en el mismo curso,
   el curso ya no bastaría y habría que mirarlos a mano. */
function avisosNombresRepetidos_(mismoNombre) {
  const iNomA = TITULOS_ALUMNADO.indexOf('Alumno/a'), iUniA = TITULOS_ALUMNADO.indexOf('Unidad');
  const iCurA = TITULOS_ALUMNADO.indexOf('Curso');
  const avisos = [];
  for (const nom in mismoNombre) {
    const iguales = mismoNombre[nom];
    if (iguales.length < 2) continue;
    const donde = iguales.map(function (f) { return f[iUniA] || '(sin unidad)'; });
    let mismoCurso = false;
    for (let a = 0; a < iguales.length; a++) {
      for (let b = a + 1; b < iguales.length; b++) {
        if (iguales[a][iCurA] === iguales[b][iCurA]) mismoCurso = true;
      }
    }
    avisos.push({ curso: iguales[0][iCurA], grupo: '', alumno: iguales[0][iNomA],
      aviso: 'Dos alumnos con el mismo nombre',
      detalle: 'Aparece en ' + donde.join(' y en ') + '. ' + (mismoCurso
        ? 'Coinciden en el mismo curso, así que el programa NO los puede distinguir: hay que revisar a mano sus datos.'
        : 'Son cursos distintos, así que el programa los distingue bien y cada uno lleva lo suyo.') });
  }
  return avisos;
}

/* Un expediente de Primaria cuyo nombre de fichero no case con ningún alumno de la tabla no sirve de nada, y hay que verlo. Casi siempre es una errata en el nombre del fichero.
   Devuelve { avisos, n }. */
function avisosExpedientesSinAlumno_(P, enAlumnado) {
  const avisos = [];
  let n = 0;
  for (const k in P.porNombre) {
    if (enAlumnado[k]) continue;
    n++;
    const cursoAviso = k.split('|')[1] || '';
    avisos.push({ curso: cursoAviso, grupo: '', alumno: P.porNombre[k].nombre,
      aviso: 'Expediente de Primaria sin alumno',
      detalle: 'El fichero "' + P.porNombre[k].fichero + '" no corresponde a ningún alumno de la tabla. ' +
               'Comprueba que el nombre del fichero está escrito igual que en Séneca.' });
  }
  return { avisos: avisos, n: n };
}

/*** EscribirAlumnado.gs ***/
function hojaLimpia(nombre, ancho) {
  const libro = libroActivo_();
  let hoja = libro.getSheetByName(nombre);
  if (!hoja) hoja = libro.insertSheet(nombre);
  if (hoja.getMaxColumns() < ancho) hoja.insertColumnsAfter(hoja.getMaxColumns(), ancho - hoja.getMaxColumns());
  const filtro = hoja.getFilter();
  if (filtro) filtro.remove();
  hoja.clear();
  return hoja;
}

function escribirAlumnado(filas) {
  const ancho = TITULOS_ALUMNADO.length;
  const hoja = hojaPlana_(HOJA_ALUMNADO, ancho);   // instrucción 83: sin pintar; el formato de abajo se traga (HojaPlana.gs)
  hoja.getRange(1, 1).setValue('Alumnado de ESO del curso ' + cursoEscolar_() +
    '. Gris: viene de Séneca. Azul: calculado. Las correcciones de repeticiones, PIL, NEAE y medidas, y las observaciones (notas), se escriben en la ficha de la web. ' +
    'Una casilla vacía quiere decir que no hay nada que poner; una "' + SIN_DATO +
    '" quiere decir que ese dato todavía no lo tenemos. ' +
    'LAS TRES COLUMNAS DE PERMANENCIA, en orden de tiempo: "PIL" quiere decir que el alumno ' +
    'está en este curso porque el año pasado ya no podía repetir Y ADEMÁS suspendió más de ' +
    MAX_SUSPENSOS_PROMOCION + ' materias, es decir que promocionó por imperativo legal; es la ' +
    'que va al informe en papel. "No podrá repetir este curso" quiere ' +
    'decir que si suspende en junio pasará de curso igualmente. "Ha agotado las dos ' +
    'permanencias" quiere decir que no puede repetir ningún curso más en toda la enseñanza ' +
    'obligatoria, Primaria y ESO juntas. Son tres preguntas distintas y los tres grupos de ' +
    'alumnos son distintos. Un "' + PIL_POR_EDAD + '" quiere decir que el número en el que se ' +
    'apoya es una suposición sacada de la edad y nadie lo ha comprobado todavía. ' +
    'Actualizado: ' + new Date().toLocaleString('es-ES')).setFontStyle('italic');
  hoja.getRange(2, 1, 1, ancho).setValues([TITULOS_ALUMNADO]).setFontWeight('bold')
      .setHorizontalAlignment('center').setVerticalAlignment('middle').setWrap(true);
  if (filas.length) hoja.getRange(3, 1, filas.length, ancho).setValues(filas);

  /* EL CUADRO DE LA TRAYECTORIA, TAMBIÉN COMO NOTA DEL NOMBRE. Lo pidió
     Francisco: quiere verlo de una sola pasada. Puesto solo en su columna
     habría que ensanchar la fila y la tabla se haría inmanejable, así que el
     mismo texto se copia como nota de la casilla del alumno: se pasa el ratón
     por encima del nombre y sale el cuadro entero, sin mover nada.
     La columna Trayectoria se queda igualmente, para poder filtrar y copiar. */
  const iTray = TITULOS_ALUMNADO.indexOf('Trayectoria');
  if (filas.length && iTray !== -1) {
    const notas = filas.map(function (f) { return [String(f[iTray] || '')]; });
    try { hoja.getRange(3, 1, filas.length, 1).setNotes(notas); }
    catch (e) { /* las notas son un lujo: si fallan, la columna sigue estando */ }
  }

  const calculadas = ['Repite el curso actual', 'Curso el año pasado', 'Repetía el año pasado',
    'Suspensos el año pasado',
    'Diversificación', 'Cursos repetidos en ESO', 'Cursos repetidos en Primaria',
    'Rep. sin localizar', 'Repeticiones totales',
    'PIL', 'No podrá repetir este curso', 'Ha agotado las dos permanencias',
    /* Instrucción 50: se corrigen en la ficha de la web; el cuaderno las repinta. */
    'Rep. Primaria (corregido)', 'Motivo de la corrección', 'Repetía el año pasado (corregido)', 'PIL (a mano)',
    'NEAE', 'MEDIDAS Y RECURSOS', 'Observaciones'];
  /* El color de la cabecera solo tiene tres posibilidades. Se agrupan las
     columnas por color y se pintan con tres llamadas (getRangeList) en vez
     de una por columna. */
  const porColorCabecera = { '#FFF2CC': [], '#DDEBF7': [], '#D9D9D9': [] };
  for (let c = 0; c < ancho; c++) {
    const t = TITULOS_ALUMNADO[c];
    const color = COLS_MANUALES_ALUMNADO.indexOf(t) !== -1 ? '#FFF2CC'
                : (calculadas.indexOf(t) !== -1 ? '#DDEBF7' : '#D9D9D9');
    porColorCabecera[color].push(fmtLetraColumna_(c + 1) + '2');
    if (COLS_MANUALES_ALUMNADO.indexOf(t) !== -1 && filas.length) {
      hoja.getRange(3, c + 1, filas.length, 1).setBackground('#FFF2CC');
    }
  }
  for (const color in porColorCabecera) {
    if (porColorCabecera[color].length) hoja.getRangeList(porColorCabecera[color]).setBackground(color);
  }
  if (filas.length) {
    hoja.getRange(2, 1, filas.length + 1, ancho)
        .setBorder(true, true, true, true, true, true, '#999999', SpreadsheetApp.BorderStyle.SOLID);
    hoja.getRange(3, 3, filas.length, ancho - 2).setHorizontalAlignment('center');
  }
  hoja.setFrozenRows(2);
  hoja.setFrozenColumns(2);
  /* Sin autoResizeColumn: arreglarFormatoDeTodo_ deja un ancho fijo por
     columna al terminar "Actualizar los datos", así que ajustarlo aquí antes
     era trabajo (lento) que se tiraba siempre. */
  hoja.getRange(2, 1, filas.length + 1, ancho).createFilter();
  hoja.volcar();
}

function escribirAvisos(avisos) {
  const hoja = hojaPlana_(HOJA_AVISOS, 7);   // instrucción 83: sin pintar
  const titulos = ['Curso', 'Grupo', 'Alumno/a', 'Aviso', 'Detalle', 'Estado', 'Observaciones'];
  avisos.sort(function (a, b) {
    const ka = a.curso + a.aviso + a.grupo + a.alumno, kb = b.curso + b.aviso + b.grupo + b.alumno;
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  });
  const filas = avisos.map(function (a) { return [a.curso, a.grupo, a.alumno, a.aviso, a.detalle, '', '']; });
  hoja.getRange(1, 1, 1, 7).setValues([titulos]).setFontWeight('bold');
  if (filas.length) hoja.getRange(2, 1, filas.length, 7).setValues(filas);
  hoja.setFrozenRows(1);
  hoja.volcar();
}

/*** HojaPlana.gs ***/
/*** ================= HOJAS SIN PINTAR (INSTRUCCIÓN 83) =================
 *
 * docs/RAPIDA-3-ACTUALIZAR-SIN-PINTAR.md, punto 3.1. «Actualizar los datos» ya no pinta el cuaderno: las pestañas que solo se miran (HISTORIAL, ALUMNADO,
 * NEAE, PRIMARIA, SECUNDARIA, AVISOS, MATRÍCULA, CUADRE, CAMBIOS SÉNECA, PENDIENTES y AVISOS INFORMES) se escriben con sus valores, de una vez, sobre lo que hay, y se
 * vacía solo el contenido de lo que sobra. Todo se mira en la web.
 *
 * `hojaPlana_(nombre, ancho)` hace de `hojaLimpia` (Codigo.gs) para esas pestañas. Devuelve una hoja «de mentira»: lo que se escribe con `setValue` y
 * `setValues` se guarda en memoria y `volcar()` lo escribe de una sola llamada, sobre las filas y columnas que ya hubiera (las que sobran quedan
 * vacías). Cualquier otra orden (colores, bordes, notas, filtro, anchos, congelar, proteger…) se traga sin hacer nada: así las funciones que
 * escribían cada pestaña siguen existiendo, con las mismas filas y las mismas columnas, y no llaman nunca a formato. La pestaña nunca está vacía a
 * mitad de la actualización.
 *
 * UNA SOLA VEZ por pestaña (con una marca guardada), la primera vez que se escribe así, se le quitan el filtro, las notas, la protección, las
 * validaciones y los formatos que dejaron las versiones anteriores. Si no queda tiempo, se hace en la vuelta siguiente.
 *
 * ======================================================== ***/

const PROP_SIN_PINTAR_ = 'SIN_PINTAR_';   // + nombre de la pestaña: ya se le quitó el aspecto viejo

/* Una orden que no hace nada y deja seguir encadenando (`.setFontWeight('bold').setBackground('#fff')`). */
function hojaNada_() {
  const nada = new Proxy(function () {}, {
    get: function (t, p) { return typeof p === 'symbol' ? undefined : nada; },
    apply: function () { return nada; }
  });
  return nada;
}

/* Quita el aspecto que dejaron las versiones anteriores. Nunca lanza. */
function hojaQuitarAspectoUnaVez_(hoja, nombre) {
  const clave = PROP_SIN_PINTAR_ + nombre;
  let props = null;
  try { props = PropertiesService.getDocumentProperties(); if (props.getProperty(clave)) return false; } catch (e) { return false; }
  if (!quedaTiempo_(10)) return false;   // la que no dé tiempo, en la vuelta siguiente
  const probar = function (f) { try { f(); } catch (e) { /* una cosa que no se pueda quitar no estropea lo demás */ } };
  probar(function () { const filtro = hoja.getFilter(); if (filtro) filtro.remove(); });
  probar(function () { const r = hoja.getRange(1, 1, hoja.getMaxRows(), hoja.getMaxColumns()); r.clearFormat(); r.clearNote(); r.clearDataValidations(); });
  probar(function () { hoja.setConditionalFormatRules([]); });
  probar(function () { hoja.getBandings().forEach(function (b) { b.remove(); }); });
  [SpreadsheetApp.ProtectionType.RANGE, SpreadsheetApp.ProtectionType.SHEET].forEach(function (tipo) {
    probar(function () { hoja.getProtections(tipo).forEach(function (p) { try { p.remove(); } catch (e) { /* se sigue */ } }); });
  });
  probar(function () { hoja.setFrozenRows(0); hoja.setFrozenColumns(0); });
  probar(function () { hoja.setTabColor(null); });
  try { props.setProperty(clave, String(Date.now())); } catch (e) { /* se repetirá, sin daño */ }   // directo: no es un dato, no tira el paquete recordado
  return true;
}

function hojaPlana_(nombre, ancho) {
  const libro = libroActivo_();
  let hoja = libro.getSheetByName(nombre);
  if (!hoja) hoja = libro.insertSheet(nombre);
  hojaQuitarAspectoUnaVez_(hoja, nombre);
  if (hoja.getMaxColumns() < ancho) hoja.insertColumnsAfter(hoja.getMaxColumns(), ancho - hoja.getMaxColumns());
  const antes = { filas: hoja.getLastRow(), columnas: hoja.getLastColumn() };
  const escrito = [];   // escrito[fila - 1][columna - 1]
  let maxFila = 0, maxCol = ancho;
  const nada = hojaNada_();

  function poner(f, c, valores) {
    for (let i = 0; i < valores.length; i++) {
      const fila = escrito[f - 1 + i] = escrito[f - 1 + i] || [];
      for (let j = 0; j < valores[i].length; j++) fila[c - 1 + j] = valores[i][j];
      if (f + i > maxFila) maxFila = f + i;
      if (c + valores[i].length - 1 > maxCol) maxCol = c + valores[i].length - 1;
    }
  }
  function rango(f, c) {
    const r = new Proxy({}, {
      get: function (t, p) {
        if (p === 'setValue') return function (v) { poner(f, c, [[v]]); return r; };
        if (p === 'setValues') return function (vs) { poner(f, c, vs); return r; };
        if (typeof p === 'symbol') return undefined;
        return function () { return r; };   // el formato se traga
      }
    });
    return r;
  }

  return new Proxy({}, {
    get: function (t, p) {
      if (p === 'getRange') return function (f, c) { return rango(f, c); };
      if (p === 'volcar') {
        return function () {
          const filas = Math.max(maxFila, antes.filas), columnas = Math.max(maxCol, antes.columnas);
          if (!filas || !columnas) return hoja;
          if (hoja.getMaxRows() < filas) hoja.insertRowsAfter(hoja.getMaxRows(), filas - hoja.getMaxRows());
          if (hoja.getMaxColumns() < columnas) hoja.insertColumnsAfter(hoja.getMaxColumns(), columnas - hoja.getMaxColumns());
          const grid = [];
          for (let i = 0; i < filas; i++) {
            const dentro = escrito[i] || [], fila = [];
            for (let j = 0; j < columnas; j++) fila.push(dentro[j] === undefined || dentro[j] === null ? '' : dentro[j]);
            grid.push(fila);
          }
          if (typeof hojaMemoriaGuardar_ === 'function') hojaMemoriaGuardar_(libro, nombre, grid);   // instrucción 107: lo que se acaba de montar queda en memoria para las capas del alumnado
          /* Instrucción 84 (ActualizacionHuellas.gs): si lo que se iba a escribir sale igual que la vez anterior y la pestaña sigue como la dejó, no se escribe. */
          let P = null;
          if (typeof huellaSalidaPreparar_ === 'function') {
            P = huellaSalidaPreparar_(nombre + (libro.getId ? '@' + String(libro.getId()).slice(0, 8) : ''), grid);
            if (huellaSalidaIgual_(P, antes.filas, antes.columnas)) { huellaColaQuitar_(hoja, P); huellaSalidaSaltada_(); return hoja; }   // instrucción 117: lo que otros pasos añadieron al final se quita y se vuelve a poner
          }
          hoja.getRange(1, 1, filas, columnas).setValues(grid);
          if (typeof huellaSalidaEscrita_ === 'function') huellaSalidaEscrita_(P, nombre);
          return hoja;
        };
      }
      if (typeof p === 'symbol') return undefined;
      return nada;
    }
  });
}

/*** NEAE.gs ***/
/*** ================= CENSO NEAE =================
 *
 * Lee el fichero "RegAluNEE.csv" que se descarga de Séneca (Censo NEAE) y
 * rellena solas las columnas NEAE y MEDIDAS Y RECURSOS de la tabla ALUMNADO.
 *
 * EL PROBLEMA DE ESTE FICHERO: no trae el nombre del alumno, solo sus
 * INICIALES. "Luis Pardo De la Vega" aparece como "LPDV". Tampoco trae el
 * grupo, solo el curso.
 *
 * CÓMO SE RESUELVE, comprobado sobre los 88 alumnos de ESO del curso 26-27:
 *   1. Las iniciales son las del NOMBRE primero y luego las de los APELLIDOS.
 *      Solo cuentan las palabras que empiezan por mayúscula: en
 *      "Pardo De la Vega" la palabra "la" no cuenta.
 *   2. Buscando por iniciales + curso, 81 de los 88 salen sin dudas.
 *   3. Los 7 restantes son parejas del mismo curso con las mismas iniciales.
 *      Se deshace el empate con la fecha de nacimiento, que este fichero trae
 *      y que el histórico RegAlum también trae, en el mismo formato.
 *   4. Lo que aun así no case se anota en AVISOS y no se escribe nada.
 *
 * Nunca se escribe encima de un alumno del que no se esté seguro.
 *
 * ======================================================== ***/

/* HOJA_NEAE vive en BaseHojas.gs (instrucción 50: la web pequeña la usa). */
const TITULOS_NEAE = ['Alumno/a', 'Unidad', 'Curso', 'Iniciales', 'Fecha de nacimiento',
  'NEAE', 'MEDIDAS Y RECURSOS', 'Cómo se ha localizado', 'Texto original de Séneca'];

/* Las cuatro grandes categorías del censo. La sigla es la que se imprime. */
const CATEGORIAS_NEAE = {
  'necesidades educativas especiales': 'NEE',
  'dificultades de aprendizaje': 'DIA',
  'altas capacidades intelectuales': 'AACC',
  'compensacion educativa': 'COM'
};
const ORDEN_CATEGORIAS = ['NEE', 'DIA', 'AACC', 'COM'];
/* NO HAY TOPE DE DETALLES, Y ES A PROPÓSITO (BD v50, 9-sep-2026).
   Antes se escribían dos detalles por categoría y el resto se resumía con un
   "+2", para que la columna del informe no se disparase. Lo quitó Francisco:
   un "+2" no le dice al tutor NADA, y el informe está para que el tutor sepa
   qué tiene delante. Si la columna se alarga, se estrecha otra cosa; lo que no
   se hace es esconder información en el papel del tutor. */

/* El detalle, acortado para que quepa en la columna del informe. */
const DETALLES_NEAE = {
  'dificultades especifica en el aprendizaje de la lectura o dislexia': 'dislexia',
  'dificultades especificas en el aprendizaje de la escritura - disgrafia': 'disgrafía',
  'dificultades especificas en el aprendizaje de la escritura - disortografia': 'disortografía',
  'dificultades especificas en el aprendizaje del calculo o discalculia': 'discalculia',
  'dificultades de aprendizaje por capacidad intelectual limite': 'capacidad límite',
  'dificultades de aprendizaje por retraso en el lenguaje': 'retraso lenguaje',
  'dificultades de aprendizaje derivadas de tdah': 'TDAH',
  'tdah: tipo combinado': 'TDAH combinado',
  'tdah: predomino del deficit de atencion': 'TDAH atención',
  'tdah: predominio del deficit de atencion': 'TDAH atención',
  'tdah: predominio de la impulsividad-hiperactividad': 'TDAH impulsividad',
  'retrasos evolutivos graves o profundos': 'retraso evolutivo',
  'trastornos graves del desarrollo del lenguaje': 'trastorno lenguaje',
  'discapacidad intelectual moderada': 'd. intelectual moderada',
  'discapacidad intelectual leve': 'd. intelectual leve',
  'discapacidad auditiva hipoacusia': 'hipoacusia',
  'baja vision': 'baja visión',
  'lesiones del sistema osteoarticular': 'lesión osteoart.',
  'enfermedades raras y cronicas': 'enf. rara/crónica',
  't.e.l. mixto': 'TEL mixto',
  't.e.l. expresivo': 'TEL expresivo',
  't.e.l. semantico-pragmatico': 'TEL sem-prag',
  'talento complejo': 'talento complejo',
  'talento simple': 'talento simple',
  'sobredotacion intelectual': 'sobredotación'
};

/* Medidas y recursos. tipo M = medida, R = recurso o personal de apoyo.
   En el informe salen así:  ACS, PE, PRA / PT, AL
   La barra separa las medidas del apoyo, y ocupa menos que la raya larga. */
const MEDIDAS_NEAE = {
  'programa especifico (pe).': { sigla: 'PE', tipo: 'M' },
  'programa de refuerzo del aprendizaje para aneae': { sigla: 'PRA', tipo: 'M' },
  'programa de profundizacion para aneae': { sigla: 'PP', tipo: 'M' },
  'adaptacion curricular significativa (acs).': { sigla: 'ACS', tipo: 'M' },
  'adaptacion curricular individualizada (aci)(nee - mod. c/d)': { sigla: 'ACI', tipo: 'M' },
  'adaptacion curricular para alumnado con altas capacidades intelectuales (acai)': { sigla: 'ACAI', tipo: 'M' },
  'adaptacion de acceso (aac)(nee)': { sigla: 'AAC', tipo: 'M' },
  'atencion especifica para alumnado de incorporacion tardia con graves carencias en la comunicacion linguistica (solo com)': { sigla: 'ATE', tipo: 'M' },
  'programa de refuerzo del area de lengua castellana y literatura, en lugar del area segunda lengua extranjera': { sigla: 'RLC', tipo: 'M' },
  'profesorado especialista en pedagogia terapeutica (pt)': { sigla: 'PT', tipo: 'R' },
  'profesorado especialista en audicion y lenguaje (al)': { sigla: 'AL', tipo: 'R' },
  'profesorado de aula temporal de adaptacion linguistica(atal)': { sigla: 'ATAL', tipo: 'R' },
  'profesorado de apoyo a la compensacion educativa': { sigla: 'COMP', tipo: 'R' },
  'profesional tecnico en integracion social_ptis (monitor o monitora de educacion especial)': { sigla: 'PTIS', tipo: 'R' },
  'profesorado del equipo de apoyo a ciegos o discapacitados visuales (once)': { sigla: 'ONCE', tipo: 'R' },
  'interprete de lengua de signos espanola (ilse)': { sigla: 'ILSE', tipo: 'R' },
  'vigilancia': { sigla: 'vigilancia', tipo: 'R' },
  'supervision especializada': { sigla: 'supervisión', tipo: 'R' },
  'asistencia en la higiene y aseo personal': { sigla: 'aseo', tipo: 'R' },
  'asistencia en el control de esfinteres': { sigla: 'aseo', tipo: 'R' },
  'ayuda en la alimentacion': { sigla: 'alimentación', tipo: 'R' },
  'ayuda en el desplazamiento': { sigla: 'desplazamiento', tipo: 'R' },
  'ayudas tecnicas para la comunicacion auditiva': { sigla: 'ayudas auditivas', tipo: 'R' },
  'ayudas opticas, no opticas o electronicas': { sigla: 'ayudas ópticas', tipo: 'R' }
};

/*** ================= QUÉ SIGNIFICA CADA SIGLA =================
 *
 * La leyenda del informe se construye con este diccionario, y solo con las
 * siglas que aparecen de verdad en cada grupo. Así ningún tutor se encuentra
 * una sigla sin explicar, y la leyenda no se llena de cosas que en su grupo
 * no salen.
 *
 * REGLA 1: si se añade una sigla nueva arriba, hay que añadirla también aquí.
 * Si no, el programa la encuentra en los datos, no sabe qué es, y lo anota
 * en AVISOS INFORMES. Así no se queda callado.
 *
 * REGLA 2: las explicaciones son CORTAS, de unos 25 caracteres. En la leyenda
 * caben tres por renglón y hay ocho renglones. Medido el 6-sep-2026: con
 * textos largos, un grupo con dieciséis siglas dejaba tres sin explicar; con
 * estos, las dieciséis caben en siete renglones.
 *
 * Las medidas y recursos que ya se escriben con palabras (vigilancia, aseo,
 * ayudas ópticas...) no necesitan explicación: se entienden solas.
 * ======================================================== ***/
const EXPLICACION_SIGLAS = {
  /* Categorías de la columna NEAE */
  'NEE': 'n. educativas especiales',
  'DIA': 'dificultades de aprendizaje',
  'AACC': 'altas capacidades',
  'COM': 'compensación educativa',
  /* Detalles que se escriben en siglas */
  'TDAH': 'déficit de atención',
  'TEL': 'trastorno del lenguaje',
  /* Medidas */
  'ACS': 'adaptación significativa',
  'ACI': 'adaptación individualizada',
  'ACAI': 'adapt. altas capacidades',
  'AAC': 'adaptación de acceso',
  'PE': 'programa específico',
  'PRA': 'refuerzo del aprendizaje',
  'PP': 'profundización',
  'ATE': 'atención por incorporación tardía',
  'RLC': 'refuerzo de Lengua',
  /* Recursos y personal de apoyo */
  'PT': 'pedagogía terapéutica',
  'AL': 'audición y lenguaje',
  'ATAL': 'adaptación lingüística',
  'COMP': 'profesorado de compensación',
  'PTIS': 'monitor de ed. especial',
  'ONCE': 'apoyo a ciegos',
  'ILSE': 'intérprete de signos'
};

/* Devuelve la explicación de una sigla, o cadena vacía si no la conoce. */
function explicacionDeSigla_(s) {
  const clave = String(s === null || s === undefined ? '' : s).trim().toUpperCase();
  return EXPLICACION_SIGLAS[clave] === undefined ? '' : EXPLICACION_SIGLAS[clave];
}

/*** ================= TEXTO ================= ***/

function sinTildes_(t) {
  return String(t === null || t === undefined ? '' : t)
    .normalize('NFD').replace(/[̀-ͯ]/g, '');
}

/* Las iniciales tal como las escribe Séneca: nombre primero, apellidos
   después, y solo las palabras que empiezan por mayúscula.
   "Pardo De la Vega, Luis"  ->  LPDV   */
function inicialesDe_(nombre) {
  const partes = String(nombre || '').split(',');
  const apellidos = partes[0] || '';
  const nombrePila = partes.length > 1 ? partes.slice(1).join(' ') : '';
  const palabras = sinTildes_(nombrePila + ' ' + apellidos).split(/[\s]+/);
  let salida = '';
  for (let i = 0; i < palabras.length; i++) {
    const p = palabras[i].replace(/^[^A-Za-z0-9ÑñÇç]+/, '');
    if (!p) continue;
    const c = p.charAt(0);
    if (c >= 'A' && c <= 'Z') salida += c;
    else if (c === 'Ñ' || c === 'Ç') salida += c;
  }
  return salida;
}

/* Fecha en texto, comparable. Vale "05/09/2012" y también una fecha de verdad. */
function fechaClave_(v) {
  if (v instanceof Date) {
    const d = ('0' + v.getDate()).slice(-2);
    const m = ('0' + (v.getMonth() + 1)).slice(-2);
    return d + '/' + m + '/' + v.getFullYear();
  }
  const t = String(v === null || v === undefined ? '' : v).trim();
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m) return ('0' + m[1]).slice(-2) + '/' + ('0' + m[2]).slice(-2) + '/' + m[3];
  return t;
}

/*** ================= LO QUE DICE EL CENSO ================= ***/

/* El campo viene así:
   [Necesidades ... | Dificultades de Aprendizaje | ... | dislexia, Necesidades ... ]
   Se parte por cada "Necesidades específicas de apoyo educativo". */
function trocearNecesidades_(texto) {
  const t = String(texto || '').replace(/^\s*\[/, '').replace(/\]\s*$/, '');
  if (!t.trim()) return [];
  const trozos = t.split(/,\s*(?=Necesidades\s+espec)/);
  const rutas = [];
  for (let i = 0; i < trozos.length; i++) {
    const partes = trozos[i].split('|');
    const limpio = [];
    for (let p = 0; p < partes.length; p++) {
      const x = partes[p].trim();
      if (x) limpio.push(x);
    }
    if (limpio.length > 1) rutas.push(limpio);
  }
  return rutas;
}

/* "DIA dislexia, disgrafía · NEE TDAH combinado" */
function resumirNecesidades_(texto, sinDiccionario) {
  const rutas = trocearNecesidades_(texto);
  const porCategoria = {};
  for (let i = 0; i < rutas.length; i++) {
    const ruta = rutas[i];
    const sigla = CATEGORIAS_NEAE[normalizar(ruta[1])];
    if (!sigla) {
      if (sinDiccionario) sinDiccionario.push('Categoría NEAE desconocida: ' + ruta[1]);
      continue;
    }
    if (!porCategoria[sigla]) porCategoria[sigla] = [];
    if (ruta.length < 3) continue;                    // Compensación Educativa no tiene detalle
    const ultimo = ruta[ruta.length - 1];
    let corto = DETALLES_NEAE[normalizar(ultimo)];
    if (corto === undefined) {
      corto = ultimo;
      if (sinDiccionario) sinDiccionario.push('Detalle NEAE sin abreviar: ' + ultimo);
    }
    if (porCategoria[sigla].indexOf(corto) === -1) porCategoria[sigla].push(corto);
  }
  const bloques = [];
  for (let i = 0; i < ORDEN_CATEGORIAS.length; i++) {
    const s = ORDEN_CATEGORIAS[i];
    if (!porCategoria[s]) continue;
    const lista = porCategoria[s];
    if (!lista.length) { bloques.push(s); continue; }
    bloques.push(s + ' ' + lista.join(', '));
  }
  return bloques.join(' · ');
}

/* "ACS, PE, PRA / PT, AL" */
function resumirMedidas_(texto, sinDiccionario) {
  const t = String(texto || '');
  const trozos = t.split('<li>');
  const medidas = [], recursos = [];
  for (let i = 1; i < trozos.length; i++) {
    let x = trozos[i].split('<')[0].trim().replace(/,\s*$/, '').trim();
    if (!x) continue;
    const d = MEDIDAS_NEAE[normalizar(x)];
    if (!d) {
      /* Una medida que no está en el diccionario NO se tira (BD v50). Antes se
         anotaba en AVISOS y desaparecía del papel, así que el tutor no llegaba
         a saber que ese alumno la tiene. Ahora se escribe con sus palabras, tal
         y como viene de Séneca, y el aviso sigue saliendo para poder darle su
         sigla. Va con las medidas: los recursos son una lista corta y cerrada
         (PT, AL, ATAL, PTIS...) que ya está entera en el diccionario. */
      if (sinDiccionario) sinDiccionario.push('Medida o recurso sin abreviar: ' + x);
      if (medidas.indexOf(x) === -1) medidas.push(x);
      continue;
    }
    const lista = d.tipo === 'M' ? medidas : recursos;
    if (lista.indexOf(d.sigla) === -1) lista.push(d.sigla);
  }
  if (!medidas.length && !recursos.length) return '';
  if (!recursos.length) return medidas.join(', ');
  if (!medidas.length) return recursos.join(', ');
  return medidas.join(', ') + ' / ' + recursos.join(', ');
}

/*** ================= LECTURA DEL FICHERO ================= ***/

function leerCensoNeae_() {
  const archivo = buscarCsv(PREFIJO_NEAE);
  if (!archivo) return { registros: [], nombre: '', avisos: [] };

  const tabla = textoATabla(textoDeArchivo(archivo));
  if (!tabla.length) return { registros: [], nombre: archivo.getName(), avisos: [] };

  const cab = tabla[0].map(normalizar);
  const iNom = cab.indexOf(normalizar('Alumno/a'));
  const iFec = cab.indexOf(normalizar('Fecha de nacimiento'));
  const iCur = cab.indexOf(normalizar('Curso'));
  const iNec = cab.indexOf(normalizar('Necesidades específicas de apoyo educativo'));
  let iMed = cab.indexOf(normalizar('Medidas Específicas y Recursos Recibidos'));
  if (iMed === -1) iMed = cab.indexOf(normalizar('Medidas Específicas y Recursos Necesitados'));
  if (iNom === -1 || iCur === -1 || iNec === -1) {
    return { registros: [], nombre: archivo.getName(),
             avisos: ['Al censo NEAE le faltan columnas. No se ha usado.'] };
  }

  const registros = [], sinDiccionario = [], descartadas = {};
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    /* Desde la BD v51 el censo vale también para Bachillerato. Lo que no sea
       ni ESO ni Bachillerato (educación especial, por ejemplo) no tiene sitio
       en la tabla ALUMNADO, así que no se puede escribir en ningún lado; pero
       tampoco se tira en silencio: se cuenta y se dice más abajo. */
    const nivel = nivelESO(fila[iCur]) || nivelBachilleratoCenso_(fila[iCur]);
    if (!nivel) {
      const q = String(fila[iCur] || '').trim() || '(sin curso)';
      descartadas[q] = (descartadas[q] || 0) + 1;
      continue;
    }
    const iniciales = sinTildes_(String(fila[iNom] || '').trim()).toUpperCase();
    if (!iniciales) continue;
    registros.push({
      iniciales: iniciales,
      fecha: iFec === -1 ? '' : fechaClave_(fila[iFec]),
      curso: nivel,
      neae: resumirNecesidades_(fila[iNec], sinDiccionario),
      medidas: iMed === -1 ? '' : resumirMedidas_(fila[iMed], sinDiccionario),
      original: String(fila[iNec] || '').replace(/\s+/g, ' ').substring(0, 400)
    });
  }

  const avisos = [], vistos = {};
  const quedanFuera = Object.keys(descartadas).sort();
  if (quedanFuera.length) {
    const detalle = [];
    for (let i = 0; i < quedanFuera.length; i++) {
      detalle.push(quedanFuera[i] + ': ' + descartadas[quedanFuera[i]]);
    }
    avisos.push('El censo trae ' + detalle.join(' · ') +
      '. Esas fichas no son ni de ESO ni de Bachillerato, así que no hay ' +
      'ningún alumno de la tabla al que escribírselas. Es normal: son de ' +
      'educación especial o de enseñanzas que este sistema no lleva.');
  }
  for (let i = 0; i < sinDiccionario.length; i++) {
    if (vistos[sinDiccionario[i]]) continue;
    vistos[sinDiccionario[i]] = true;
    avisos.push(sinDiccionario[i]);
  }
  return { registros: registros, nombre: archivo.getName(), avisos: avisos };
}

/*** ================= EL CRUCE ================= ***/

/* historial: las filas de la pestaña HISTORIAL.
   Devuelve un mapa por nombre normalizado con lo que hay que escribir. */
function cruzarNeae_(registros, historial, iNombre, iCurso, iFecha) {
  const porClave = {};                       // iniciales + curso -> lista de alumnos
  for (let f = 0; f < historial.length; f++) {
    const nombre = String(historial[f][iNombre] || '').trim();
    if (!nombre) continue;
    const curso = String(historial[f][iCurso] || '').trim();
    const clave = inicialesDe_(nombre) + '|' + curso;
    if (!porClave[clave]) porClave[clave] = [];
    porClave[clave].push({
      nombre: nombre,
      fecha: iFecha === -1 ? '' : fechaClave_(historial[f][iFecha])
    });
  }

  const salida = {}, avisos = [];
  let porIniciales = 0, porFecha = 0;
  for (let i = 0; i < registros.length; i++) {
    const r = registros[i];
    const candidatos = porClave[r.iniciales + '|' + r.curso] || [];
    let elegido = null, como = '';
    if (candidatos.length === 1) {
      elegido = candidatos[0];
      como = 'iniciales + curso';
      porIniciales++;
    } else if (candidatos.length > 1) {
      const conFecha = [];
      for (let c = 0; c < candidatos.length; c++) {
        if (r.fecha && candidatos[c].fecha === r.fecha) conFecha.push(candidatos[c]);
      }
      if (conFecha.length === 1) {
        elegido = conFecha[0];
        como = 'iniciales + curso + fecha de nacimiento';
        porFecha++;
      } else {
        const nombres = [];
        for (let c = 0; c < candidatos.length; c++) nombres.push(candidatos[c].nombre);
        avisos.push({ curso: r.curso, grupo: '', alumno: '',
          aviso: 'Censo NEAE: no sé de quién es esta ficha',
          detalle: 'Iniciales "' + r.iniciales + '" de ' + r.curso + ', nacido el ' +
                   (r.fecha || 'sin fecha') + '. Podría ser: ' + nombres.join(' / ') +
                   '. No he escrito nada.' });
      }
    } else {
      avisos.push({ curso: r.curso, grupo: '', alumno: '',
        aviso: 'Censo NEAE: ficha sin alumno en el centro',
        detalle: 'Iniciales "' + r.iniciales + '" de ' + r.curso +
                 '. No hay nadie con esas iniciales en ese curso. Puede que ya no esté matriculado.' });
    }
    if (!elegido) continue;
    /* La clave lleva el curso, como todos los cruces del sistema: dos alumnos
       distintos pueden llamarse igual, y la ficha NEAE es de uno solo. */
    const clave = normalizar(elegido.nombre) + '|' + r.curso;
    if (salida[clave]) {
      avisos.push({ curso: r.curso, grupo: '', alumno: elegido.nombre,
        aviso: 'Censo NEAE: dos fichas para el mismo alumno',
        detalle: 'Se ha quedado con la primera.' });
      continue;
    }
    salida[clave] = { neae: r.neae, medidas: r.medidas, como: como,
                      iniciales: r.iniciales, fecha: r.fecha, original: r.original,
                      nombre: elegido.nombre, curso: r.curso };
  }
  return { porNombre: salida, avisos: avisos, porIniciales: porIniciales, porFecha: porFecha };
}

/*** ================= LA PESTAÑA NEAE ================= ***/

function escribirNeae_(porNombre, unidades, nombreFichero) {
  const ancho = TITULOS_NEAE.length;
  const hoja = hojaPlana_(HOJA_NEAE, ancho);   // instrucción 83: sin pintar
  hoja.getRange(1, 1).setValue('Censo NEAE de Séneca. Origen: ' + (nombreFichero || 'no encontrado') +
    '. El fichero no trae el nombre del alumno, solo sus iniciales: aquí se ve a quién se ha' +
    ' asignado cada ficha. Actualizado: ' + new Date().toLocaleString('es-ES')).setFontStyle('italic');
  hoja.getRange(2, 1, 1, ancho).setValues([TITULOS_NEAE]).setFontWeight('bold')
      .setBackground('#D9D9D9').setWrap(true).setVerticalAlignment('middle');

  const filas = [];
  for (const clave in porNombre) {
    const d = porNombre[clave];
    filas.push([d.nombre, unidades[clave] || '', d.curso, d.iniciales, d.fecha,
                d.neae, d.medidas, d.como, d.original]);
  }
  filas.sort(function (a, b) {
    const ka = a[1] + ' ' + normalizar(a[0]), kb = b[1] + ' ' + normalizar(b[0]);
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  });
  if (filas.length) hoja.getRange(3, 1, filas.length, ancho).setValues(filas);
  hoja.setFrozenRows(2);
  /* Sin autoResizeColumn: arreglarFormatoDeTodo_ (Formato.gs) deja un ancho
     fijo por columna al terminar "Actualizar los datos". */
  hoja.setColumnWidth(ancho, 320);
  if (filas.length) hoja.getRange(3, ancho, filas.length, 1).setWrap(true);
  hoja.volcar();
  return filas.length;
}

/*** ================= LO QUE LLAMA Codigo.gs ================= ***/

/* Devuelve { porNombre, avisos, resumen }. Si no encuentra el fichero,
   devuelve un mapa vacío y un aviso: las columnas se quedan como estaban. */
function datosNeae_(historial, iNombre, iCurso, iFecha) {
  const censo = leerCensoNeae_();
  const avisos = [];
  for (let i = 0; i < censo.avisos.length; i++) {
    avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Censo NEAE', detalle: censo.avisos[i] });
  }
  if (!censo.registros.length) {
    avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'No encuentro el censo NEAE',
      detalle: 'Debe haber un fichero que empiece por "' + PREFIJO_NEAE + '" en la carpeta de datos. ' +
               'Sin él, las columnas NEAE y MEDIDAS Y RECURSOS se quedan como estaban.' });
    return { porNombre: {}, avisos: avisos, nombre: censo.nombre, resumen: '', total: 0 };
  }
  /* Sin fecha de nacimiento en el histórico no se pueden deshacer los empates
     entre alumnos del mismo curso con las mismas iniciales. Pasa cuando la
     pestaña HISTORIAL se hizo con una versión anterior del programa. */
  let hayFechas = false;
  if (iFecha !== -1) {
    for (let f = 0; f < historial.length; f++) {
      if (String(historial[f][iFecha] || '').trim()) { hayFechas = true; break; }
    }
  }
  if (!hayFechas) {
    avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'El histórico no tiene fechas de nacimiento',
      detalle: 'Vuelve a pulsar "1. Leer el histórico de matrículas". Sin las fechas, ' +
               'los alumnos del mismo curso con las mismas iniciales se quedan sin NEAE.' });
  }

  /* EL BACHILLERATO NO ESTÁ EN EL HISTORIAL, así que se le añaden aquí sus
     filas, sacadas de la matrícula. Si no, cada ficha de Bachillerato saldría
     como "ficha sin alumno en el centro". Ver Bachillerato.gs. */
  const anchoCruce = Math.max(iNombre, iCurso, iFecha) + 1;
  const filasBac = filasBachilleratoParaCruce_(iNombre, iCurso, anchoCruce);
  const paraCruzar = filasBac.length ? historial.concat(filasBac) : historial;

  const R = cruzarNeae_(censo.registros, paraCruzar, iNombre, iCurso, iFecha);
  for (let i = 0; i < R.avisos.length; i++) avisos.push(R.avisos[i]);
  const total = R.porIniciales + R.porFecha;
  return {
    porNombre: R.porNombre,
    avisos: avisos,
    nombre: censo.nombre,
    total: total,
    resumen: 'Censo NEAE: ' + censo.registros.length + ' fichas de ESO y Bachillerato, ' +
             total + ' asignadas (' + R.porFecha + ' por fecha de nacimiento).'
  };
}

/*** Primaria.gs ***/
/*** ================= EXPEDIENTES DE PRIMARIA =================
 *
 * Francisco descarga de Séneca, uno a uno, el expediente de Primaria de cada
 * alumno de 1º de ESO. Los deja en la subcarpeta "Expedientes Primaria" que
 * cuelga de "Datos de matrícula". Cada fichero se llama:
 *
 *     RegDetExpEle Apellido1 Apellido2, Nombre.csv
 *
 * EL NOMBRE DEL ALUMNO NO ESTÁ DENTRO DEL FICHERO: solo en su nombre. Por eso
 * el cruce con ALUMNADO se hace por el nombre del fichero, normalizado.
 *
 * QUÉ TRAE CADA FICHERO. Una línea por materia y por año académico, desde 1º
 * de Primaria hasta 6º, con la nota. Las materias que el alumno arrastraba de
 * un curso anterior salen con el curso entre paréntesis:
 *
 *     "Matemáticas (5º de Educ. Prima.)"
 *
 * PARA QUÉ SE USA (decisión de Francisco, 6-sep-2026):
 *
 *   1. PENDIENTES (6º Primaria): las materias del PROPIO 6º con nota menor
 *      que 5. Las que arrastraba de cursos anteriores NO entran, porque en
 *      algunos alumnos son diez o más y no caben en el folio. Para incluirlas
 *      basta con poner INCLUIR_ARRASTRADAS en true, aquí abajo.
 *
 *   2. REPETICIONES EN PRIMARIA de verdad. Hasta ahora se estimaban con la
 *      edad, y unos 38 alumnos quedaban por revisar a mano. El expediente lo
 *      dice sin lugar a dudas: si un curso aparece en dos años académicos
 *      distintos, ese curso se repitió. Solo se da por bueno cuando el
 *      expediente trae los seis cursos; si viene incompleto (alumnado que
 *      llega de otra comunidad), se anota en AVISOS y se deja la estimación
 *      por edad, que es lo que había.
 *
 * Nunca se escribe encima de un alumno del que no se esté seguro.
 *
 * ======================================================== ***/

const CARPETA_PRIMARIA = 'Expedientes Primaria';
/* Ponlo en true si algún día quieres que la columna PENDIENTES (6º Primaria)
   incluya también lo que el alumno arrastraba de 3º, 4º o 5º. */
const INCLUIR_ARRASTRADAS = false;

const TITULOS_PRIMARIA = ['Alumno/a', 'Unidad', 'Año de 1º', 'Año de 6º', 'Nº pendientes',
  'Pendientes de 6º', 'Arrastraba de antes', 'Rep. Primaria (expediente)',
  'Cursos repetidos', 'Centro de 6º', 'Fichero'];

/* Las materias de Primaria, acortadas para que quepan en la columna del
   informe. Las que ya están en el diccionario general de ESO (LCL, MAT,
   ING, EFI, REL...) no hace falta repetirlas: se buscan allí. */
const ABREVIATURAS_PRIMARIA = {
  'Conocimiento del Medio Natural Social y Cultural': 'CM',
  'Educación Artística': 'ART',
  'Inglés (Primer Idioma)': 'ING',
  'Ciencias de la Naturaleza': 'CNA',
  'Ciencias Sociales': 'CSO',
  'Valores sociales y cívicos': 'VSC',
  'Proyecto Interdisciplinar': 'PI',
  'Proyecto Interdisciplinar 1': 'PI',
  'Educación para la Ciudadanía y los Derechos Humanos': 'ECDH',
  'Inteligencia Emocional en el Aula. Colegio con Consciencia Plena': 'IE',
  'Materia de diseño propio 1': 'MDP'
};

/*** ================= LEER UNA LÍNEA ================= ***/

/* "6º de Educ. Prima. - Periodo 1"  ->  "6º".  Devuelve '' si no es Primaria. */
function cursoPrimaria_(texto) {
  const m = String(texto || '').trim().match(/^([1-6])\s*º?\s*de\s+Educ/i);
  return m ? m[1] + 'º' : '';
}

/* "Matemáticas (5º de Educ. Prima.)"  ->  { materia: 'Matemáticas', de: '5º' }
   "Matemáticas"                       ->  { materia: 'Matemáticas', de: '' }  */
function partirMateria_(texto) {
  const t = String(texto || '').replace(/\s+/g, ' ').trim();
  const m = t.match(/^(.*?)\s*\(([1-6])\s*º?\s*de\s+Educ\.?\s*Prima\.?\)$/i);
  if (m) return { materia: m[1].trim(), de: m[2] + 'º' };
  return { materia: t, de: '' };
}

/* Una nota es negativa si es un número menor que 5. Séneca puede dejarla
   vacía (matrícula trasladada, o pendiente de la convocatoria extraordinaria):
   en ese caso no se sabe, y no se cuenta como suspensa. */
function notaNegativa_(v) {
  if (!esNumero(v)) return false;
  return aNumero(v) < 5;
}

function abreviarPrimaria_(nombre, sinDiccionario) {
  const objetivo = normalizar(nombre);
  for (const largo in ABREVIATURAS_PRIMARIA) {
    if (normalizar(largo) === objetivo) return ABREVIATURAS_PRIMARIA[largo];
  }
  const general = abreviar(nombre);
  if (normalizar(general) !== objetivo) return general;   // lo tenía el de ESO
  if (sinDiccionario) sinDiccionario.push('Materia de Primaria sin abreviar: ' + nombre);
  return nombre;
}

/* "RegDetExpEle Apellido1 Apellido2, Nombre.csv"  ->  "Apellido1 Apellido2, Nombre" */
function nombreDelFichero_(nombreFichero) {
  let t = String(nombreFichero || '').replace(/\.csv$/i, '');
  const p = normalizar(PREFIJO_EXPEDIENTE);
  if (normalizar(t).indexOf(p) === 0) t = t.substring(PREFIJO_EXPEDIENTE.length);
  return t.replace(/^[\s_-]+/, '').replace(/\s+/g, ' ').trim();
}

/*** ================= LEER UN EXPEDIENTE =================
 *
 * CACHÉ DE EXPEDIENTES (BD v64). Descargar y leer un CSV por cada alumno es
 * lo que más tarda de "Actualizar los datos" cuando ya hay muchos expedientes
 * acumulados de años anteriores. leerExpediente_ es ahora solo la envoltura
 * que mira la caché (Cache.gs); leerExpedientePrimariaReal_ es la lectura de
 * verdad, tal y como era antes.
 *
 * OJO CON sinDiccionario: es una lista que se va rellenando por el camino
 * (las materias que no se han sabido abreviar), y hay que guardarla también
 * en la caché, porque si el resultado sale de la caché ya no se vuelve a
 * llamar a abreviarPrimaria_ y esos avisos se perderían. ***/

function leerExpediente_(archivo, sinDiccionario) {
  const r = conCacheDeFichero_('PRIMARIA', archivo, function (archivoDeVerdad) {
    const propios = [];
    return { salida: leerExpedientePrimariaReal_(archivoDeVerdad, propios), sinDic: propios };
  });
  if (sinDiccionario && r.sinDic && r.sinDic.length) {
    for (let i = 0; i < r.sinDic.length; i++) sinDiccionario.push(r.sinDic[i]);
  }
  return r.salida;
}

function leerExpedientePrimariaReal_(archivo, sinDiccionario) {
  const alumno = nombreDelFichero_(archivo.getName());
  const salida = {
    nombre: alumno, fichero: archivo.getName(), anoPrimero: '', anoSexto: '', centro: '',
    pendientes: [], arrastradas: [], repeticiones: '', cursosRepetidos: [],
    completo: false, avisos: []
  };
  if (!alumno) {
    salida.avisos.push('El fichero "' + archivo.getName() + '" no lleva el nombre del alumno.');
    return salida;
  }

  const tabla = textoATabla(textoDeArchivo(archivo));
  if (tabla.length < 2) {
    salida.avisos.push('El fichero "' + archivo.getName() + '" está vacío.');
    return salida;
  }

  const cab = tabla[0].map(normalizar);
  const iCurso = cab.indexOf(normalizar('Curso'));
  const iAno = cab.indexOf(normalizar('Año académico'));
  const iEstado = cab.indexOf(normalizar('Estado de matrícula'));
  const iCentro = cab.indexOf(normalizar('Centro'));
  const iMateria = cab.indexOf(normalizar('Materias'));
  const iNota = cab.indexOf(normalizar('Calificaciones'));
  if (iCurso === -1 || iMateria === -1 || iNota === -1) {
    salida.avisos.push('Al fichero "' + archivo.getName() + '" le faltan columnas. No lo he usado.');
    return salida;
  }

  /* Primera vuelta: qué años hay de cada curso, y cuál es el año de 6º.
     Si el alumno repitió 6º, vale el más reciente. */
  const anosPorCurso = {};
  let anoSexto = 0, anoPrimero = 0;
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    const curso = cursoPrimaria_(fila[iCurso]);
    if (!curso) continue;
    const estado = iEstado === -1 ? '' : normalizar(fila[iEstado]);
    if (ESTADOS_QUE_NO_CUENTAN.indexOf(estado) !== -1) continue;
    const ano = iAno === -1 ? 0 : parseInt(fila[iAno], 10);
    if (!ano) continue;
    if (!anosPorCurso[curso]) anosPorCurso[curso] = {};
    anosPorCurso[curso][ano] = true;
    if (curso === '6º' && ano > anoSexto) anoSexto = ano;
    /* El año en que empezó 1º de Primaria. Si repitió 1º, el primero de los dos.
       Sirve para descartar la incorporación tardía al sistema educativo
       español: se compara con su fecha de nacimiento en Codigo.gs. */
    if (curso === '1º' && (!anoPrimero || ano < anoPrimero)) anoPrimero = ano;
  }

  /* Repeticiones: un curso que aparece en dos años académicos distintos se
     repitió. Solo vale si están los seis cursos; si no, el expediente viene
     incompleto y no se puede contar. */
  let faltan = [];
  let repeticiones = 0;
  const repetidos = [];
  for (let n = 1; n <= 6; n++) {
    const curso = n + 'º';
    const anos = anosPorCurso[curso];
    if (!anos) { faltan.push(curso); continue; }
    const veces = Object.keys(anos).length;
    if (veces > 1) { repeticiones += veces - 1; repetidos.push(curso); }
  }
  salida.anoPrimero = anoPrimero || '';
  salida.completo = faltan.length === 0;
  salida.cursosRepetidos = repetidos;
  if (salida.completo) {
    salida.repeticiones = repeticiones;
  } else {
    salida.avisos.push('El expediente de ' + alumno + ' no trae ' +
      (faltan.length === 1 ? 'el curso ' : 'los cursos ') + faltan.join(', ') +
      ' de Primaria. No he tocado sus repeticiones: se queda la estimación por edad.' +
      (repetidos.length ? ' (En lo que sí trae repitió ' + repetidos.join(', ') + '.)' : ''));
  }

  if (!anoSexto) {
    salida.avisos.push('El expediente de ' + alumno + ' no trae 6º de Primaria. ' +
      'No he escrito sus pendientes.');
    return salida;
  }
  salida.anoSexto = anoSexto;

  /* Segunda vuelta: las notas de 6º. Una misma materia puede salir dos veces
     (ordinaria y extraordinaria): se queda la nota más alta. */
  const mejores = {};
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    if (cursoPrimaria_(fila[iCurso]) !== '6º') continue;
    const estado = iEstado === -1 ? '' : normalizar(fila[iEstado]);
    if (ESTADOS_QUE_NO_CUENTAN.indexOf(estado) !== -1) continue;
    if (iAno !== -1 && parseInt(fila[iAno], 10) !== anoSexto) continue;
    if (iCentro !== -1 && !salida.centro) {
      salida.centro = String(fila[iCentro] || '').replace(/\s+/g, ' ').trim();
    }
    const p = partirMateria_(fila[iMateria]);
    if (!p.materia) continue;
    const clave = normalizar(p.materia) + '|' + p.de;
    const nota = fila[iNota];
    const anterior = mejores[clave];
    if (!anterior || (esNumero(nota) && (!esNumero(anterior.nota) || aNumero(nota) > aNumero(anterior.nota)))) {
      mejores[clave] = { materia: p.materia, de: p.de, nota: nota };
    }
  }

  const propias = [], arrastradas = [];
  for (const clave in mejores) {
    const m = mejores[clave];
    if (!notaNegativa_(m.nota)) continue;
    const corto = abreviarPrimaria_(m.materia, sinDiccionario);
    if (m.de) arrastradas.push(corto + ' ' + m.de);
    else propias.push(corto);
  }
  propias.sort();
  arrastradas.sort();
  salida.pendientes = INCLUIR_ARRASTRADAS ? propias.concat(arrastradas) : propias;
  salida.arrastradas = arrastradas;
  return salida;
}

/*** ================= LA CARPETA =================
 *
 * El panel mira esta carpeta para el resumen de "qué hay" y datosPrimaria_
 * la vuelve a mirar para leer los expedientes de verdad: dentro de una misma
 * pulsación de "Actualizar los datos" se listaba dos veces, y si hay muchos
 * ficheros (años de expedientes) eso se nota. Se lista una sola vez y se
 * guarda en CACHE_FICHEROS_EXPEDIENTES_; la próxima pulsación es una
 * ejecución nueva y se vuelve a mirar de cero. ***/
let CACHE_CARPETA_EXPEDIENTES_;   // undefined = no calculada todavía
let CACHE_FICHEROS_EXPEDIENTES_ = null;

function carpetaExpedientes_() {
  if (CACHE_CARPETA_EXPEDIENTES_ !== undefined) return CACHE_CARPETA_EXPEDIENTES_;
  let carpeta = null;
  try {
    const it = carpeta_('descargas').getFoldersByName(CARPETA_PRIMARIA);
    if (it.hasNext()) carpeta = it.next();
  } catch (e) { /* devolvemos null y se avisa */ }
  CACHE_CARPETA_EXPEDIENTES_ = carpeta;
  return carpeta;
}

/* Los ficheros de la carpeta de expedientes, listados una sola vez. */
function ficherosDeExpedientes_() {
  if (CACHE_FICHEROS_EXPEDIENTES_) return CACHE_FICHEROS_EXPEDIENTES_;
  const arr = [];
  const carpeta = carpetaExpedientes_();
  if (carpeta) {
    const it = carpeta.getFiles();
    while (it.hasNext()) arr.push(it.next());
  }
  CACHE_FICHEROS_EXPEDIENTES_ = arr;
  return arr;
}

/*** ================= LO QUE LLAMA Codigo.gs ================= ***/

/* Devuelve { porNombre, avisos, total, ficheros }.
   Si no hay carpeta o no hay ficheros, devuelve un mapa vacío: las columnas
   se quedan exactamente como estaban. */
function datosPrimaria_(cursosDeAlumno) {
  const avisos = [];
  const carpeta = carpetaExpedientes_();
  if (!carpeta) {
    avisos.push({ curso: '1º', grupo: '', alumno: '', aviso: 'No encuentro la carpeta de expedientes',
      detalle: 'Debe haber una subcarpeta llamada "' + CARPETA_PRIMARIA + '" dentro de la carpeta de ' +
               'datos. Sin ella, la columna PENDIENTES (6º Primaria) se queda como estaba.' });
    return { porNombre: {}, avisos: avisos, total: 0, ficheros: 0 };
  }

  const porNombre = {}, sinDiccionario = [];
  let ficheros = 0;
  const listaFicheros = ficherosDeExpedientes_();
  for (let fi = 0; fi < listaFicheros.length; fi++) {
    const f = listaFicheros[fi];
    if (!/\.csv$/i.test(f.getName())) continue;
    ficheros++;
    let r;
    try {
      r = leerExpediente_(f, sinDiccionario);
    } catch (e) {
      avisos.push({ curso: '1º', grupo: '', alumno: '', aviso: 'Expediente de Primaria ilegible',
        detalle: f.getName() + ': ' + e.message });
      continue;
    }
    for (let i = 0; i < r.avisos.length; i++) {
      avisos.push({ curso: '1º', grupo: '', alumno: r.nombre,
        aviso: 'Expediente de Primaria', detalle: r.avisos[i] });
    }
    if (!r.nombre) continue;
    /* Asignación dinámica del curso. Se busca el alumno en la matrícula actual
       para añadirle el curso correcto a la clave. */
    const nomNorm = normalizar(r.nombre);
    const posibles = (cursosDeAlumno && cursosDeAlumno[nomNorm]) || [];
    
    if (posibles.length > 1) {
      avisos.push({ curso: '', grupo: '', alumno: r.nombre,
        aviso: 'Expediente ambiguo por nombre repetido',
        detalle: 'Hay alumnado que se llama exactamente así en ' + posibles.join(' y ') +
                 '. Como el fichero de Séneca no indica el curso, el programa no sabe a cuál asignarlo.' });
      continue;
    }
    
    const cursoAsignado = posibles.length === 1 ? posibles[0] : '1º';
    const clave = nomNorm + '|' + cursoAsignado;
    
    if (porNombre[clave]) {
      avisos.push({ curso: '1º', grupo: '', alumno: r.nombre,
        aviso: 'Dos expedientes para el mismo alumno',
        detalle: 'Ficheros "' + porNombre[clave].fichero + '" y "' + r.fichero +
                 '". Me he quedado con el primero.' });
      continue;
    }
    porNombre[clave] = r;
  }

  const vistos = {};
  for (let i = 0; i < sinDiccionario.length; i++) {
    if (vistos[sinDiccionario[i]]) continue;
    vistos[sinDiccionario[i]] = true;
    avisos.push({ curso: '1º', grupo: '', alumno: '', aviso: 'Expediente de Primaria',
      detalle: sinDiccionario[i] });
  }

  return { porNombre: porNombre, avisos: avisos,
           total: Object.keys(porNombre).length, ficheros: ficheros };
}

/*** ================= LA PESTAÑA PRIMARIA ================= ***/

/* Igual que la pestaña NEAE: sirve para ver de un vistazo qué ha entendido el
   programa de cada expediente, sin abrir los CSV uno a uno. */
function escribirPrimaria_(porNombre, unidadesPorNombre, usados) {
  const ancho = TITULOS_PRIMARIA.length;
  const hoja = hojaPlana_(HOJA_PRIMARIA, ancho);   // instrucción 83: sin pintar
  hoja.getRange(1, 1).setValue('Expedientes de Primaria descargados de Séneca, uno por alumno de 1º. ' +
    'El nombre del alumno se saca del nombre del fichero. ' +
    (INCLUIR_ARRASTRADAS ? 'La columna PENDIENTES incluye lo arrastrado de cursos anteriores. '
                         : 'En PENDIENTES solo van las materias suspensas en 6º. ') +
    'Actualizado: ' + new Date().toLocaleString('es-ES')).setFontStyle('italic');
  hoja.getRange(2, 1, 1, ancho).setValues([TITULOS_PRIMARIA]).setFontWeight('bold')
      .setBackground('#D9D9D9').setWrap(true).setVerticalAlignment('middle');

  const filas = [];
  for (const clave in porNombre) {
    const r = porNombre[clave];
    filas.push([r.nombre, unidadesPorNombre[clave] || (usados[clave] ? '' : 'NO ESTÁ EN ALUMNADO'),
      anoAcademico_(r.anoPrimero), anoAcademico_(r.anoSexto),
      r.pendientes.length ? r.pendientes.length : '',
      r.pendientes.join(', '), r.arrastradas.join(', '),
      r.repeticiones === '' ? 'expediente incompleto' : r.repeticiones,
      r.cursosRepetidos.join(', '), r.centro, r.fichero]);
  }
  filas.sort(function (a, b) {
    const ka = normalizar(a[0]), kb = normalizar(b[0]);
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  });
  if (filas.length) hoja.getRange(3, 1, filas.length, ancho).setValues(filas);
  hoja.volcar();
  return filas.length;
}

/*** Secundaria.gs ***/
/*** ================= EXPEDIENTES DE SECUNDARIA =================
 *
 * Añadido en la BD v42, el 8-sep-2026, a partir de una corrección de
 * Francisco: "no podemos ver las matrículas de otros institutos desde Séneca,
 * pero eso no es del todo cierto. Si el otro instituto pertenece al Sistema
 * Educativo Andaluz sí podemos verlo."
 *
 * QUÉ PROBLEMA RESUELVE. El fichero RegAlum.csv es el registro de matrículas
 * DE ESTE CENTRO. Un alumno que repitió 2º en otro instituto y llegó aquí
 * después figura como si no lo hubiera repetido. Su PIL salía mal.
 *
 * QUÉ ES ESTE FICHERO. El expediente académico de Secundaria del alumno,
 * descargado de Séneca uno a uno, igual que el de Primaria. Trae TODA su vida
 * en la ESO, con el centro de cada año, así que ve lo que RegAlum no ve.
 *
 * DÓNDE VA. En la subcarpeta "Expedientes Secundaria", dentro de
 * "Datos de matrícula". Cada fichero se llama:
 *
 *     RegDetExpEle SEC Apellido1 Apellido2, Nombre.csv
 *
 * EL NOMBRE DEL ALUMNO NO ESTÁ DENTRO DEL FICHERO, igual que en Primaria:
 * solo en el nombre del fichero. Por eso el cruce se hace por ahí.
 *
 * NO HACEN FALTA LOS DE TODOS. Descargarlos es un trabajo de uno en uno, y
 * son casi setecientos alumnos. Solo hace falta el de quien tenga algo sin
 * cuadrar en su trayectoria de ESO. El programa saca esa lista solo, en
 * AVISOS, con el aviso "Hace falta su expediente de Secundaria".
 *
 * MISMAS COLUMNAS QUE EL DE PRIMARIA. Comprobado sobre el primer fichero:
 *   Tipo de expediente · Curso · Año académico · Estado de matrícula ·
 *   Centro · Grupo de materias · Materias · Convocatoria · Calificaciones
 *
 * Cuatro diferencias en el CONTENIDO, y las cuatro están tratadas aquí:
 *   1. El curso viene como "2º de E.S.O. - Periodo 1".
 *   2. La convocatoria puede ser "Matriculada" o "Pendiente", y entonces la
 *      calificación viene vacía: es el curso en marcha, no una nota.
 *   3. El estado de matrícula puede venir vacío (el año actual) y puede ser
 *      "Trasladada", que no cuenta.
 *   4. Las materias pendientes de cursos anteriores salen como líneas
 *      propias, con el curso entre paréntesis: "Inglés (1º de E.S.O.)".
 *      Para contar suspensos SÍ cuentan: son materias con evaluación
 *      negativa, y eso es lo que decide la promoción.
 *
 * ======================================================== ***/

const CARPETA_SECUNDARIA = 'Expedientes Secundaria';
const TITULOS_SECUNDARIA = ['Alumno/a', 'Unidad', 'Curso el año pasado', 'Repetía el año pasado',
  'Suspensos el año pasado', 'Repeticiones en ESO', 'Cursos repetidos en ESO',
  'Años que trae', 'Centros', 'Fichero'];

/*** ================= LEER UNA LÍNEA ================= ***/

/* "2º de E.S.O. - Periodo 1"  ->  "2º".  Devuelve '' si no es un curso de ESO.
   Se apoya en nivelESO, de Codigo.gs, que ya entiende las formas que escribe
   Séneca. */
function cursoSecundaria_(texto) {
  return nivelESO(String(texto || '').trim());
}

/* "Inglés (1º de E.S.O.)"  ->  { materia: 'Inglés', de: '1º' }
   "Inglés"                 ->  { materia: 'Inglés', de: '' }              */
function partirMateriaSec_(texto) {
  const t = String(texto || '').replace(/\s+/g, ' ').trim();
  const m = t.match(/^(.*?)\s*\(([1-4])\s*º?\s*de\s+E\.?\s*S\.?\s*O\.?\)$/i);
  if (m) return { materia: m[1].trim(), de: m[2] + 'º' };
  return { materia: t, de: '' };
}

/* "RegDetExpEle SEC Apellido1 Apellido2, Nombre.csv" -> "Apellido1 Apellido2, Nombre"
   EL "SEC" ES OPCIONAL (BD v48, 9-sep-2026). Séneca no siempre lo pone, y lo
   que de verdad dice que un expediente es de Secundaria no es su nombre: es
   estar en la carpeta "Expedientes Secundaria". Así que
   "RegDetExpEle Apellidos, Nombre.csv" vale igual. */
function nombreDelFicheroSec_(nombreFichero) {
  let t = String(nombreFichero || '').replace(/\.csv$/i, '');
  t = t.replace(/^\s*RegDetExpEle\b\s*/i, '');
  t = t.replace(/^\s*SEC\b\s*/i, '');
  return t.replace(/^[\s_-]+/, '').replace(/\s+/g, ' ').trim();
}

/*** ================= LEER UN EXPEDIENTE =================
 *
 * CACHÉ DE EXPEDIENTES (BD v64). Igual que en Primaria.gs: leerExpedienteSec_
 * es ahora la envoltura que mira la caché (Cache.gs), y
 * leerExpedienteSecReal_ es la lectura de verdad, tal y como era antes. Su
 * resultado no lleva ninguna Date, así que se guarda en la caché tal cual. ***/

function leerExpedienteSec_(archivo) {
  /* Instrucción 45: lo guardado antes de esa versión no trae `notasPorAno`: se relee una vez. */
  return conCacheDeFichero_('SECUNDARIA', archivo, leerExpedienteSecReal_, function (r) { return r && r.notasPorAno !== undefined; });
}

function leerExpedienteSecReal_(archivo) {
  const alumno = nombreDelFicheroSec_(archivo.getName());
  const salida = {
    nombre: alumno, fichero: archivo.getName(),
    anos: [], centros: [], repeticiones: '', cursosRepetidos: [],
    cursoPasado: '', repetiaPasado: '', suspensosPasado: '',
    /* porAno: { 2024: { curso, centro, estado, suspensos } }. Es lo que
       necesita la columna Trayectoria de ALUMNADO, que enseña la historia del
       alumno año por año en una sola casilla. */
    porAno: {},
    /* notasPorAno (instrucción 45): { 2024: [[materia, nota, de], …] } con la nota FINAL de cada materia (la última
       convocatoria con nota). `de` es '1º'… si es una pendiente de un curso anterior. Es lo que guarda `_materias`. */
    notasPorAno: {},
    avisos: []
  };
  if (!alumno) {
    salida.avisos.push('El fichero "' + archivo.getName() + '" no lleva el nombre del alumno.');
    return salida;
  }

  const tabla = textoATabla(textoDeArchivo(archivo));
  if (tabla.length < 2) {
    salida.avisos.push('El fichero "' + archivo.getName() + '" está vacío.');
    return salida;
  }

  const cab = tabla[0].map(normalizar);
  const iCurso = cab.indexOf(normalizar('Curso'));
  const iAno = cab.indexOf(normalizar('Año académico'));
  const iEstado = cab.indexOf(normalizar('Estado de matrícula'));
  const iCentro = cab.indexOf(normalizar('Centro'));
  const iMateria = cab.indexOf(normalizar('Materias'));
  const iNota = cab.indexOf(normalizar('Calificaciones'));
  if (iCurso === -1 || iAno === -1) {
    salida.avisos.push('Al fichero "' + archivo.getName() + '" le faltan columnas. No lo he usado.');
    return salida;
  }

  /* Primera vuelta: en qué curso estuvo cada año, y en qué centro.
     Las líneas trasladadas no cuentan: si contaran, un traslado parecería una
     repetición. */
  const anosPorCurso = {};   // '2º' -> { 2024: true, 2025: true }
  const cursoDelAno = {};    // 2025 -> '2º'
  const centros = {};
  const detallePorAno = {};  // 2025 -> { curso, centro, estado }
  let ultimo = 0;
  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    const curso = cursoSecundaria_(fila[iCurso]);
    if (!curso) continue;
    const estado = iEstado === -1 ? '' : normalizar(fila[iEstado]);
    if (ESTADOS_QUE_NO_CUENTAN.indexOf(estado) !== -1) continue;
    const ano = parseInt(fila[iAno], 10);
    if (!ano) continue;
    if (!anosPorCurso[curso]) anosPorCurso[curso] = {};
    anosPorCurso[curso][ano] = true;
    cursoDelAno[ano] = curso;
    if (ano > ultimo) ultimo = ano;
    let centroFila = '';
    if (iCentro !== -1) {
      centroFila = String(fila[iCentro] || '').replace(/\s+/g, ' ').trim();
      if (centroFila) centros[centroFila] = true;
    }
    if (!detallePorAno[ano]) {
      detallePorAno[ano] = { curso: curso, centro: centroFila,
                             estado: String(fila[iEstado] || '').trim() };
    }
  }
  if (!ultimo) {
    salida.avisos.push('El expediente de ' + alumno + ' no trae ningún curso de ESO.');
    return salida;
  }

  /* Cuántos cursos repitió y cuáles. Un curso que aparece en dos años
     académicos distintos es un curso repetido, esté donde esté el centro. */
  let repeticiones = 0;
  const repetidos = [];
  for (let n = 1; n <= 4; n++) {
    const curso = n + 'º';
    const anos = anosPorCurso[curso];
    if (!anos) continue;
    const lista = Object.keys(anos).sort();
    if (lista.length < 2) continue;
    repeticiones += lista.length - 1;
    repetidos.push(curso + ' (' +
      lista.map(function (a) { return anoAcademico_(a); }).join(', ') + ')');
  }
  salida.repeticiones = repeticiones;
  salida.cursosRepetidos = repetidos;
  salida.centros = Object.keys(centros);
  salida.anos = Object.keys(cursoDelAno).sort();
  salida.porAno = detallePorAno;

  /* El curso pasado, y si lo estaba repitiendo. Esto es lo que el histórico de
     este centro no puede saber cuando el alumno venía de otro instituto. */
  const anoPasado = ultimo - 1;
  const cursoPasado = cursoDelAno[anoPasado] || '';
  if (cursoPasado) {
    salida.cursoPasado = cursoPasado;
    let repetia = 'NO';
    const anosDeEse = Object.keys(anosPorCurso[cursoPasado]);
    for (let q = 0; q < anosDeEse.length; q++) {
      if (parseInt(anosDeEse[q], 10) < anoPasado) repetia = 'SÍ';
    }
    salida.repetiaPasado = repetia;
  } else {
    salida.avisos.push('El expediente de ' + alumno + ' no dice en qué curso estuvo el curso ' +
      anoAcademico_(anoPasado) + '. No he tocado su curso del año pasado.');
  }

  /* Cuántas materias suspendió el año pasado. Cuentan todas las que tienen
     evaluación negativa, incluidas las pendientes de cursos anteriores: es lo
     que decide la promoción. Una materia que sale dos veces (ordinaria y
     extraordinaria) se queda con la nota más alta. Una nota vacía no es un
     suspenso: es una materia en marcha o sin calificar todavía. */
  if (iMateria !== -1 && iNota !== -1) {
    const mejores = {};   // año -> clave de materia -> mejor nota
    for (let f = 1; f < tabla.length; f++) {
      const fila = tabla[f];
      const ano = parseInt(fila[iAno], 10);
      if (!ano) continue;
      if (!cursoSecundaria_(fila[iCurso])) continue;
      const estado = iEstado === -1 ? '' : normalizar(fila[iEstado]);
      if (ESTADOS_QUE_NO_CUENTAN.indexOf(estado) !== -1) continue;
      const p = partirMateriaSec_(fila[iMateria]);
      if (!p.materia) continue;
      const clave = normalizar(p.materia) + '|' + p.de;
      const nota = fila[iNota];
      const notaTexto = String(nota === undefined || nota === null ? '' : nota).trim();
      if (notaTexto !== '') {
        const dic = salida.notasPorAno[ano] || (salida.notasPorAno[ano] = {});
        dic[clave] = [p.materia, esNumero(notaTexto) ? aNumero(notaTexto) : notaTexto, p.de];
      }
      if (!mejores[ano]) mejores[ano] = {};
      const antes = mejores[ano][clave];
      if (antes === undefined ||
          (esNumero(nota) && (!esNumero(antes) || aNumero(nota) > aNumero(antes)))) {
        mejores[ano][clave] = nota;
      }
    }
    for (const ano in mejores) {
      let suspensos = 0;
      for (const k in mejores[ano]) {
        if (esNumero(mejores[ano][k]) && aNumero(mejores[ano][k]) < 5) suspensos++;
      }
      if (detallePorAno[ano]) detallePorAno[ano].suspensos = suspensos;
      if (parseInt(ano, 10) === anoPasado) salida.suspensosPasado = suspensos;
    }
    /* De { clave: [materia, nota, de] } a una lista, para que viaje en JSON. */
    for (const ano in salida.notasPorAno) {
      const dic = salida.notasPorAno[ano];
      salida.notasPorAno[ano] = Object.keys(dic).map(function (k) { return dic[k]; });
    }
  }

  return salida;
}

/*** ================= LA CARPETA ================= ***/

let CACHE_CARPETA_SEC_;

function carpetaSecundaria_() {
  if (CACHE_CARPETA_SEC_ !== undefined) return CACHE_CARPETA_SEC_;
  let carpeta = null;
  try {
    const it = carpeta_('descargas').getFoldersByName(CARPETA_SECUNDARIA);
    if (it.hasNext()) carpeta = it.next();
  } catch (e) { /* devolvemos null y no pasa nada: la fuente es opcional */ }
  CACHE_CARPETA_SEC_ = carpeta;
  return carpeta;
}

/* Los ficheros de la carpeta de expedientes de Secundaria, listados una sola
   vez por ejecución. Igual que ficherosDeExpedientes_ en Primaria.gs: dentro
   de una misma pulsación de "Actualizar los datos" se mira dos veces (el
   panel, y datosSecundaria_ al construir la tabla), y listar Drive dos veces
   es tiempo que no hace falta gastar. */
let CACHE_FICHEROS_SEC_ = null;

function ficherosDeExpedientesSec_() {
  if (CACHE_FICHEROS_SEC_) return CACHE_FICHEROS_SEC_;
  const arr = [];
  const carpeta = carpetaSecundaria_();
  if (carpeta) {
    const it = carpeta.getFiles();
    while (it.hasNext()) arr.push(it.next());
  }
  CACHE_FICHEROS_SEC_ = arr;
  return arr;
}

/*** ================= LO QUE LLAMA Codigo.gs ================= ***/

/* Devuelve { porNombre, avisos, total, ficheros }.
   Esta fuente es OPCIONAL: si no hay carpeta o no hay ficheros, devuelve un
   mapa vacío y el sistema sigue funcionando igual que antes, con el histórico
   de este centro. No se avisa de que falte la carpeta: es lo normal. */
function datosSecundaria_(cursosDeAlumno) {
  const avisos = [];
  const carpeta = carpetaSecundaria_();
  if (!carpeta) return { porNombre: {}, avisos: avisos, total: 0, ficheros: 0 };

  const porNombre = {};
  let ficheros = 0;
  const listaFicheros = ficherosDeExpedientesSec_();
  for (let fi = 0; fi < listaFicheros.length; fi++) {
    const f = listaFicheros[fi];
    if (!/\.csv$/i.test(f.getName())) continue;
    ficheros++;
    let r;
    try {
      r = leerExpedienteSec_(f);
    } catch (e) {
      avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Expediente de Secundaria ilegible',
        detalle: f.getName() + ': ' + e.message });
      continue;
    }
    for (let i = 0; i < r.avisos.length; i++) {
      avisos.push({ curso: '', grupo: '', alumno: r.nombre,
        aviso: 'Expediente de Secundaria', detalle: r.avisos[i] });
    }
    if (!r.nombre) continue;

    /* El cruce lleva el curso, como todos los del sistema. El curso se busca
       en la matrícula de este año, porque el fichero no lo dice. */
    const nomNorm = normalizar(r.nombre);
    const posibles = (cursosDeAlumno && cursosDeAlumno[nomNorm]) || [];
    if (posibles.length > 1) {
      avisos.push({ curso: '', grupo: '', alumno: r.nombre,
        aviso: 'Expediente de Secundaria ambiguo por nombre repetido',
        detalle: 'Hay alumnado que se llama exactamente así en ' + posibles.join(' y ') +
                 '. El fichero no dice el curso, así que no sé a cuál asignarlo.' });
      continue;
    }
    const clave = nomNorm + '|' + (posibles.length === 1 ? posibles[0] : '');
    if (porNombre[clave]) {
      avisos.push({ curso: '', grupo: '', alumno: r.nombre,
        aviso: 'Dos expedientes de Secundaria para el mismo alumno',
        detalle: 'Ficheros "' + porNombre[clave].fichero + '" y "' + r.fichero +
                 '". Me he quedado con el primero.' });
      continue;
    }
    porNombre[clave] = r;
  }

  return { porNombre: porNombre, avisos: avisos,
           total: Object.keys(porNombre).length, ficheros: ficheros };
}

/*** ================= LA PESTAÑA SECUNDARIA ================= ***/

/* Igual que la de PRIMARIA: sirve para ver de un vistazo qué ha entendido el
   programa de cada expediente, sin abrir los CSV uno a uno. */
function escribirSecundaria_(porNombre, unidadesPorNombre, enAlumnado) {
  const ancho = TITULOS_SECUNDARIA.length;
  const hoja = hojaPlana_(HOJA_SECUNDARIA, ancho);   // instrucción 83: sin pintar
  hoja.getRange(1, 1).setValue('Expedientes de Secundaria descargados de Séneca, uno por alumno. ' +
    'Traen toda su vida en la ESO, incluidos los años en otros institutos, que el histórico de ' +
    'este centro no ve. Solo hacen falta los del alumnado que sale avisado en AVISOS. ' +
    'Actualizado: ' + new Date().toLocaleString('es-ES')).setFontStyle('italic');
  hoja.getRange(2, 1, 1, ancho).setValues([TITULOS_SECUNDARIA]).setFontWeight('bold')
      .setBackground('#D9D9D9').setWrap(true).setVerticalAlignment('middle');

  const filas = [];
  for (const clave in porNombre) {
    const r = porNombre[clave];
    filas.push([r.nombre,
      unidadesPorNombre[clave] || (enAlumnado[clave] ? '' : 'NO ESTÁ EN ALUMNADO'),
      r.cursoPasado, r.repetiaPasado,
      r.suspensosPasado === '' ? '' : r.suspensosPasado,
      r.repeticiones === '' ? '' : r.repeticiones,
      (r.cursosRepetidos || []).join('; '),
      (r.anos || []).map(function (a) { return anoAcademico_(a); }).join(', '),
      (r.centros || []).join(' · '),
      r.fichero]);
  }
  filas.sort(function (a, b) {
    const ka = normalizar(a[0]), kb = normalizar(b[0]);
    return ka < kb ? -1 : (ka > kb ? 1 : 0);
  });
  if (filas.length) hoja.getRange(3, 1, filas.length, ancho).setValues(filas);
  hoja.volcar();
  return filas.length;
}

/*** Bachillerato.gs ***/
/*** ================= BACHILLERATO =================
 *
 * QUÉ ES ESTO. El alumnado de Bachillerato del centro, leído de los CSV de
 * matrícula que Francisco descarga de Séneca. Entra en la misma pestaña
 * ALUMNADO que la ESO, pero por un camino aparte, y por una razón de fondo:
 * en Bachillerato NO valen las reglas de la ESO.
 *
 * - No existe el PIL. Bachillerato no es enseñanza obligatoria, así que no
 *   hay promoción por imperativo legal.
 * - No existen las dos permanencias de la enseñanza obligatoria. En
 *   Bachillerato el tope son cuatro años, y esa cuenta empieza de cero.
 * - No existe la diversificación.
 * - No hay repeticiones de Primaria que calcular, ni edad teórica que
 *   comparar.
 *
 * Por eso el alumnado de Bachillerato NO pasa por el cálculo de permanencias
 * de Codigo.gs. Sus casillas de PIL y de permanencia se quedan vacías, que es
 * lo honrado: vacío quiere decir "aquí no aplica" (punto 2 bis de CONTEXTO).
 *
 * EL CURSO SE ESCRIBE "1º BACH" Y "2º BACH", con la etapa dentro. Es
 * imprescindible: la clave de todos los cruces del sistema es nombre + curso,
 * y si Bachillerato se guardara como "1º" chocaría con 1º de la ESO. Dos
 * alumnos distintos que se llamaran igual se convertirían en uno solo. Es el
 * fallo que se arregló en la BD v26.
 *
 * Y ESE TEXTO NO SE INVENTA: se recorta de la Unidad que escribe Séneca,
 * "1º BACH A" -> "1º BACH". Así el rótulo del grupo y el curso siempre casan.
 *
 * LOS CURSOS DE LA ESO NO SE TOCAN. Siguen siendo "1º", "2º", "3º" y "4º".
 * Renombrarlos habría perdido TODO lo que Francisco tiene escrito a mano en
 * las columnas amarillas, porque esas anotaciones se guardan por nombre y
 * curso. No merece la pena por una simetría.
 *
 * SON CUATRO FICHEROS, DOS POR CURSO, uno por modalidad:
 *
 *     MatOMCMatr1ºBACH-c-26-27.csv     MatOMCMatr1ºBACH-h-26-27.csv
 *     MatOMCMatr2ºBACH-c-26-27.csv     MatOMCMatr2ºBACH-h-26-27.csv
 *
 * La letra dice la modalidad: -c- Ciencias y Tecnología, -h- Humanidades y
 * Ciencias Sociales. Ese nombre lo pone Francisco a mano, así que además se
 * comprueba por dentro, mirando qué materias trae el fichero, y si las dos
 * cosas no coinciden se avisa.
 *
 * ======================================================== ***/

/* NIVELES_BAC vive en BaseHojas.gs (instrucción 50). */
const ETAPA_BAC = 'Bachillerato';

/* El tercer valor de celda de Séneca, además de MATR y PEND. Sale en 2º y
   quiere decir que el alumno ya aprobó esa materia y este año no la cursa:
   está repitiendo 2º y solo cursa lo que le quedó. Confirmado por Francisco
   el 9-sep-2026. Tener alguna APRO es, por tanto, la señal de que repite. */
const MARCA_APROBADA = 'APRO';

/* Las dos modalidades (MODALIDAD_CIENCIAS y MODALIDAD_HUMANIDADES) viven desde la instrucción 110 en MatriculaReglas.gs, que también carga la página. */

/* Materias que delatan la modalidad. Sirven para comprobar que el nombre del
   fichero dice la verdad. */
const DELATAN_CIENCIAS = ['Física y Química', 'Dibujo Técnico', 'Química', 'Física',
  'Biología, Geología y Ciencias Ambientales', 'Biología', 'Tecnología e Ingeniería'];
const DELATAN_HUMANIDADES = ['Latín', 'Griego', 'Historia del Arte', 'Literatura Universal',
  'Economía', 'Geografía'];

/*** ================= LA MATRÍCULA SE COMPRUEBA EN Matricula.gs =================
 *
 * Hasta la BD v61 aquí había un reparto en cuatro bloques (comunes, modalidad,
 * optativas, religión) y una cuenta propia de Bachillerato, diagnosticoMatricula_,
 * distinta de la de la ESO. Desde la BD v62 la cuenta es la misma para las dos
 * etapas y vive en Matricula.gs: lo que debe tener el alumno según la pestaña
 * OFERTA y según Jefatura, contra lo que tiene en Séneca.
 *
 * Lo que queda aquí es leer los cuatro CSV y repartir lo que el alumno cursa en
 * las columnas de ALUMNADO (MAT. MODALIDAD, OPTATIVAS, REL/Atedu), según la
 * columna que diga cada línea de la pestaña OFERTA.
 * ======================================================================== ***/

/* ABREVIATURAS_BAC (las abreviaturas de las materias de Bachillerato que no están en ABREVIATURAS, Codigo.gs) vive desde la instrucción 125 en BaseHojas.gs: la web la necesita
   para dar su nombre largo a las pendientes de 2º de Bachillerato. Para cambiar una, se cambia allí y en ningún sitio más. */

/*** ================= UTILIDADES ================= ***/

/* esBachillerato_ vive en BaseFunciones.gs (instrucción 50). */

/* "1º BACH A" -> "1º BACH". Si la unidad no dice nada, se usa el curso que
   venga del nombre del fichero. */
function cursoDeUnidadBac_(unidad, porDefecto) {
  const t = String(unidad || '').trim();
  const m = t.match(/^([12])\s*º\s*BACH/i);
  if (!m) return porDefecto;
  return m[1] + 'º BACH';
}

function abreviarBac_(materia) {
  const t = String(materia || '').trim();
  if (ABREVIATURAS[t] !== undefined) return ABREVIATURAS[t];
  if (ABREVIATURAS_BAC[t] !== undefined) return ABREVIATURAS_BAC[t];
  return t;
}

/* Los títulos de las columnas de materias pendientes de 1º vienen así:
     Lengua Castellana y Literatura (1º de Bachillerato (Ciencias y Tecnología))
     Filosofía (1º de Bachillerato (Humanid.y Ciencias Social)
   Ojo con dos cosas. La primera: no vale buscar un paréntesis a secas, porque
   "Francés (Segundo Idioma)" también lo lleva y no es una pendiente. La
   segunda: en los ficheros de Humanidades el paréntesis se queda SIN CERRAR.
   Es así en el fichero de Séneca, no es un error de copia. */
function pendienteDeBac_(titulo) {
  const t = String(titulo || '').trim();
  const i = t.indexOf('(1º de Bachillerato');
  if (i <= 0) return '';
  return t.substring(0, i).trim();
}

/*** ================= LOS FICHEROS ================= ***/

/* Los CSV de matrícula de Bachillerato de la carpeta, agrupados por curso.
   Devuelve { '1º BACH': [ {archivo, modalidad}, ... ], '2º BACH': [...] }.
   Hay uno por modalidad y curso, así que aquí NO se puede hacer lo que hace
   buscarCsvsMatricula con la ESO (uno por curso): eso tiraría media clase.
   Instrucción 144: cada fichero se reconoce por su identidad (curso +
   modalidad, IdentidadFichero.gs), no por cómo esté escrito su nombre. Si la
   modalidad no sale del nombre, se mira la que dicen las materias de su
   cabecera; si tampoco sale, el fichero se lee solo, sin agruparlo con otro. */
function ficherosBachilleratoPorCurso_() {
  const porCurso = {}, mejores = {};
  const listas = ficherosPorCarpeta_();
  for (let c = 0; c < listas.length; c++) {
    const ficheros = listas[c];
    for (let i = 0; i < ficheros.length; i++) {
      const f = ficheros[i];
      const n = f.getName();
      const id = identidadMatricula_(n);
      if (!id || id.etapa !== 'BACH') continue;
      let modalidad = id.modalidad;
      if (!modalidad) {
        try { const t = textoATabla(textoDeArchivo(f)); modalidad = t.length ? modalidadPorLasMaterias_(t[0]) : ''; } catch (e) { modalidad = ''; }
      }
      /* DEL MISMO FICHERO, EL MÁS RECIENTE, esté en la carpeta que esté: puede
         haber una copia vieja ya ordenada y otra recién descargada, y a veces
         con el nombre escrito distinto. Sin esto cada alumno saldría dos veces. */
      const clave = modalidad ? id.curso + '|' + modalidad : id.curso + '|?' + n;
      if (!mejores[clave] ||
          f.getLastUpdated().getTime() > mejores[clave].archivo.getLastUpdated().getTime()) {
        mejores[clave] = { archivo: f, modalidad: modalidad, deNombre: id.modalidad, nombre: n, curso: id.curso };
      }
    }
  }
  for (const k in mejores) {
    const m = mejores[k];
    if (!porCurso[m.curso]) porCurso[m.curso] = [];
    porCurso[m.curso].push(m);
  }
  for (const cu in porCurso) {
    porCurso[cu].sort(function (a, b) { return a.nombre < b.nombre ? -1 : 1; });
  }
  return porCurso;
}

/* Qué modalidad dicen las materias que trae el fichero. Sirve para comprobar
   que el nombre del fichero no miente. */
function modalidadPorLasMaterias_(cabecera) {
  let ciencias = 0, humanidades = 0;
  for (let i = 0; i < cabecera.length; i++) {
    const t = String(cabecera[i] || '').trim();
    if (DELATAN_CIENCIAS.indexOf(t) !== -1) ciencias++;
    if (DELATAN_HUMANIDADES.indexOf(t) !== -1) humanidades++;
  }
  if (ciencias > humanidades) return MODALIDAD_CIENCIAS;
  if (humanidades > ciencias) return MODALIDAD_HUMANIDADES;
  return '';
}

/*** ================= LEER UN FICHERO ================= ***/

/* Un CSV de matrícula de Bachillerato. Devuelve los alumnos con la misma
   forma que leerMatricula de la ESO, para que componerAlumnado no note la
   diferencia: { nombre, unidad, curso, valores, pend, diver, tiene, existe,
   modalidad }.

   Las materias se reparten en las columnas que diga la pestaña OFERTA:
   MAT. MODALIDAD, OPTATIVAS y REL/Atedu. Las comunes no se enseñan. Una
   materia que no esté en la oferta se escribe con las optativas, para que no
   desaparezca, y la comprobación de Matricula.gs la saca como "sobra". */
function leerMatriculaBac_(tabla, cursoPorDefecto, modalidad) {
  const cab = tabla[0].map(function (t) { return String(t).trim(); });
  const cabN = cab.map(normalizar);
  const iNombre = cabN.indexOf(normalizar('Alumno/a'));
  const iUnidad = cabN.indexOf(normalizar('Unidad'));
  const alumnos = [], sinUnidad = [], repetidores = [];

  /* Qué es cada columna. Ver clasificarColumnas_ en Matricula.gs. */
  const C = clasificarColumnas_(cab, cursoPorDefecto, iNombre, iUnidad);
  const existe = {};
  let conColumna = 0;
  for (let c = 0; c < C.clase.length; c++) {
    const k = C.clase[c];
    if (!k || k.tipo !== 'MATERIA' || !k.lineas.length) continue;
    existe[normalizar(k.lineas[0].materia)] = true;
    conColumna++;
  }
  /* Instrucción 110: lo mismo que en Codigo.gs: las columnas de materia del CSV y, de cada alumno, cuáles tiene (y cuáles aprobadas). */
  const colsMateria = C.clase.filter(function (k) { return k && k.tipo === 'MATERIA'; }).map(function (k) { return k.titulo; });

  for (let f = 1; f < tabla.length; f++) {
    const fila = tabla[f];
    const nombre = String(fila[iNombre] || '').trim();
    if (!nombre) continue;
    const unidad = iUnidad === -1 ? '' : String(fila[iUnidad] || '').trim();
    if (!unidad) sinUnidad.push(nombre);
    const curso = cursoDeUnidadBac_(unidad, cursoPorDefecto);

    const columnas = {}, tiene = {}, aprobada = {}, pend = [], aprobadas = [], crudo = { cols: colsMateria, curso: cursoPorDefecto, clave: matriculaClaveColumnas_(cursoPorDefecto, modalidad), t: [], ap: [] };
    for (let c = 0; c < C.clase.length; c++) {
      const k = C.clase[c];
      if (!k) continue;
      const valor = String(fila[c] || '').trim().toUpperCase();
      if (!valor) continue;
      if (k.tipo === 'PEND') {
        const asig = pendienteDeBac_(k.titulo) || k.titulo;
        if (valor === PEND) pend.push(abreviarBac_(asig) + ' 1º');
        else if (valor === MARCA_APROBADA) aprobadas.push(abreviarBac_(asig) + ' 1º');
        continue;
      }
      if (!celdaMatriculada_(valor)) continue;
      crudo.t.push(k.titulo);
      if (valor === MARCA_APROBADA) crudo.ap.push(k.titulo);
      const l = k.lineas.length ? k.lineas[0] : null;
      const nm = l ? normalizar(l.materia) : normalizar(k.titulo);
      tiene[nm] = l ? l.materia : k.titulo;
      /* Una materia APRO ya la tiene aprobada de cuando repitió: cuenta para
         comprobar la matrícula (nunca "falta" ni "sobra"), pero este año no
         la cursa, así que no se escribe en el papel. */
      if (valor === MARCA_APROBADA) {
        aprobada[nm] = true;
        aprobadas.push(l ? l.abrev : abreviarBac_(k.titulo));
        continue;
      }
      const columna = l ? (l.columna || '') : 'OPTATIVAS';
      if (!columna) continue;
      if (!columnas[columna]) columnas[columna] = [];
      columnas[columna].push(l ? l.abrev : abreviarBac_(k.titulo));
    }

    /* Tener materias APRO quiere decir que repite el curso y solo cursa lo que
       le quedó. Es la única forma de saberlo desde este fichero. */
    const repite = aprobadas.length ? 'SÍ' : '';
    if (aprobadas.length) repetidores.push(nombre + ' (' + unidad + '): ya aprobadas ' + aprobadas.join(', '));

    alumnos.push({
      nombre: nombre, unidad: unidad, curso: curso, diver: false,
      valores: { 'REL/Atedu': (columnas['REL/Atedu'] || []).join(' / '), 'MODALIDAD': modalidad,
                 'MAT. MODALIDAD': (columnas['MAT. MODALIDAD'] || []).join(' '),
                 'OPTATIVAS': (columnas['OPTATIVAS'] || []).join(' ') },
      pend: pend, repiteBac: repite, tiene: tiene, aprobada: aprobada, existe: existe, modalidad: modalidad, crudo: crudo
    });
  }
  const avisoNombres = avisoNombresDeMaterias_(cursoPorDefecto, modalidad, C, tabla, celdaMatriculada_);
  return { alumnos: alumnos, sinUnidad: sinUnidad, repetidores: repetidores,
           conColumna: conColumna, avisoNombres: avisoNombres };
}

/*** ================= TODO EL BACHILLERATO ================= ***/

/* Se lee una sola vez por ejecución. Lo piden dos sitios: Codigo.gs, para
   meter a estos alumnos en ALUMNADO, y NEAE.gs, para saber a quién pertenece
   cada ficha del censo. Sin esta caché se descargarían los cuatro CSV dos
   veces y los avisos saldrían repetidos. */
let CACHE_BACHILLERATO_ = null;

/* Lee los cuatro ficheros y devuelve el alumnado agrupado por curso, con la
   misma forma que la ESO. Si no hay ficheros, devuelve vacío y no molesta. */
function alumnadoDeBachillerato_() {
  if (CACHE_BACHILLERATO_) return CACHE_BACHILLERATO_;
  const porCurso = {}, avisos = [], resumen = [], dichas = {};
  const ficheros = ficherosBachilleratoPorCurso_();
  const cursos = Object.keys(ficheros).sort();
  if (!cursos.length) {
    CACHE_BACHILLERATO_ = { porCurso: porCurso, avisos: avisos, resumen: resumen };
    return CACHE_BACHILLERATO_;
  }

  for (let i = 0; i < cursos.length; i++) {
    const curso = cursos[i];
    const lista = ficheros[curso];
    for (let j = 0; j < lista.length; j++) {
      const tabla = textoATabla(textoDeArchivo(lista[j].archivo));
      if (!tabla.length) {
        avisos.push({ curso: curso, grupo: '', alumno: '',
          aviso: 'Fichero de Bachillerato vacío', detalle: lista[j].nombre });
        continue;
      }
      const porDentro = modalidadPorLasMaterias_(tabla[0]);
      let modalidad = lista[j].modalidad;
      if (!modalidad) modalidad = porDentro;
      if (modalidad && porDentro && modalidad !== porDentro) {
        avisos.push({ curso: curso, grupo: '', alumno: '',
          aviso: 'La modalidad del nombre del fichero no cuadra con lo que trae dentro',
          detalle: lista[j].nombre + ': por el nombre es ' + modalidad + ', pero por sus ' +
            'materias parece ' + porDentro + '. He usado la del nombre. Comprueba que el ' +
            'fichero es el que crees.' });
      }
      const r = leerMatriculaBac_(tabla, curso, modalidad);
      if (!porCurso[curso]) porCurso[curso] = [];
      for (let k = 0; k < r.alumnos.length; k++) porCurso[curso].push(r.alumnos[k]);
      resumen.push(curso + ' (' + (modalidad || 'modalidad sin identificar') + '): ' +
        r.alumnos.length + ' alumnos (' + lista[j].nombre + ')');
      r.sinUnidad.forEach(function (n) {
        avisos.push({ curso: curso, grupo: '', alumno: n,
          aviso: 'Sin unidad en Séneca', detalle: 'No saldrá en ningún informe de grupo' });
      });
      r.repetidores.forEach(function (t) {
        avisos.push({ curso: curso, grupo: '', alumno: '',
          aviso: 'Repite curso y solo cursa lo que le quedó', detalle: t });
      });

      /* Los nombres de materias que no cuadran entre la oferta y este fichero,
         en una sola línea. La matrícula de cada alumno la comprueba
         Matricula.gs, no esto. */
      if (r.avisoNombres) avisos.push(r.avisoNombres);
      if (!r.conColumna) {
        avisos.push({ curso: curso, grupo: '', alumno: '',
          aviso: 'Fichero de Bachillerato sin materias',
          detalle: lista[j].nombre + ' no trae ninguna materia de la oferta de ' + curso +
            '. Puede que no sea el informe de matrícula, o que la pestaña OFERTA tenga los nombres mal.' });
      }
    }
  }
  CACHE_BACHILLERATO_ = { porCurso: porCurso, avisos: avisos, resumen: resumen };
  return CACHE_BACHILLERATO_;
}

/*** ================= EL CENSO NEAE Y EL BACHILLERATO ================= ***/

/* Cómo escribe Séneca el curso de Bachillerato en el censo NEAE y en los
   expedientes: "1º de Bachillerato (Ciencias y Tecnología)". Devuelve el
   curso tal y como lo guarda el sistema, "1º BACH", o cadena vacía si eso no
   es Bachillerato. */
function nivelBachilleratoCenso_(texto) {
  /* Vale tanto "1º de Bachillerato (Ciencias y Tecnología)", que es como lo
     escribe Séneca en el censo y en los expedientes, como "1º BACH A", que es
     como lo escribe en la Unidad de la matrícula. */
  const m = String(texto || '').trim().match(/^([12])\s*º?\s*(de\s+)?BACH/i);
  return m ? m[1] + 'º BACH' : '';
}

/* Filas con la forma de las del HISTORIAL, para que el censo NEAE pueda
   cruzar también las fichas de Bachillerato.

   POR QUÉ HACE FALTA ESTO. El censo no trae el nombre del alumno, solo sus
   iniciales, así que hay que buscar a quién pertenece cada ficha. Ese cruce
   se hace contra la pestaña HISTORIAL, y en el HISTORIAL no hay Bachillerato:
   se construye filtrando por ESO. Sin estas filas, una ficha de Bachillerato
   no encontraría a nadie y saldría como "ficha sin alumno en el centro".

   Aquí se dan las mismas columnas que necesita el cruce, sacadas de la
   matrícula: el nombre y el curso. La fecha de nacimiento va vacía, porque la
   matrícula no la trae. Consecuencia, y hay que tenerla presente: si dos
   alumnos de Bachillerato del mismo curso tuvieran las mismas iniciales, el
   empate NO se puede deshacer, así que no se escribe nada y sale un aviso.
   Es lo correcto: mejor una casilla vacía que el NEAE de otra persona. */
function filasBachilleratoParaCruce_(iNombre, iCurso, ancho) {
  const filas = [];
  const bac = alumnadoDeBachillerato_();
  for (const curso in bac.porCurso) {
    const lista = bac.porCurso[curso];
    for (let i = 0; i < lista.length; i++) {
      const fila = [];
      for (let c = 0; c < ancho; c++) fila.push('');
      fila[iNombre] = lista[i].nombre;
      fila[iCurso] = lista[i].curso;
      filas.push(fila);
    }
  }
  return filas;
}

/*** ================= LA FILA DE ALUMNADO ================= ***/

/* Los valores de un alumno de Bachillerato, listos para montar su fila de
   ALUMNADO. Solo se rellena lo que en Bachillerato significa algo. Todo lo
   demás se queda VACÍO, que quiere decir "aquí no aplica", y no con
   interrogante, que querría decir "esto lo tenemos que averiguar". */
function valoresDeBachillerato_(a, man, ficha, cursosDelCenso) {
  const v = a.valores || {};
  const pend = a.pend || [];
  return {
    'Alumno/a': a.nombre,
    'Unidad': a.unidad,
    'Curso': a.curso,
    'Repite el curso actual': a.repiteBac || '',
    'Nº pendientes': pend.length ? pend.length : '',
    'Asignaturas pendientes': pend.length ? pend.length + ': ' + pend.join(', ') : '',
    'REL/Atedu': v['REL/Atedu'] || '',
    'MODALIDAD': v['MODALIDAD'] || '',
    'MAT. MODALIDAD': v['MAT. MODALIDAD'] || '',
    'OPTATIVAS': v['OPTATIVAS'] || '',
    'MATRÍCULA': v['MATRÍCULA'] || '',
    'Nº asignaturas': v['Nº asignaturas'] === undefined ? '' : v['Nº asignaturas'],
    'Debería tener': v['Debería tener'] === undefined ? '' : v['Debería tener'],
    'Diversificación': '',
    /* EL CENSO MANDA, TAMBIÉN AQUÍ. La descarga del censo NEAE de Séneca es
       una sola y trae el centro entero: no se pide por cursos ni por etapas.
       Lo confirmó Francisco el 9-sep-2026. Por tanto, si un alumno de
       Bachillerato no está en el censo es que no tiene NEAE, y su casilla se
       queda vacía. No se conserva lo que hubiera escrito antes: un dato
       equivocado que se conserva se queda escrito para siempre, y como la
       casilla se ve llena nadie sospecha. Ya pasó una vez con dos alumnas que
       se llamaban igual.
       El parámetro cursosDelCenso se recibe por compatibilidad con la llamada
       de Codigo.gs, pero aquí no se usa: en Bachillerato no hay medias tintas. */
    'NEAE': ficha ? ficha.neae : '',
    'MEDIDAS Y RECURSOS': ficha ? ficha.medidas : '',
    'Observaciones': man[4] || ''
  };
}

/*** Jefatura.gs ***/
/*** ================= FICHERO DE JEFATURA (AGRUPAMIENTOS) =================
 *
 * HASTA LA INSTRUCCIÓN 11, tercera fuente de cada "Actualizar los datos".
 * DESDE LA INSTRUCCIÓN 12 (docs/FASE-1-WEB.md, punto 4), ya no: el Excel de
 * Jefatura desaparece, y quien manda es el reparto definitivo de la mesa de
 * agrupamiento (JefaturaModelo.gs, jefaturaDesdeModelo_). Este fichero se
 * queda solo con la LECTURA del Excel (leerJefatura_ y todo lo que necesita),
 * que ahora usa una sola vez `jefaturaImportarExcel_` (JefaturaModelo.gs)
 * para traer el reparto de 26-27 a la mesa como modelo definitivo. El
 * emparejamiento por nombre (emparejarConJefatura_) lo sigue usando
 * Codigo.gs, aunque con el adaptador el emparejamiento sea siempre exacto:
 * los nombres del reparto definitivo salen de la propia Séneca.
 *
 * El cuaderno de Jefatura se localiza POR SU NOMBRE: tiene que ser un
 * cuaderno de Google Sheets cuyo nombre contenga la palabra AGRUPAMIENTOS.
 *
 * ======================================================================== ***/

const HOJA_DISCREP    = 'DISCREPANCIAS';
const NOMBRE_JEFATURA = 'agrupamientos';

/* LOS CÓDIGOS DE JEFATURA NO SON LOS NUESTROS, y la tabla que los traduce ya
   no está escrita aquí (BD v62): sale de la pestaña OFERTA, columnas
   "Código de Jefatura" y "Abreviatura". Así hay una sola lista de materias
   en todo el programa. Se construye una vez por ejecución. */
let CACHE_TRAD_JEFATURA_ = null;
/* Si leerOferta_() falla, se anota aquí en vez de tragárselo, y leerJefatura_
   lo deja en AVISOS: sin la pestaña OFERTA los códigos de Jefatura se quedan
   sin traducir, y eso hay que poder verlo, no solo intuirlo. */
let AVISO_TRAD_JEFATURA_ = '';
function tablaTraduccionJefatura_() {
  if (CACHE_TRAD_JEFATURA_) return CACHE_TRAD_JEFATURA_;
  const tabla = {};
  try {
    const O = leerOferta_();
    for (const curso in O.porCurso) {
      const lineas = O.porCurso[curso];
      for (let i = 0; i < lineas.length; i++) {
        const abrev = lineas[i].abrev;
        if (!abrev) continue;
        tabla[codigoJef_(abrev)] = abrev;
        for (let k = 0; k < lineas[i].jef.length; k++) {
          const c = codigoJef_(lineas[i].jef[k]);
          if (c && tabla[c] === undefined) tabla[c] = abrev;
        }
      }
    }
  } catch (e) {
    AVISO_TRAD_JEFATURA_ = 'No he podido leer la pestaña OFERTA para traducir los códigos de ' +
      'Jefatura (' + e.message + '). Los códigos se han dejado tal cual venían, sin traducir.';
  }
  CACHE_TRAD_JEFATURA_ = tabla;
  return tabla;
}

/* PIL no tiene columna propia en el cuaderno: Jefatura lo escribe suelto en
   cualquier celda de la fila. Las demás marcas (exento de francés, repite,
   NEAE, conflictivo) sí tienen su columna y se leen de ahí: ver
   docs/MARCAS-JEFATURA-POR-COLUMNA.md. */
const CODIGO_PIL_JEFATURA = 'PIL';

/*** ================= LÓGICA PURA ================= ***/

/* Quita tildes y pasa a mayúsculas. Para comparar códigos, no nombres. */
function codigoJef_(v) {
  return String(v === null || v === undefined ? '' : v)
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\s+/g, ' ').trim().toUpperCase();
}

function traducirJef_(v) {
  const c = codigoJef_(v);
  if (!c) return '';
  const tabla = tablaTraduccionJefatura_();
  return tabla[c] === undefined ? c : tabla[c];
}

/* ¿Es esto el rótulo de un grupo de ESO? Devuelve "1º ESO A" o ''.
   Vale tanto para el nombre de la pestaña ("1ºESO A") como para la celda A1. */
/* Reconoce el nombre de un grupo en el cuaderno de Jefatura.

   Vale para la ESO ("3º ESO B") y, desde el 9-sep-2026, también para
   Bachillerato. La palabra de la etapa se acepta escrita de varias maneras
   —BACH, BACHILLERATO, BTO— porque el nombre de la pestaña lo escribe una
   persona a mano y no siempre lo escribe igual.

   LO QUE DEVUELVE SE ESCRIBE SIEMPRE "1º BACH A", que es como Séneca escribe
   la unidad. Si se devolviera tal cual estaba en la pestaña, un "1º
   BACHILLERATO A" no casaría con el "1º BACH A" de Séneca y saldrían todos
   los alumnos del grupo como "Grupo distinto". */
function grupoDeTexto_(v) {
  const t = String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim();
  const eso = t.match(/^([1-4])\s*º\s*ESO\s+([A-Z])$/i);
  if (eso) return eso[1] + 'º ESO ' + eso[2].toUpperCase();
  const bac = t.match(/^([12])\s*º\s*(?:BACH(?:ILLERATO)?|BTO)\.?\s+([A-Z])$/i);
  if (bac) return bac[1] + 'º BACH ' + bac[2].toUpperCase();
  return '';
}

/* El nivel al que pertenece un grupo. En la ESO son los dos primeros
   caracteres ("3º ESO B" -> "3º"). En Bachillerato el nivel lleva la etapa
   dentro ("1º BACH A" -> "1º BACH"), porque si no chocaría con 1º de la ESO y
   dos alumnos distintos con el mismo nombre se confundirían. */
function nivelDeGrupoJef_(grupo) {
  const t = String(grupo || '').trim();
  const m = t.match(/^([12])\s*º\s+BACH\b/i);
  if (m) return m[1] + 'º BACH';
  return t.substring(0, 2);
}

/* Coloca cada título de la fila 1 en el hueco que le toca.
   'h.ultimaColumna' es el índice de la última columna que tiene título: todo
   lo que Jefatura escriba a la derecha (anotaciones al margen, datos de un
   alumno entrante...) no tiene título y no se lee ni se barre, para no
   contaminar la fila del alumno de al lado (docs/MARCAS-JEFATURA-POR-COLUMNA.md). */
function huecosJefatura_(titulos, nivel) {
  const h = { ultimaColumna: -1 };
  for (let c = 0; c < titulos.length; c++) {
    const t = normalizar(titulos[c]);
    if (!t) continue;
    h.ultimaColumna = c;
    if (t === 'origen' || t === 'centro de procedencia') h.origen = c;
    /* LA COLUMNA DE RELIGIÓN. Jefatura le cambia el nombre de una pestaña a
       otra: "REL/Atedu" en la ESO, y en Bachillerato "REL/AE" (1º BACH A),
       "REL/PTEV" (1º BACH B) o "REL/ECDH" (2º BACH A). Se reconoce por lo
       único que no cambia: empieza por REL. Así no hay que tocar el programa
       cada vez que le pone otro nombre. "RELACIÓN..." no cuela, porque detrás
       de REL tiene que venir algo que no sea una letra. */
    else if (/^rel($|[^a-z0-9])/.test(t) || t.indexOf('religion') === 0) h.rel = c;
    /* La segunda optativa de los alumnos de diversificación de 3º. Jefatura la
       titula "2º OPT DIV" en 3º ESO A y "OPT 2 DIV" en 3º ESO B, así que se
       reconoce porque el título lleva las palabras OPT y DIV, vaya donde vaya. */
    else if (t.indexOf('opt') !== -1 && t.indexOf('div') !== -1) h.optdiv = c;
    else if (t === 'mat a/b') h.mat = c;
    else if (nivel === '4º' && t === 'opt1') h.opc2 = c;
    else if (nivel === '4º' && t === 'opt2') h.opc1 = c;
    else if (nivel === '4º' && t === 'opt3') h.opc3 = c;
    else if (nivel === '4º' && t === 'opt and') h.opc4 = c;
    else if (t === 'opt' || t === 'opt.' || t === 'opt 1' || t === 'opt1') h.opt = c;
    else if (t.indexOf('exento') === 0) h.alct = c;
    else if (t.indexOf('repite') === 0 || t.indexOf('repetidor') === 0) h.repite = c;
    else if (t === 'neae' || t === 'neae/c') h.neae = c;
    else if (t.indexOf('conflict') === 0) h.conf = c;
    /* Instrucción 49: el texto libre de «Observaciones» pasa a nota de la ficha (JefaturaNotas.gs). */
    else if (t.indexOf('observaciones') === 0) h.observ = c;
    /* BACHILLERATO. Sus pestañas de grupo tienen otras columnas: dos de
       materias de modalidad (MOD1, MOD2) y dos de optativas (OPT1, OPT2).
       Solo se miran en Bachillerato, para no cambiar nada de la ESO: allí
       "OPT1" ya significa otra cosa en 4º. */
    else if (esNivelBachillerato_(nivel) && t === 'mod1') h.mod1 = c;
    else if (esNivelBachillerato_(nivel) && t === 'mod2') h.mod2 = c;
    /* Jefatura escribe "OPT 2" con espacio (visto el 10-sep-2026 en 2º BACH B).
       Hasta la BD v62 solo se reconocía "OPT2" y esa columna se perdía. */
    else if (esNivelBachillerato_(nivel) && (t === 'opt2' || t === 'opt 2')) h.opt2 = c;
    /* En Humanidades, la materia de modalidad obligatoria a elegir: "MCS/LAT". */
    else if (esNivelBachillerato_(nivel) && /^(mcs|lat|mat)\s*\/\s*(mcs|lat|mat)$/.test(t)) h.mod0 = c;
  }
  return h;
}

/* ¿Este nivel es de Bachillerato? El nivel de un grupo de Bachillerato se
   escribe con la etapa dentro: "1º BACH". */
function esNivelBachillerato_(nivel) {
  return /^[12]\s*º\s+BACH$/i.test(String(nivel || '').trim());
}

/* Convierte una pestaña de grupo en filas de alumno.
   'grupo' viene del nombre de la pestaña.
   'valores' incluye la fila 1 (títulos) y todo lo que hay debajo. */
function leerPestanaJefatura_(grupo, valores) {
  if (!grupo || !valores || !valores.length) return [];
  const nivel = nivelDeGrupoJef_(grupo);
  const titulos = valores[0];
  const h = huecosJefatura_(titulos, nivel);
  const alumnos = [];

  /* Exento de francés, repite, NEAE y conflictivo: cada una de su columna, no
     barriendo la fila. Si la pestaña no trae esa columna, la marca se queda
     sin marcar para todos sus alumnos: no hay barrido de respaldo. */
  const marcada = function (fila, col) {
    if (col === undefined) return false;
    return String(fila[col] === null || fila[col] === undefined ? '' : fila[col]).trim() !== '';
  };
  const columnasDeMarca = [h.alct, h.repite, h.neae, h.conf].filter(function (c) { return c !== undefined; });

  for (let f = 1; f < valores.length; f++) {
    const fila = valores[f];
    const nombre = String(fila[1] === null || fila[1] === undefined ? '' : fila[1]).trim();
    if (!nombre || nombre.indexOf(',') === -1) continue;

    /* PIL y diversificación no tienen columna propia: se siguen buscando por
       la fila, pero solo dentro de las columnas con título y saltando las
       cuatro columnas que ya tienen su propia marca (apartado 2.3 de
       docs/MARCAS-JEFATURA-POR-COLUMNA.md). */
    let div = false, pil = false;
    for (let c = 0; c <= h.ultimaColumna; c++) {
      if (columnasDeMarca.indexOf(c) !== -1) continue;
      const v = codigoJef_(fila[c]);
      if (!v) continue;
      if (v === 'DIV' || v.indexOf('DIVER') === 0) div = true;
      if (v === CODIGO_PIL_JEFATURA) pil = true;
    }
    const dame = function (k) { return h[k] === undefined ? '' : traducirJef_(fila[h[k]]); };

    alumnos.push({
      nombre: nombre,
      unidad: grupo,
      curso: nivel,
      origen: h.origen === undefined ? '' : String(fila[h.origen] || '').trim(),
      rel: dame('rel'),
      /* Los alumnos de diversificación de 3º cursan dos optativas: la suya y
         Música, que Jefatura pone en esa columna aparte. En Séneca las dos salen
         en la misma casilla, separadas por una barra, así que aquí se juntan
         igual para que se puedan comparar. */
      opt: [dame('opt'), dame('optdiv')].filter(function (x) { return x; }).join(' / '),
      optdiv: dame('optdiv'),
      mat: dame('mat'),
      opc1: dame('opc1'),
      opc2: dame('opc2'),
      opc3: dame('opc3'),
      opc4: dame('opc4'),
      /* En 1º la columna FR -> ALCT de ALUMNADO ya no se queda vacía: pone FR
         o ALCT. Aquí se hace lo mismo para poder compararlas: en 1º, quien no
         está marcado como exento es que cursa francés. */
      alct: marcada(fila, h.alct) ? 'ALCT' : (nivel === '1º' ? 'FR' : ''),
      /* Las columnas de materias de Bachillerato, TAL Y COMO LAS ESCRIBE
         JEFATURA, sin traducir: la de modalidad obligatoria (MCS/LAT), dos de
         modalidad, dos de optativas y la de religión (la titula "REL/ECD").
         Las traduce Matricula.gs con la pestaña OFERTA.
         La religión se añadió en la BD v66: hasta entonces se quedaba fuera y
         el cuadro "Religión o Proyecto transversal" no se comparaba nunca con
         Jefatura. Lo vio Francisco el 11-sep-2026.
         SOLO EN BACHILLERATO. En la ESO esta lista va vacía a propósito: allí
         la religión se compara por su cuenta, ya traducida, en el hueco 'rel'. */
      bac: !esNivelBachillerato_(nivel) ? [] :
        [h.mod0, h.mod1, h.mod2, h.opt, h.opt2, h.rel].map(function (col) {
          return col === undefined ? '' : String(fila[col] === null || fila[col] === undefined ? '' : fila[col]).trim();
        }),
      /* Instrucción 49: lo escrito en «Observaciones» y en las celdas sin título a la derecha (JefaturaNotas.gs). */
      notas: notasDeFilaExcel_(fila, h),
      repite: marcada(fila, h.repite) ? 'SÍ' : '',
      pil: pil ? 'SÍ' : '',
      conf: marcada(fila, h.conf) ? 'SÍ' : '',
      neae: marcada(fila, h.neae) ? 'NEAE' : '',
      div: div ? 'SÍ' : ''
    });
  }
  return alumnos;
}

/* Busca el fichero de Jefatura por su nombre, sin abrirlo. Devuelve
   { archivo, sinConvertir }: 'archivo' es el más reciente que sea una Hoja de
   cálculo de Google, o null si no hay ninguno; 'sinConvertir' es el nombre de
   un Excel sin convertir, si es lo único que se ha encontrado.
   Usa la misma caché de ficheros que buscarCsv (Codigo.gs), así que no vuelve
   a listar Drive si ya se ha mirado antes en esta misma ejecución. */
function buscarFicheroJefatura_() {
  const listas = ficherosPorCarpeta_();
  let sinConvertir = '', mejor = null;
  for (let c = 0; c < listas.length; c++) {
    const ficheros = listas[c];
    for (let i = 0; i < ficheros.length; i++) {
      const f = ficheros[i];
      if (normalizar(f.getName()).indexOf(NOMBRE_JEFATURA) === -1) continue;
      if (f.getMimeType() === MimeType.GOOGLE_SHEETS) {
        /* SE MIRAN TODOS Y GANA EL MÁS RECIENTE. Antes se cogía el primero que
           apareciera, y desde que la carpeta tiene estructura (BD v54) eso
           podía ser la versión vieja, ya ordenada, en vez de la que Jefatura
           acaba de pasar y todavía está suelta en la carpeta de descargas. */
        if (!mejor || f.getLastUpdated().getTime() > mejor.getLastUpdated().getTime()) mejor = f;
        continue;
      }
      sinConvertir = f.getName();
    }
  }
  return { archivo: mejor, sinConvertir: sinConvertir };
}

/* Busca el cuaderno de Jefatura por su nombre Y LO ABRE. Devuelve
   {libro, nombre} o {aviso: '...'} si no lo encuentra o si está sin convertir. */
function buscarLibroJefatura_(encontrado) {
  const r = encontrado || buscarFicheroJefatura_();
  if (r.archivo) {
    return { libro: SpreadsheetApp.openById(r.archivo.getId()), nombre: r.archivo.getName(),
      cambio: r.archivo.getLastUpdated().toISOString() };
  }
  if (r.sinConvertir) {
    return { aviso: 'He encontrado "' + r.sinConvertir + '", pero es un Excel sin convertir. ' +
      'Ábrelo en Drive y usa Archivo > Guardar como Hojas de cálculo de Google.' };
  }
  return { aviso: 'No he encontrado ningún cuaderno cuyo nombre contenga "AGRUPAMIENTOS".' };
}

/* Lee el cuaderno entero. Devuelve {alumnos, nombre, avisos}.
   Instrucción 84: si el Excel no ha cambiado desde la última vez (misma fecha, misma versión del programa y misma oferta), se devuelve lo que ya se leyó sin abrirlo
   (ActualizacionMemoria.gs). */
function leerJefatura_() {
  if (typeof jefaturaConMemoria_ !== 'function') return leerJefaturaDeVerdad_();
  const encontrado = buscarFicheroJefatura_();
  return jefaturaConMemoria_(encontrado, function () { return leerJefaturaDeVerdad_(encontrado); });
}

function leerJefaturaDeVerdad_(encontrado) {
  const r = buscarLibroJefatura_(encontrado);
  if (!r.libro) return { alumnos: [], nombre: '', avisos: [r.aviso] };

  const alumnos = [], avisos = [], vistos = {}, saltadas = [];
  /* Los códigos que Jefatura escribe y que la pestaña OFERTA no sabe leer, sin
     repetir. Se dicen al final, en un solo aviso. */
  const codigosSinLeer = {};
  const hojas = r.libro.getSheets();
  let grupos = 0;
  for (let h = 0; h < hojas.length; h++) {
    const hoja = hojas[h];

    /* El grupo lo manda el NOMBRE de la pestaña. Es importante: el cuaderno
       tiene además pestañas de resumen ("TODO 1º", "1º ESO CON OPT.") que
       llevan el mismo rótulo en A1 y repetirían a todos los alumnos. */
    const grupo = grupoDeTexto_(hoja.getName());
    if (!grupo) { saltadas.push(hoja.getName()); continue; }
    if (hoja.getLastRow() < 2 || hoja.getLastColumn() < 2) continue;
    const enA1 = grupoDeTexto_(hoja.getRange(1, 1).getValue());
    if (enA1 && enA1 !== grupo) {
      avisos.push({ curso: nivelDeGrupoJef_(grupo), grupo: grupo, alumno: '',
        aviso: 'Pestaña de Jefatura con dos nombres distintos',
        detalle: 'La pestaña se llama "' + hoja.getName() + '" pero en A1 pone "' + enA1 + '". No la he leído.' });
      continue;
    }
    grupos++;
    const ancho = Math.min(hoja.getLastColumn(), 40);
    const leidos = leerPestanaJefatura_(grupo, hoja.getRange(1, 1, hoja.getLastRow(), ancho).getValues());
    for (let i = 0; i < leidos.length; i++) {
      /* Nombre y curso, como todos los cruces del sistema: dos alumnos
         distintos pueden llamarse igual y no se pueden descartar uno a otro. */
      const clave = normalizar(leidos[i].nombre) + '|' + leidos[i].curso;
      if (vistos[clave]) {
        avisos.push({ curso: leidos[i].curso, grupo: leidos[i].unidad, alumno: leidos[i].nombre,
          aviso: 'Repetido en el fichero de Jefatura',
          detalle: 'Aparece en ' + vistos[clave] + ' y también en ' + leidos[i].unidad });
        continue;
      }
      vistos[clave] = leidos[i].unidad;
      try {
        const lineasCurso = ofertaDeCurso_(leidos[i].curso);
        const cods = codigosDeJefatura_(leidos[i]);
        for (let b = 0; b < cods.length; b++) {
          if (!lineaDeCodigoJef_(lineasCurso, cods[b])) codigosSinLeer[leidos[i].curso + ' · ' + cods[b]] = true;
        }
      } catch (e) { /* sin oferta no se puede comprobar */ }
      alumnos.push(leidos[i]);
    }
  }
  /* LOS CÓDIGOS QUE LA PESTAÑA OFERTA NO SABE LEER. Un código que no se sabe
     leer no se compara, y en MATRÍCULA ese cuadro se comprueba contando. */
  const listaCodigos = Object.keys(codigosSinLeer).sort();
  if (listaCodigos.length) {
    avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'Códigos de Jefatura que no sé leer',
      detalle: listaCodigos.join(' · ') + '. Escríbelos en la columna "Código de Jefatura" de la ' +
        'pestaña OFERTA, en la línea de la materia que es cada uno, y se comparan también.' });
  }

  /* Qué pestañas no se han leído. Casi siempre son las de resumen ("TODO 1º",
     "1º ESO CON OPT."), y está bien que no se lean. Pero si alguna pestaña de
     grupo tiene el nombre escrito de otra manera, aquí es donde se ve. */
  if (saltadas.length) {
    avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'Pestañas del cuaderno de Jefatura que no he leído',
      detalle: saltadas.join(' · ') + '. Solo se leen las que se llaman como un grupo, ' +
        'tipo "3º ESO B" o "1º BACH A". Si alguna de estas es un grupo, dime cómo se llama.' });
  }

  if (!grupos) {
    avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'El cuaderno de Jefatura no tiene grupos',
      detalle: 'Ninguna pestaña de "' + r.nombre + '" se llama como un grupo, tipo "3º ESO B".' });
  }
  if (AVISO_TRAD_JEFATURA_) {
    avisos.push({ curso: '', grupo: '', alumno: '',
      aviso: 'No he podido traducir los códigos de Jefatura', detalle: AVISO_TRAD_JEFATURA_ });
  }
  return { alumnos: alumnos, nombre: r.nombre, cambio: r.cambio || '', avisos: avisos };
}

/*** ================= ESCRITURA =================
 *
 * Instrucción 12 (docs/FASE-1-WEB.md, punto 4.4): JEFATURA y DISCREPANCIAS
 * ya no se escriben. Las escribían escribirJefatura_ y escribirDiscrepancias_
 * (con compararJefatura_ para calcular las diferencias); las tres se han
 * quitado de aquí porque ya no las llama nadie: el reparto definitivo se ve
 * en la mesa de agrupamiento, y sus diferencias con Séneca, en CAMBIOS
 * SÉNECA (MesaCambios.gs, instrucción 9), que hace la misma comparación
 * mejor (alumno a alumno). `filaJefatura_` y `TITULOS_JEFATURA` tampoco se
 * usan ya, y se han quitado con ellas.
 * ======================================================== ***/

/*** JefaturaModelo.gs ***/
/*** ================= EL REPARTO DEFINITIVO, EN VEZ DEL EXCEL DE JEFATURA =================
 *
 * Instrucción 12 (docs/FASE-1-WEB.md, punto 4). Adiós al Excel «AGRUPAMIENTOS»: a partir de
 * ahora, quien manda es el modelo marcado "definitivo" de cada curso en la mesa de
 * agrupamiento, más las marcas de `_mesa_marcas` (conflictivo, pide bilingüe, exento de
 * francés). `jefaturaDesdeModelo_(curso)` da la MISMA forma que daba `leerJefatura_`
 * (Jefatura.gs): `{alumnos, nombre, avisos}`, para no tener que tocar Matricula.gs ni
 * Cuadre.gs: siguen leyendo exactamente los mismos campos de cada alumno
 * (`codigosDeJefatura_`, Matricula.gs).
 *
 * DE DÓNDE SALE CADA COSA AHORA (tabla 4.2 de la instrucción):
 *   - Grupo, optativas, religión/AE, MAT A/B, modalidad y optativas de Bachillerato:
 *     del modelo definitivo (`asignaciones[clave]`, ampliado en MesaDatos.gs y JsMesaReparto.html
 *     para guardar TODAS las franjas, no solo grupo y una optativa).
 *   - Conflictivo, pide bilingüe, exento de francés: `_mesa_marcas` (MesaAlmacen.gs).
 *   - Repite, PIL, NEAE, diversificación: la BD, desde Séneca (`mesaAlumnosDeCurso_`, que ya
 *     los calcula; no cambia).
 *   - Colegio de procedencia: el expediente de Primaria / RegAlum (ya lo hacía).
 *   - Clase de 6º: lo que trajera el Excel al importarlo (`jefaturaImportarExcel_`, abajo);
 *     no hay otra fuente todavía (llegará con la admisión, fase 4).
 *
 * `leerJefatura_` (Jefatura.gs) NO SE TOCA: sigue siendo la lectura del Excel de verdad, pero
 * ahora la usa solo `jefaturaImportarExcel_`, una vez, no cada "Actualizar los datos".
 *
 * ======================================================== ***/

/* Los "cursos" (grados) que puede tener la mesa. Ni ALUMNADO ni _mesa_modelos
   dan por sí solos una lista fiable antes de reconstruir la tabla (todavía
   tienen los datos de la vez anterior), así que la lista es la de siempre:
   los mismos seis grados que ya usa toda la mesa (mesaOrdenCurso_, MesaDatos.gs). */
const GRADOS_MESA_ = ['1º', '2º', '3º', '4º', '1º BACH', '2º BACH'];

function jefaturaDesdeModelo_() {
  const avisos = [];
  const alumnos = [];
  const marcas = mesaLeerMarcas_();
  let algunDefinitivo = false;

  GRADOS_MESA_.forEach(function (grado) {
    let definitivo = mesaListarModelosCompletos_(grado).filter(function (m) { return m.definitivo; })[0];
    if (!definitivo) return;
    algunDefinitivo = true;
    try { definitivo = mesaModeloVigente_(definitivo, grado, cursoEscolar_()); } catch (e) { /* sin la regla, el modelo tal cual */ }   // instrucción 73: un grupo que ya no existe es «Sin grupo»

    let sinAsignacion = 0;
    mesaAlumnosDeCurso_(grado).forEach(function (al) {
      const asign = definitivo.asignaciones[al.clave];
      if (!asign) { sinAsignacion++; return; }
      const guardada = marcas[al.clave] || {};
      alumnos.push({
        nombre: al.nombre, unidad: asign.grupo || 'Sin grupo', curso: grado,
        origen: asign.origen || '',
        rel: asign.rel || '', opt: asign.opt || '', optdiv: '',
        mat: asign.mat || '',
        opc1: asign.opc1 || '', opc2: asign.opc2 || '', opc3: asign.opc3 || '', opc4: asign.opc4 || '',
        alct: guardada.exentoFrances ? 'ALCT' : (asign.alct || (grado === '1º' ? 'FR' : '')),
        bac: asign.bac || [],
        repite: al.rep ? 'SÍ' : '',
        pil: al.pil ? 'SÍ' : '',
        conf: guardada.conflictivo ? 'SÍ' : '',
        neae: al.neae ? 'NEAE' : '',
        div: al.div ? 'SÍ' : ''
      });
    });
    if (sinAsignacion) {
      avisos.push({ curso: grado, grupo: '', alumno: '',
        aviso: 'Alumnado sin grupo en el reparto definitivo',
        detalle: sinAsignacion + ' alumno(s) de ' + grado + ' no está(n) en el modelo "' +
          definitivo.nombre + '". Colócalo(s) en la mesa de agrupamiento.' });
    }
  });

  if (!algunDefinitivo) {
    avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Sin reparto definitivo',
      detalle: 'Ningún curso tiene todavía un modelo marcado como definitivo en la mesa de ' +
        'agrupamiento: no se puede comparar la matrícula contra ningún reparto.' });
  }
  return { alumnos: alumnos, nombre: 'Reparto definitivo de la mesa de agrupamiento', avisos: avisos };
}

/* La misma forma que da la mesa para "grupoOrigen" (mesaAlumnosDeCurso_,
   MesaDatos.gs), pero desde el modelo en vez de la pestaña JEFATURA (que
   deja de escribirse). Se usa desde ahí, no desde aquí. */
function origenDesdeModelo_(grado, clave) {
  const definitivo = mesaListarModelosCompletos_(grado).filter(function (m) { return m.definitivo; })[0];
  if (!definitivo) return '';
  const asign = definitivo.asignaciones[clave];
  return (asign && asign.origen) || '';
}

/* Para el botón de la web: ¿ya se ha hecho la importación alguna vez? Basta
   con que exista un modelo "Jefatura 26-27" en cualquier grado. */
function jefaturaYaImportada_() {
  return GRADOS_MESA_.some(function (grado) {
    return mesaListarModelos_(grado).some(function (m) { return m.nombre === 'Jefatura 26-27'; });
  });
}

/*** ================= IMPORTAR EL EXCEL, UNA SOLA VEZ ================= ***/

/* Botón "Traer el reparto de Jefatura de 26-27" (instrucción 12, punto 4.3):
   lee el Excel con la lectura de siempre (Jefatura.gs, sin tocar) y crea, en
   cada curso, un modelo "Jefatura 26-27". Si el curso YA tiene un modelo
   definitivo, no se pisa: se crea el importado sin marcarlo definitivo y se
   avisa (puede que la mesa ya tenga trabajo hecho desde entonces). También
   copia a _mesa_marcas el exento de francés y el conflictivo, sin pisar lo
   que ya hubiera escrito la mesa. */
function jefaturaImportarExcel_(correo) {
  const J = leerJefatura_();
  if (!J.alumnos.length) {
    return { ok: false, motivo: 'No he podido leer el Excel de Jefatura: ' +
      (J.avisos[0] || 'no se ha encontrado ningún alumno.') };
  }

  const porGrado = {};
  J.alumnos.forEach(function (a) { (porGrado[a.curso] = porGrado[a.curso] || []).push(a); });

  const resultado = { creados: [], yaDefinitivo: [], marcasCopiadas: 0 };
  const marcas = mesaLeerMarcas_();

  Object.keys(porGrado).forEach(function (grado) {
    const alumnosJef = porGrado[grado];
    const alumnosMesa = mesaAlumnosDeCurso_(grado);
    const porNombre = {};
    alumnosMesa.forEach(function (al) { porNombre[normalizar(al.nombre)] = al; });

    const asignaciones = {};
    let sinCasar = 0;
    alumnosJef.forEach(function (aj) {
      const al = porNombre[normalizar(aj.nombre)];
      if (!al) { sinCasar++; return; }
      asignaciones[al.clave] = {
        grupo: aj.unidad, optativa: aj.opt || aj.rel || '',
        opt: aj.opt || '', opc1: aj.opc1 || '', opc2: aj.opc2 || '', opc3: aj.opc3 || '', opc4: aj.opc4 || '',
        mat: aj.mat || '', alct: aj.alct || '', rel: aj.rel || '', bac: aj.bac || [],
        origen: aj.origen || ''
      };

      /* Conflictivo y exento de francés: solo si la mesa no tiene ya algo
         guardado para este alumno (nunca se pisa lo que Jefatura ha escrito
         a mano en la mesa después del Excel). */
      if (!marcas[al.clave]) {
        if (aj.conf === 'SÍ') { mesaGuardarMarca_(al.clave, 'conflictivo', true); resultado.marcasCopiadas++; }
        if (aj.alct === 'ALCT') { mesaGuardarMarca_(al.clave, 'exentoFrances', true); resultado.marcasCopiadas++; }
      }
    });

    const yaDefinitivo = mesaListarModelosCompletos_(grado).some(function (m) { return m.definitivo; });
    const creado = mesaCrearModeloAlmacen_(grado, 'Jefatura 26-27',
      { asignaciones: asignaciones, reglas: { fijar: [], juntar: [], separar: [] }, criterios: {} }, correo);
    if (!yaDefinitivo) {
      mesaMarcarDefinitivoAlmacen_(creado.id, grado);
      resultado.creados.push({ curso: grado, sinCasar: sinCasar });
    } else {
      resultado.yaDefinitivo.push({ curso: grado, sinCasar: sinCasar });
    }
  });

  return { ok: true, resultado: resultado };
}

/*** JefaturaSincronizar.gs ***/
/*** ================= EL EXCEL DE JEFATURA MANDA EN EL CURSO EN MARCHA =================
 *
 * Instrucción 28 (docs/LECTURA-REPARTO-JEFATURA.md). Desde la instrucción 12 el Excel
 * «AGRUPAMIENTOS» se traía UNA sola vez (`jefaturaImportarExcel_`, JefaturaModelo.gs), y el
 * modelo importado no pisaba un definitivo que ya existiera. Resultado: el sistema decía lo que
 * decía un modelo viejo o una foto vieja, no lo que dice el Excel.
 *
 * Ahora, en cada «Actualizar los datos», mientras el Excel exista: se vuelve a leer y el modelo
 * «Jefatura 26-27» de cada grado que trae se pone al día (o se crea) y pasa a ser el definitivo
 * de ese grado. Los demás modelos de la mesa no se tocan. En `_mesa_marcas` el exento de francés
 * se iguala al Excel; el conflictivo solo se añade (puede venir también del tránsito).
 *
 * Devuelve las líneas de `AVISOS` con el recuento. Si no hay Excel, no hace nada y no dice nada.
 * ======================================================== ***/

/* NOMBRE_MODELO_JEFATURA_ y fechaCortaExcel_: en JefaturaCodigos.gs y JefaturaDejar.gs (la pantalla los usa sin arrastrar este fichero). */

/* Una sola lectura del Excel por ejecución: se llama antes y después de reconstruir ALUMNADO. */
let CACHE_EXCEL_SINCRONIZAR_ = null;

/* Lo que compara «reparto distinto»: grupo, optativas, MAT A/B, religión, francés/ALCT y Bachillerato. */
function huellaRepartoJefatura_(a) {
  return [a.grupo || '', a.opt || '', a.opc1 || '', a.opc2 || '', a.opc3 || '', a.opc4 || '',
    a.mat || '', a.rel || '', a.alct || '', (a.bac || []).join('|')].join('¬');
}

/* Lo mismo, con el exento de francés ya resuelto como lo resuelve el adaptador
   (`jefaturaDesdeModelo_`): la marca de la mesa manda sobre el modelo. */
function huellaDeModelo_(asign, marca, grado) {
  const a = Object.assign({}, asign);
  a.alct = (marca && marca.exentoFrances) ? 'ALCT' : (asign.alct || (grado === '1º' ? 'FR' : ''));
  return huellaRepartoJefatura_(a);
}

/* `opciones` (solo el botón «Dejar el Excel de Jefatura», JefaturaDejar.gs): { ahora, inicio, limiteMs, excluirGrados }. Con límite de
   tiempo, los grados que no caben quedan en `faltan` y no se pierde lo ya hecho. */
function jefaturaSincronizarExcel_(sinAvisos, opciones) {
  opciones = opciones || {};
  const salida = { avisos: [], leido: false, distintos: 0, grados: {}, sinEmparejar: [], notasNuevas: 0, faltan: [], hechos: [],
    nombreExcel: '', cambioExcel: '', codigosSinResolver: 0 };
  /* Instrucción 49: con el Excel dejado, no se lee; manda la mesa. Los alumnos nuevos se colocan con lo que diga Séneca. */
  const dejado = excelJefaturaEstado_();
  /* Instrucción 65: un curso que nunca tuvo Excel (cualquiera que no sea el de CURSO_EXCEL_JEFATURA_) también se rige por la mesa: no hay nada que leer. */
  if (!dejado.dejado && cursoEscolar_() !== CURSO_EXCEL_JEFATURA_) {
    if (sinAvisos) mesaSincronizarSinExcel_().forEach(function (a) { salida.avisos.push(a); });
    return salida;
  }
  if (dejado.dejado) {
    if (!sinAvisos) {
      salida.avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Excel de Jefatura dejado',
        detalle: 'El Excel de Jefatura se dejó de leer el ' + fechaCortaExcel_(dejado.cuando) + ' (' + dejado.quien + '). Manda la mesa de agrupamiento.' });
    } else {
      try {
        const n = jefaturaAlumnosNuevos_();
        if (n.nuevos.length) salida.avisos.push(n.aviso);
      } catch (e) { /* se reintenta en la siguiente actualización */ }
    }
    return salida;
  }
  let J;
  try {
    J = CACHE_EXCEL_SINCRONIZAR_ || (CACHE_EXCEL_SINCRONIZAR_ = leerJefatura_());
  } catch (e) {
    salida.avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'No he podido releer el Excel de Jefatura',
      detalle: e.message + ' Se sigue con el reparto definitivo que ya había en la mesa.' });
    return salida;
  }
  if (!J.alumnos.length) return salida;
  salida.leido = true;
  salida.nombreExcel = J.nombre; salida.cambioExcel = J.cambio || '';

  const ahora = opciones.ahora || function () { return Date.now(); };
  const excluir = opciones.excluirGrados || [];
  const porGrado = {};
  J.alumnos.forEach(function (a) { (porGrado[a.curso] = porGrado[a.curso] || []).push(a); });
  const marcas = mesaLeerMarcas_();
  const sinEmparejar = [];
  const paresNotas = [], codigosCalculados = [], codigosConocidos = {};
  const codigosExistentes = codigosExcelFilas_();
  let distintos = 0, modelosPuestosAlDia = 0;

  Object.keys(porGrado).forEach(function (grado) {
    if (excluir.indexOf(grado) !== -1) return;
    if (salida.faltan.length || (opciones.limiteMs !== undefined && ahora() - opciones.inicio > opciones.limiteMs)) {
      salida.faltan.push(grado);
      return;
    }
    const porNombre = {};
    const alumnosSeneca = mesaAlumnosDeCurso_(grado);
    alumnosSeneca.forEach(function (al) { porNombre[normalizar(al.nombre)] = al; });

    const modelos = mesaListarModelosCompletos_(grado);
    const definitivoActual = modelos.filter(function (m) { return m.definitivo; })[0];
    const propio = modelos.filter(function (m) { return m.nombre === NOMBRE_MODELO_JEFATURA_; })[0];

    const asignaciones = {};
    porGrado[grado].forEach(function (aj) {
      const al = porNombre[normalizar(aj.nombre)];
      if (!al) { sinEmparejar.push(aj); return; }
      if ((aj.notas || []).length) paresNotas.push({ alumnoJ: aj, claveMesa: al.clave });
      asignaciones[al.clave] = {
        grupo: aj.unidad, optativa: aj.opt || aj.rel || '',
        opt: aj.opt || '', opc1: aj.opc1 || '', opc2: aj.opc2 || '', opc3: aj.opc3 || '', opc4: aj.opc4 || '',
        mat: aj.mat || '', alct: aj.alct || '', rel: aj.rel || '', bac: aj.bac || [],
        origen: aj.origen || ''
      };
      /* ¿Tenía este alumno un reparto distinto del Excel? (contra lo que el sistema decía). */
      const antes = definitivoActual && definitivoActual.asignaciones[al.clave];
      if (!antes || huellaDeModelo_(antes, marcas[al.clave], grado) !== huellaRepartoJefatura_(asignaciones[al.clave])) {
        distintos++;
      }
      /* Marcas: el exento de francés se iguala al Excel; el conflictivo solo se añade. */
      const m = marcas[al.clave] || {};
      const exento = aj.alct === 'ALCT';
      if (!!m.exentoFrances !== exento) {
        mesaGuardarMarca_(al.clave, 'exentoFrances', exento);
        marcas[al.clave] = Object.assign({}, m, { exentoFrances: exento });
      }
      if (aj.conf === 'SÍ' && !m.conflictivo) {
        mesaGuardarMarca_(al.clave, 'conflictivo', true);
        marcas[al.clave] = Object.assign({}, marcas[al.clave] || m, { conflictivo: true });
      }
    });

    /* Instrucción 49: los códigos que no se saben leer, con su propuesta. */
    try {
      const r = codigosExcelDeGrado_(grado, porGrado[grado], porNombre, alumnosSeneca, codigosExistentes);
      r.calculados.forEach(function (c) { codigosCalculados.push(c); });
      Object.keys(r.conocidos).forEach(function (k) { codigosConocidos[k] = true; });
    } catch (e) { /* sin propuesta de códigos no se rompe la lectura: queda el aviso de siempre */ }

    if (propio) {
      /* Solo se escribe si algo ha cambiado: sin cambios, el modelo no sube de versión. */
      const mismos = Object.keys(asignaciones).length === Object.keys(propio.asignaciones).length &&
        Object.keys(asignaciones).every(function (k) {
          const p = propio.asignaciones[k];
          return p && huellaRepartoJefatura_(p) === huellaRepartoJefatura_(asignaciones[k]) &&
            (p.origen || '') === (asignaciones[k].origen || '');
        });
      if (!mismos) {
        const r = mesaGuardarModeloAlmacen_(propio.id, {
          asignaciones: asignaciones, reglas: propio.reglas, criterios: propio.criterios,
          definitivo: propio.definitivo
        }, propio.version, 'Excel de Jefatura');
        if (r.ok) modelosPuestosAlDia++;
      }
      if (!propio.definitivo) mesaMarcarDefinitivoAlmacen_(propio.id, grado);
    } else {
      const creado = mesaCrearModeloAlmacen_(grado, NOMBRE_MODELO_JEFATURA_,
        { asignaciones: asignaciones, reglas: { fijar: [], juntar: [], separar: [] }, criterios: {} },
        'Excel de Jefatura');
      mesaMarcarDefinitivoAlmacen_(creado.id, grado);
      modelosPuestosAlDia++;
    }
    salida.grados[grado] = porGrado[grado].length;
    salida.hechos.push(grado);
  });

  /* Instrucción 49: la tabla de códigos y las notas, una sola escritura cada una. */
  try {
    const comb = codigosExcelCombinar_(codigosExistentes, codigosCalculados, codigosConocidos, new Date().toISOString());
    if (comb.cambiado) codigosExcelEscribir_(comb.filas);
  } catch (e) { /* la lectura sigue */ }
  try { salida.notasNuevas = jefaturaNotasPasar_(paresNotas); } catch (e) { /* las notas se reintentan en la siguiente lectura */ }
  salida.codigosSinResolver = codigosExcelSinResolver_().length;
  if (!salida.faltan.length) {
    try { excelJefaturaGuardar_('lectura', JSON.stringify({ nombre: J.nombre, cambio: J.cambio || '' }), ''); } catch (e) { /* no es esencial */ }
  }
  salida.sinEmparejar = sinEmparejar.map(function (aj) {
    return { nombre: aj.nombre, unidad: aj.unidad, curso: aj.curso, texto: (aj.notas || []).map(textoNotaExcel_) };
  });

  salida.distintos = distintos;
  if (!sinAvisos) {
    salida.avisos.push({ curso: '', grupo: '', alumno: '', aviso: 'Reparto de Jefatura releído del Excel',
      detalle: distintos
        ? distintos + ' alumno(s) tenían un reparto distinto al del Excel «' + J.nombre + '»; ya está puesto al día ' +
          '(optativas, MAT A/B, francés/ALCT, religión).'
        : 'Ningún alumno tenía un reparto distinto al del Excel «' + J.nombre + '» (0).' });
    sinEmparejar.forEach(function (aj) {
      const texto = (aj.notas || []).map(textoNotaExcel_).join(' · ');
      salida.avisos.push({ curso: aj.curso, grupo: aj.unidad, alumno: aj.nombre,
        aviso: 'Alumno del Excel de Jefatura sin emparejar con Séneca',
        detalle: 'Está en el Excel (' + aj.unidad + ') pero no en la tabla ALUMNADO. Si es un alta reciente, ' +
          'se empareja en la siguiente actualización.' + (texto ? ' Texto en el Excel: «' + texto + '».' : '') });
    });
    codigosExcelAvisos_().forEach(function (a) { salida.avisos.push(a); });
  }
  return salida;
}

/*** JefaturaNotas.gs ***/
/*** ================= LOS TEXTOS AL MARGEN DEL EXCEL DE JEFATURA, A LA FICHA =================
 *
 * Instrucción 49 (docs/DEJAR-EL-EXCEL-DE-JEFATURA.md, punto 3.2). De la fila de cada alumno del Excel se lee lo escrito en la
 * columna «Observaciones» y lo escrito en las celdas SIN título a la derecha de la última columna con título. Cada texto pasa
 * a ser una nota de la ficha (`_notas`, tipo «excel», autor «Excel de Jefatura»), una sola vez: mismo alumno y mismo texto, una
 * nota, se lea el Excel las veces que se lea. No se leen colores, tachados, letra de otro color ni comentarios de celda.
 * ======================================================== ***/

const AUTOR_NOTA_EXCEL_ = 'Excel de Jefatura';
const TIPO_NOTA_EXCEL_ = 'excel';
/* Lo que el programa ya entiende como marca en una celda: no es texto para la ficha. */
const MARCAS_DE_EXCEL_ = ['REP', 'REPITE', 'REPETIDOR', 'PIL', 'DIV', 'DIVER', 'DIVERSIFICACION', 'NEAE', 'CONF', 'CONFLICTIVO', 'ALCT'];

/* ¿La celda solo lleva marcas (REP, PIL…)? Con una marca y además texto, es texto. */
function textoEsSoloMarca_(texto) {
  const trozos = String(texto || '').split(/[\s,;\/\-·+]+/).map(function (x) {
    return x.normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  }).filter(function (x) { return x; });
  if (!trozos.length) return true;
  return trozos.every(function (t) { return MARCAS_DE_EXCEL_.indexOf(t) !== -1; });
}

function textoDeCeldaExcel_(v) {
  if (v instanceof Date) {
    const d = v.getDate(), m = v.getMonth() + 1;
    return (d < 10 ? '0' : '') + d + '/' + (m < 10 ? '0' : '') + m + '/' + v.getFullYear();
  }
  return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim();
}

/* Los textos de la fila de un alumno: [{ donde: 'Observaciones' | 'Al margen', texto }]. `h` son los huecos de huecosJefatura_. */
function notasDeFilaExcel_(fila, h) {
  const salida = [];
  if (h.observ !== undefined) {
    const t = textoDeCeldaExcel_(fila[h.observ]);
    if (t && !textoEsSoloMarca_(t)) salida.push({ donde: 'Observaciones', texto: t });
  }
  for (let c = h.ultimaColumna + 1; c < fila.length; c++) {
    const t = textoDeCeldaExcel_(fila[c]);
    if (t && !textoEsSoloMarca_(t)) salida.push({ donde: 'Al margen', texto: t });
  }
  return salida;
}

function textoNotaExcel_(n) { return n.donde + ': ' + n.texto; }

/* La clave de `_notas` de un alumno de la mesa: el Nº de Id. Escolar tal cual, o la clave «nom:…» (claveNotas_, AlumnadoLigero.gs). */
function claveNotasDeClaveMesa_(claveMesa) {
  return String(claveMesa).indexOf('id:') === 0 ? String(claveMesa).substring(3) : String(claveMesa);
}

/* Pasa a `_notas` los textos de los alumnos del Excel ya emparejados con Séneca. `pares`: [{ alumnoJ, claveMesa }].
   Devuelve cuántas notas nuevas han entrado. Una sola escritura. */
function jefaturaNotasPasar_(pares) {
  const candidatas = [];
  pares.forEach(function (p) {
    (p.alumnoJ.notas || []).forEach(function (n) {
      candidatas.push({ clave: claveNotasDeClaveMesa_(p.claveMesa), texto: textoNotaExcel_(n) });
    });
  });
  if (!candidatas.length) return 0;
  const lock = LockService.getScriptLock();
  lock.waitLock(NOTAS_LOCK_ESPERA_);
  try {
    const yaEstan = {};
    notasFilas_().forEach(function (n) { if (n.tipo === TIPO_NOTA_EXCEL_) yaEstan[n.clave + '¬' + n.texto] = true; });
    const filas = [], ahora = new Date();
    candidatas.forEach(function (c) {
      const k = c.clave + '¬' + c.texto;
      if (yaEstan[k]) return;
      yaEstan[k] = true;
      filas.push([Utilities.getUuid(), c.clave, ahora, AUTOR_NOTA_EXCEL_, c.texto, '', TIPO_NOTA_EXCEL_, '', '']);
    });
    if (!filas.length) return 0;
    const h = hojaNotas_(true);
    h.getRange(h.getLastRow() + 1, 1, filas.length, NOTAS_CABECERA_.length).setValues(filas);
    return filas.length;
  } finally {
    lock.releaseLock();
  }
}

/* Cuántas notas del Excel hay ya en `_notas`, para el resumen de «Revisión». */
function jefaturaNotasContar_() {
  return notasFilas_().filter(function (n) { return n.tipo === TIPO_NOTA_EXCEL_; }).length;
}

/*** JefaturaCodigos.gs ***/
/*** ================= LOS CÓDIGOS DEL EXCEL DE JEFATURA QUE EL PROGRAMA NO SABE LEER =================
 *
 * Instrucción 49 (docs/DEJAR-EL-EXCEL-DE-JEFATURA.md, punto 3.1). En cada grado y en cada columna de materia del Excel, cada valor
 * distinto que ni la pestaña OFERTA ni las reglas fijas saben traducir a una materia es un «código sin leer». Se propone la materia
 * mirando lo que cursan en Séneca los alumnos que llevan ese código, y se guarda en la pestaña oculta `_codigos_excel` (nunca en
 * OFERTA, que es de Francisco). OFERTA manda siempre; lo que confirma una persona no lo toca el programa; un «Puesto solo» no se
 * recalcula. La traducción se usa en el mismo sitio que la de OFERTA: `lineaDeCodigoJef_` y `codigosDeJefatura_` (Matricula.gs).
 * ======================================================== ***/

/* El curso escolar cuyo reparto se lee del Excel «AGRUPAMIENTOS» (hoy y desde la instrucción 28). */
const CURSO_EXCEL_JEFATURA_ = '26-27';
const NOMBRE_MODELO_JEFATURA_ = 'Jefatura 26-27';
const HOJA_CODIGOS_EXCEL = '_codigos_excel';
const CODIGOS_EXCEL_CABECERA_ = ['Curso escolar', 'Grado', 'Columna', 'Código', 'Materia', 'Estado', 'Alumnos', 'Quién', 'Cuándo'];
const CODIGOS_EXCEL_NOTA_ = 'No toques esta pestaña. Códigos del Excel de Jefatura que la pestaña OFERTA no sabe leer, con la materia ' +
  'propuesta y su estado (instrucción 49, docs/DEJAR-EL-EXCEL-DE-JEFATURA.md). Se resuelven en la web, en Revisión.';
const CE_SOLO_ = 'Puesto solo', CE_CONFIRMADO_ = 'Confirmado', CE_DUDOSO_ = 'Dudoso', CE_SIN_ = 'Sin propuesta', CE_NO_ = 'No comparar';
const CE_MIN_ALUMNOS_ = 3, CE_MIN_PARTE_ = 0.8, CE_MAX_SEGUNDA_ = 0.5;
const CE_QUIEN_PROGRAMA_ = 'Programa';
/* El francés/ALCT no está: sale de una marca («exento de francés»), no de un código que escriba Jefatura. */
const COLUMNAS_EXCEL_ESO_ = [['rel', 'Religión'], ['opt', 'Optativa'], ['mat', 'Matemáticas A/B'], ['opc1', 'Opción 1'], ['opc2', 'Opción 2'],
  ['opc3', 'Opción 3'], ['opc4', 'Opción 4']];
const COLUMNAS_EXCEL_BAC_ = ['Modalidad obligatoria', 'Modalidad 1', 'Modalidad 2', 'Optativa 1', 'Optativa 2', 'Religión'];

let CACHE_CODIGOS_EXCEL_ = null;

/* Un código en mayúsculas y sin tildes (como codigoLimpio_, Matricula.gs; aquí aparte para que la pantalla no arrastre Matricula.gs). */
function codigoClaveExcel_(v) {
  return String(v === null || v === undefined ? '' : v)
    .normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim().toUpperCase();
}

/* Las materias que se pueden elegir en cada grado, para el desplegable de la pantalla: las abreviaturas de las líneas de la
   pestaña OFERTA que se enseñan en una columna de ALUMNADO (las comunes no). Solo lee, nunca escribe. */
function materiasDeOfertaPorGrado_() {
  const h = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('OFERTA');
  const salida = {};
  if (!h || h.getLastRow() < 3) return salida;
  h.getRange(3, 1, h.getLastRow() - 2, 7).getValues().forEach(function (f) {
    const grado = String(f[0] || '').trim(), abrev = String(f[4] || f[1] || '').trim(), columna = String(f[6] || '').trim();
    if (!grado || !abrev || !columna) return;
    const l = salida[grado] = salida[grado] || [];
    if (l.indexOf(abrev) === -1) l.push(abrev);
  });
  Object.keys(salida).forEach(function (g) { salida[g].sort(); });
  return salida;
}

/*** ---------------- La pestaña ---------------- */

function codigosExcelFilas_() {
  const h = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(HOJA_CODIGOS_EXCEL);
  if (!h || h.getLastRow() < 2) return [];
  return h.getRange(2, 1, h.getLastRow() - 1, CODIGOS_EXCEL_CABECERA_.length).getValues().map(function (f) {
    return { curso: String(f[0] || ''), grado: String(f[1] || ''), columna: String(f[2] || ''), codigo: String(f[3] || ''),
      materia: String(f[4] || ''), estado: String(f[5] || ''), alumnos: Number(f[6]) || 0, quien: String(f[7] || ''),
      cuando: f[8] instanceof Date ? f[8].toISOString() : String(f[8] || '') };
  }).filter(function (f) { return f.grado && f.codigo; });
}

function codigosExcelEscribir_(filas) {
  const libro = SpreadsheetApp.getActiveSpreadsheet();
  let h = libro.getSheetByName(HOJA_CODIGOS_EXCEL);
  if (!h) {
    h = libro.insertSheet(HOJA_CODIGOS_EXCEL);
    try { h.hideSheet(); } catch (e) { /* si no se puede ocultar, se sigue viendo y no rompe nada */ }
  }
  h.clear();
  h.getRange(1, 1, 1, CODIGOS_EXCEL_CABECERA_.length).setValues([CODIGOS_EXCEL_CABECERA_]);
  try { h.getRange(1, 1).setNote(CODIGOS_EXCEL_NOTA_); } catch (e) { /* la nota es un adorno */ }
  if (filas.length) {
    h.getRange(2, 1, filas.length, CODIGOS_EXCEL_CABECERA_.length).setValues(filas.map(function (f) {
      return [f.curso, f.grado, f.columna, f.codigo, f.materia, f.estado, f.alumnos, f.quien, f.cuando];
    }));
  }
  CACHE_CODIGOS_EXCEL_ = null;
}

/* { 'grado|CÓDIGO': { materia, estado } } de lo que ya se puede usar (Puesto solo, Confirmado) o se ha apartado (No comparar). */
function codigosExcelMapa_() {
  if (CACHE_CODIGOS_EXCEL_) return CACHE_CODIGOS_EXCEL_;
  const mapa = {};
  try {
    /* Solo vale para el curso escolar que lee el Excel: otro curso no hereda sus códigos. */
    if (cursoEscolar_() !== CURSO_EXCEL_JEFATURA_) { CACHE_CODIGOS_EXCEL_ = mapa; return mapa; }
    codigosExcelFilas_().forEach(function (f) {
      if ([CE_SOLO_, CE_CONFIRMADO_, CE_NO_].indexOf(f.estado) === -1) return;
      const k = f.grado + '|' + codigoClaveExcel_(f.codigo);
      if (!mapa[k] || f.estado !== CE_SOLO_) mapa[k] = { materia: f.estado === CE_NO_ ? '' : f.materia, estado: f.estado };
    });
  } catch (e) { /* sin la pestaña, todo como antes */ }
  CACHE_CODIGOS_EXCEL_ = mapa;
  return mapa;
}

function codigoExcelNoComparar_(grado, codigo) {
  const e = codigosExcelMapa_()[grado + '|' + codigoClaveExcel_(codigo)];
  return !!e && e.estado === CE_NO_;
}

/* La línea de la oferta de un grado a la que se refiere un código, según `_codigos_excel`. null si no hay nada usable. */
function lineaDeCodigoExcel_(lineas, codigo) {
  if (!lineas || !lineas.length) return null;
  const e = codigosExcelMapa_()[lineas[0].curso + '|' + codigoClaveExcel_(codigo)];
  if (!e || !e.materia) return null;
  const m = codigoClaveExcel_(e.materia);
  for (let i = 0; i < lineas.length; i++) if (codigoClaveExcel_(lineas[i].abrev) === m) return lineas[i];
  for (let i = 0; i < lineas.length; i++) if (codigoClaveExcel_(lineas[i].materia) === m) return lineas[i];
  return null;
}

/*** ---------------- La propuesta (sin pantalla, se prueba suelta) ---------------- */

/* Las materias que cursa un alumno en Séneca, tal como están en ALUMNADO (abreviaturas). `al`: un alumno de mesaAlumnosDeCurso_. */
function materiasSenecaDeAlumno_(al) {
  const lista = [];
  const mete = function (v, separador) {
    String(v === null || v === undefined ? '' : v).split(separador).forEach(function (x) {
      const t = x.trim();
      if (t && t !== '-' && lista.indexOf(t) === -1) lista.push(t);
    });
  };
  [al.opt, al.opc1, al.opc2, al.opc3, al.opc4, al.religion, al.mat].forEach(function (v) { mete(v, /[\/,;]/); });
  [al.matModalidad, al.bacOptativas].forEach(function (v) { mete(v, /[\s\/,;]+/); });
  return lista;
}

/* Las materias que cursa TODO el grado (no valen como propuesta). */
function materiasComunesDelGrado_(materiasDeCadaAlumno) {
  if (!materiasDeCadaAlumno.length) return [];
  return materiasDeCadaAlumno[0].filter(function (m) {
    return materiasDeCadaAlumno.every(function (l) { return l.indexOf(m) !== -1; });
  });
}

/* alumnosDelCodigo: la lista de materias de Séneca de cada alumno (ya emparejado) que lleva el código.
   comunes: lo que cursa todo el grado. usadas: lo que ya tiene otro código de esa misma columna y grado.
   Devuelve { estado: 'Puesto solo' | 'Dudoso' | 'Sin propuesta', materia, alumnos }. Regla de «clara»: 3 alumnos o más, el 80 % o más
   cursa la propuesta y la segunda candidata no llega al 50 %. Nunca se pone sola una propuesta con menos de 3 ni con dos parecidas. */
function codigosExcelProponer_(alumnosDelCodigo, comunes, usadas) {
  const n = alumnosDelCodigo.length;
  const cuenta = {};
  alumnosDelCodigo.forEach(function (lista) {
    lista.forEach(function (m) {
      if (comunes.indexOf(m) !== -1 || usadas.indexOf(m) !== -1) return;
      cuenta[m] = (cuenta[m] || 0) + 1;
    });
  });
  const candidatas = Object.keys(cuenta).sort(function (a, b) { return cuenta[b] - cuenta[a] || (a < b ? -1 : 1); });
  /* Una materia que solo cursa uno de varios alumnos no los une: no hay propuesta. */
  if (!candidatas.length || (n > 1 && cuenta[candidatas[0]] < 2)) return { estado: CE_SIN_, materia: '', alumnos: n };
  const primera = candidatas[0];
  const segunda = candidatas[1] ? cuenta[candidatas[1]] / n : 0;
  const clara = n >= CE_MIN_ALUMNOS_ && cuenta[primera] / n >= CE_MIN_PARTE_ && segunda < CE_MAX_SEGUNDA_;
  return { estado: clara ? CE_SOLO_ : CE_DUDOSO_, materia: primera, alumnos: n };
}

/*** ---------------- Qué códigos hay en cada alumno del Excel ---------------- */

/* [{ columna, codigo }] de un alumno del Excel (la forma de leerJefatura_): cada valor por la columna de la que sale. */
function codigosPorColumnaExcel_(j) {
  const salida = [];
  const mete = function (columna, v) {
    String(v === null || v === undefined ? '' : v).split('/').forEach(function (x) {
      const t = x.trim();
      if (t) salida.push({ columna: columna, codigo: codigoClaveExcel_(t) });
    });
  };
  if (j.bac && j.bac.length) {
    j.bac.forEach(function (v, i) { mete(COLUMNAS_EXCEL_BAC_[i] || ('Columna ' + (i + 1)), v); });
  } else {
    COLUMNAS_EXCEL_ESO_.forEach(function (par) { mete(par[1], j[par[0]]); });
  }
  return salida;
}

/* Los códigos sin leer de UN grado, con su propuesta. `existentes`: las filas de `_codigos_excel`.
   Devuelve { calculados: [filas], conocidos: { 'grado|columna|codigo': true } } (los que OFERTA ya sabe). */
function codigosExcelDeGrado_(grado, alumnosJ, porNombre, alumnosSeneca, existentes) {
  const lineas = ofertaDeCurso_(grado);
  const comunes = materiasComunesDelGrado_(alumnosSeneca.map(materiasSenecaDeAlumno_));
  const ocurrencias = {}, conocidos = {}, usadasOferta = {};
  alumnosJ.forEach(function (aj) {
    const al = porNombre[normalizar(aj.nombre)];
    codigosPorColumnaExcel_(aj).forEach(function (cc) {
      const k = cc.columna + '|' + cc.codigo;
      const l = lineas.length ? lineaDeCodigoOferta_(lineas, cc.codigo) : null;
      if (l) {
        conocidos[grado + '|' + k] = true;
        (usadasOferta[cc.columna] = usadasOferta[cc.columna] || []).push(l.abrev);
        return;
      }
      const o = ocurrencias[k] || (ocurrencias[k] = { columna: cc.columna, codigo: cc.codigo, alumnos: [] });
      if (al) o.alumnos.push(materiasSenecaDeAlumno_(al));
    });
  });
  /* Lo que una persona o el programa ya fijó en la misma columna cuenta como «usado»; se empieza por los códigos con más alumnos. */
  const usadasTabla = {};
  existentes.forEach(function (f) {
    if (f.grado === grado && (f.estado === CE_SOLO_ || f.estado === CE_CONFIRMADO_) && f.materia) {
      (usadasTabla[f.columna + '|' + f.codigo] = f.materia);
    }
  });
  const calculados = [];
  Object.keys(ocurrencias).sort(function (a, b) { return ocurrencias[b].alumnos.length - ocurrencias[a].alumnos.length || (a < b ? -1 : 1); })
    .forEach(function (k) {
      const o = ocurrencias[k];
      const usadas = (usadasOferta[o.columna] || []).slice();
      Object.keys(usadasTabla).forEach(function (kk) {
        if (kk.indexOf(o.columna + '|') === 0 && kk !== k) usadas.push(usadasTabla[kk]);
      });
      calculados.forEach(function (c) { if (c.columna === o.columna && c.estado === CE_SOLO_) usadas.push(c.materia); });
      const p = codigosExcelProponer_(o.alumnos, comunes, usadas);
      calculados.push({ grado: grado, columna: o.columna, codigo: o.codigo, materia: p.materia, estado: p.estado, alumnos: p.alumnos });
    });
  return { calculados: calculados, conocidos: conocidos };
}

/* Junta lo ya guardado con lo calculado ahora (puro). Reglas: lo de una persona (Confirmado, No comparar) y los «Puesto solo» no se
   tocan; Dudoso y Sin propuesta se recalculan (y pueden pasar a «Puesto solo»); lo que OFERTA ya sabe deja de salir si lo puso el
   programa; sin cambios, ni se reescribe. Devuelve { filas, cambiado }. */
function codigosExcelCombinar_(existentes, calculados, conocidos, ahoraIso) {
  const clave = function (f) { return f.grado + '|' + f.columna + '|' + f.codigo; };
  const porClave = {}, orden = [];
  existentes.forEach(function (f) { porClave[clave(f)] = f; orden.push(clave(f)); });
  let cambiado = false;
  Object.keys(conocidos).forEach(function (k) {
    const f = porClave[k];
    if (f && (f.estado === CE_SOLO_ || f.estado === CE_DUDOSO_ || f.estado === CE_SIN_)) {
      delete porClave[k]; orden.splice(orden.indexOf(k), 1); cambiado = true;
    }
  });
  calculados.forEach(function (c) {
    const k = clave(c), f = porClave[k];
    if (f && [CE_CONFIRMADO_, CE_NO_, CE_SOLO_].indexOf(f.estado) !== -1) return;
    if (f && f.estado === c.estado && f.materia === c.materia && f.alumnos === c.alumnos) return;
    const nueva = { curso: CURSO_EXCEL_JEFATURA_, grado: c.grado, columna: c.columna, codigo: c.codigo, materia: c.materia,
      estado: c.estado, alumnos: c.alumnos, quien: CE_QUIEN_PROGRAMA_, cuando: ahoraIso };
    if (!f) orden.push(k);
    porClave[k] = nueva;
    cambiado = true;
  });
  return { filas: orden.map(function (k) { return porClave[k]; }), cambiado: cambiado };
}

/* Cuántos códigos esperan a una persona (Dudoso y Sin propuesta). */
function codigosExcelSinResolver_() {
  return codigosExcelFilas_().filter(function (f) { return f.estado === CE_DUDOSO_ || f.estado === CE_SIN_; });
}

/* La línea de AVISOS para los códigos que esperan a una persona. */
function codigosExcelAvisos_() {
  const pend = codigosExcelSinResolver_();
  if (!pend.length) return [];
  return [{ curso: '', grupo: '', alumno: '', aviso: 'Códigos de Jefatura que no sé leer',
    detalle: pend.map(function (f) { return f.grado + ' · ' + f.codigo + ' (' + f.columna + ', ' + f.estado.toLowerCase() + ')'; }).join(' · ') +
      '. Se resuelven en la web, en «Revisión» › «Excel de Jefatura».' }];
}

/* Una persona fija la materia de un código (o «No comparar»). Queda «Confirmado» con su nombre; el programa ya no lo toca. */
function codigoExcelFijar_(grado, columna, codigo, materia, correo) {
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    const filas = codigosExcelFilas_();
    const k = grado + '|' + columna + '|' + codigoClaveExcel_(codigo);
    const f = filas.filter(function (x) { return x.grado + '|' + x.columna + '|' + codigoClaveExcel_(x.codigo) === k; })[0];
    if (!f) throw new Error('Ese código ya no está en la lista.');
    const noComparar = String(materia || '').trim() === CE_NO_;
    if (!noComparar && !String(materia || '').trim()) throw new Error('Elige una materia, o «No comparar».');
    f.estado = noComparar ? CE_NO_ : CE_CONFIRMADO_;
    f.materia = noComparar ? '' : String(materia).trim();
    f.quien = correo; f.cuando = new Date().toISOString();
    codigosExcelEscribir_(filas);
    return f;
  } finally {
    lock.releaseLock();
  }
}

/*** JefaturaDejar.gs ***/
/*** ================= DEJAR EL EXCEL DE JEFATURA =================
 *
 * Instrucción 49 (docs/DEJAR-EL-EXCEL-DE-JEFATURA.md, puntos 3.3 y 3.4). El botón «Dejar el Excel de Jefatura» de «Revisión» hace una
 * última lectura (con códigos y textos al margen), enseña un resumen y, con el «Sí», apaga la relectura de cada «Actualizar los datos»:
 * desde ese día manda la mesa de agrupamiento. «Volver a leer el Excel» lo deshace guardando antes una copia de cada modelo. Con el
 * Excel dejado, el alumno que llega a mitad de curso se coloca solo en el modelo definitivo con lo que diga Séneca.
 *
 * Dónde vive: pestañas ocultas del cuaderno central (que es el del curso 26-27, el único que lee el Excel):
 *   `_excel_jefatura`         Clave | Valor | Quién | Cuándo — dejado, lectura, pasada (lectura partida) y resumen.
 *   `_excel_jefatura_alumnos` los alumnos nuevos y los conocidos el día de dejarlo, para los avisos de «Revisión».
 * ======================================================== ***/

const HOJA_EXCEL_JEFATURA = '_excel_jefatura';
const EXCEL_JEFATURA_CABECERA_ = ['Clave', 'Valor', 'Quién', 'Cuándo'];
const EXCEL_JEFATURA_NOTA_ = 'No toques esta pestaña. Estado del Excel de Jefatura: si se dejó de leer, cuándo y quién (instrucción 49, ' +
  'docs/DEJAR-EL-EXCEL-DE-JEFATURA.md).';
const HOJA_EXCEL_JEFATURA_ALUMNOS = '_excel_jefatura_alumnos';
const EXCEL_ALUMNOS_CABECERA_ = ['Curso escolar', 'Grado', 'Clave', 'Alumno', 'Unidad', 'Materias', 'Origen', 'Fecha', 'En Séneca'];
const EXCEL_ALUMNOS_NOTA_ = 'No toques esta pestaña. Alumnos que han entrado solos en el reparto con el Excel dejado, y los que estaban ' +
  'cuando se dejó (instrucción 49).';
const LIMITE_LECTURA_EXCEL_MS_ = 270000;   // de los seis minutos de una llamada, lo que se dedica a leer
const AVISO_COLORES_EXCEL_ = 'Los colores, tachados y comentarios del Excel no se leen. Si alguno significa algo, apúntalo como nota en la ficha del alumno antes de dejarlo.';
/* Solo para las pruebas: { ahora, limiteMs } cambia el reloj de la lectura. */
let RELOJ_EXCEL_ = null;

/* Fecha corta, 03/10/2026 (hora de Madrid). */
function fechaCortaExcel_(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso);
  let t;
  try { t = Utilities.formatDate(d, 'Europe/Madrid', 'dd/MM/yyyy'); } catch (e) { t = ''; }
  return t || (('0' + d.getUTCDate()).slice(-2) + '/' + ('0' + (d.getUTCMonth() + 1)).slice(-2) + '/' + d.getUTCFullYear());
}

/*** ---------------- El estado ---------------- */

function excelJefaturaFilas_() {
  const h = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(HOJA_EXCEL_JEFATURA);
  if (!h || h.getLastRow() < 2) return [];
  return h.getRange(2, 1, h.getLastRow() - 1, EXCEL_JEFATURA_CABECERA_.length).getValues().map(function (f, i) {
    return { fila: i + 2, clave: String(f[0] || ''), valor: String(f[1] || ''), quien: String(f[2] || ''),
      cuando: f[3] instanceof Date ? f[3].toISOString() : String(f[3] || '') };
  }).filter(function (f) { return f.clave; });
}

function excelJefaturaLeer_(clave) {
  return excelJefaturaFilas_().filter(function (f) { return f.clave === clave; })[0] || null;
}

function excelJefaturaGuardar_(clave, valor, quien) {
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    const libro = SpreadsheetApp.getActiveSpreadsheet();
    let h = libro.getSheetByName(HOJA_EXCEL_JEFATURA);
    if (!h) {
      h = libro.insertSheet(HOJA_EXCEL_JEFATURA);
      h.getRange(1, 1, 1, EXCEL_JEFATURA_CABECERA_.length).setValues([EXCEL_JEFATURA_CABECERA_]);
      try { h.getRange(1, 1).setNote(EXCEL_JEFATURA_NOTA_); h.hideSheet(); } catch (e) { /* adorno */ }
    }
    const f = excelJefaturaLeer_(clave), ahora = new Date().toISOString();
    if (f) h.getRange(f.fila, 1, 1, 4).setValues([[clave, valor, quien, ahora]]);
    else h.appendRow([clave, valor, quien, ahora]);
  } finally {
    lock.releaseLock();
  }
}

/* { dejado, quien, cuando, lectura: { nombre, cambio, cuando } }. No escribe nunca. */
function excelJefaturaEstado_() {
  const filas = excelJefaturaFilas_();
  const d = filas.filter(function (f) { return f.clave === 'dejado'; })[0];
  const l = filas.filter(function (f) { return f.clave === 'lectura'; })[0];
  let lectura = null;
  if (l) { try { lectura = Object.assign(JSON.parse(l.valor), { cuando: l.cuando }); } catch (e) { lectura = null; } }
  return { dejado: !!d && d.valor === 'SÍ', quien: d ? d.quien : '', cuando: d ? d.cuando : '', lectura: lectura };
}

function excelJefaturaJson_(clave) {
  const f = excelJefaturaLeer_(clave);
  if (!f || !f.valor) return null;
  try { return JSON.parse(f.valor); } catch (e) { return null; }
}

/*** ---------------- Los alumnos nuevos y los conocidos ---------------- */

function excelAlumnosFilas_() {
  const h = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(HOJA_EXCEL_JEFATURA_ALUMNOS);
  if (!h || h.getLastRow() < 2) return [];
  return h.getRange(2, 1, h.getLastRow() - 1, EXCEL_ALUMNOS_CABECERA_.length).getValues().map(function (f) {
    return { grado: String(f[1] || ''), clave: String(f[2] || ''), alumno: String(f[3] || ''), unidad: String(f[4] || ''),
      materias: String(f[5] || ''), origen: String(f[6] || ''), fecha: f[7] instanceof Date ? f[7].toISOString() : String(f[7] || ''),
      enSeneca: String(f[8] || '') !== 'NO' };
  }).filter(function (f) { return f.clave; });
}

function excelAlumnosEscribir_(filas) {
  const libro = SpreadsheetApp.getActiveSpreadsheet();
  let h = libro.getSheetByName(HOJA_EXCEL_JEFATURA_ALUMNOS);
  if (!h) {
    h = libro.insertSheet(HOJA_EXCEL_JEFATURA_ALUMNOS);
    try { h.hideSheet(); } catch (e) { /* adorno */ }
  }
  h.clear();
  h.getRange(1, 1, 1, EXCEL_ALUMNOS_CABECERA_.length).setValues([EXCEL_ALUMNOS_CABECERA_]);
  try { h.getRange(1, 1).setNote(EXCEL_ALUMNOS_NOTA_); } catch (e) { /* adorno */ }
  if (filas.length) {
    h.getRange(2, 1, filas.length, EXCEL_ALUMNOS_CABECERA_.length).setValues(filas.map(function (f) {
      return [CURSO_EXCEL_JEFATURA_, f.grado, f.clave, f.alumno, f.unidad, f.materias, f.origen, f.fecha, f.enSeneca ? 'SÍ' : 'NO'];
    }));
  }
}

/* Con el Excel dejado, en cada actualización: el alumno de Séneca que no está en el modelo definitivo de su grado entra en él con el
   grupo y las materias de Séneca (el modelo sube de versión solo si entra alguien), y se apunta como «Nuevo». Los registrados que ya no
   están en Séneca se marcan; no se quitan del modelo. Solo en los grados con modelo definitivo. */
function jefaturaAlumnosNuevos_() {
  const ahora = new Date().toISOString();
  const registro = excelAlumnosFilas_();
  const nuevos = [];
  let cambiado = false;
  GRADOS_MESA_.forEach(function (grado) {
    const def = mesaListarModelosCompletos_(grado).filter(function (m) { return m.definitivo; })[0];
    if (!def) return;
    const alumnos = mesaAlumnosDeCurso_(grado);
    if (!alumnos.length) return;
    const enSeneca = {};
    alumnos.forEach(function (al) { enSeneca[al.clave] = true; });
    /* Los que ya no están en Séneca, o han vuelto. */
    registro.forEach(function (r) {
      if (r.grado !== grado) return;
      if (r.enSeneca !== !!enSeneca[r.clave]) { r.enSeneca = !!enSeneca[r.clave]; cambiado = true; }
    });
    const faltan = alumnos.filter(function (al) { return !def.asignaciones[al.clave]; });
    if (!faltan.length) return;
    const desdeSeneca = mesaAsignacionesDeSeneca_(faltan);
    const asignaciones = Object.assign({}, def.asignaciones);
    faltan.forEach(function (al) { asignaciones[al.clave] = desdeSeneca[al.clave]; });
    const r = mesaGuardarModeloAlmacen_(def.id, { asignaciones: asignaciones, reglas: def.reglas, criterios: def.criterios, definitivo: true },
      def.version, 'Séneca (alumno nuevo)');
    if (!r.ok) return;   // alguien guardó en la mesa a la vez: se reintenta en la siguiente actualización
    faltan.forEach(function (al) {
      const fila = { grado: grado, clave: al.clave, alumno: al.nombre, unidad: al.grupo, enSeneca: true, origen: 'Nuevo', fecha: ahora,
        materias: materiasSenecaDeAlumno_(al).join(', ') };
      registro.push(fila); nuevos.push(fila); cambiado = true;
    });
  });
  if (cambiado) excelAlumnosEscribir_(registro);
  const salida = { nuevos: nuevos, aviso: null };
  if (nuevos.length) {
    const nombres = nuevos.map(function (n) { return n.alumno; }).join(', ');
    salida.aviso = { curso: '', grupo: '', alumno: '', aviso: 'Alumnos nuevos colocados con lo que dice Séneca',
      detalle: nuevos.length + ' alumnos nuevos colocados con lo que dice Séneca: ' + nombres + '.' };
    /* AVISOS ya está escrito cuando esto corre (después de rehacer ALUMNADO): se añade la línea. */
    try {
      avisosAnadirFilas_(libroActivo_(), [[salida.aviso.curso, salida.aviso.grupo, salida.aviso.alumno, salida.aviso.aviso, salida.aviso.detalle, '', '']]);   // instrucción 117: la única puerta
    } catch (e) { /* el aviso es un extra: el alumno ya está colocado */ }
  }
  return salida;
}

/*** ---------------- El botón: leer, resumen, dejar, volver ---------------- */

function excelJefaturaComprobarCurso_(curso) {
  if ((curso || cursoEscolar_()) !== CURSO_EXCEL_JEFATURA_) throw new Error('El Excel de Jefatura solo se lee en el curso ' + CURSO_EXCEL_JEFATURA_ + '.');
}

function excelJefaturaResumenDe_(grados, sinEmparejar, notasNuevas, s) {
  const filas = codigosExcelFilas_();
  const porResolver = filas.filter(function (f) { return f.estado === CE_DUDOSO_ || f.estado === CE_SIN_; }).length;
  return {
    ok: true, completa: true, faltan: [], nombreExcel: s.nombreExcel, cambioExcel: s.cambioExcel, grados: grados,
    totalAlumnos: Object.keys(grados).reduce(function (t, g) { return t + grados[g]; }, 0),
    sinEmparejar: sinEmparejar, notasNuevas: notasNuevas, textosEnNotas: jefaturaNotasContar_(),
    codigosPuestosSolos: filas.filter(function (f) { return f.estado === CE_SOLO_; }).length, codigosPorResolver: porResolver,
    puedeDejar: porResolver === 0, aviso: AVISO_COLORES_EXCEL_
  };
}

/* Lee el Excel ahora (la misma lectura de siempre, con códigos y textos). Si no cabe en el tiempo, guarda lo hecho y dice qué grados faltan. */
function excelJefaturaLeerAhora_(opciones) {
  opciones = opciones || RELOJ_EXCEL_ || {};
  if (excelJefaturaEstado_().dejado) throw new Error('El Excel ya está dejado.');
  CACHE_EXCEL_SINCRONIZAR_ = null;
  const pasada = excelJefaturaJson_('pasada') || { hechos: [], grados: {}, sinEmparejar: [], notasNuevas: 0 };
  const s = jefaturaSincronizarExcel_(true, { ahora: opciones.ahora, inicio: (opciones.ahora || Date.now)(),
    limiteMs: opciones.limiteMs === undefined ? LIMITE_LECTURA_EXCEL_MS_ : opciones.limiteMs, excluirGrados: pasada.hechos });
  if (!s.leido) {
    const motivo = s.avisos.length ? s.avisos[0].detalle : 'No he encontrado el Excel de Jefatura (un cuaderno cuyo nombre lleve «AGRUPAMIENTOS») o no trae ningún alumno.';
    return { ok: false, motivo: motivo };
  }
  pasada.hechos = pasada.hechos.concat(s.hechos);
  Object.keys(s.grados).forEach(function (g) { pasada.grados[g] = s.grados[g]; });
  pasada.sinEmparejar = pasada.sinEmparejar.concat(s.sinEmparejar);
  pasada.notasNuevas += s.notasNuevas;
  if (s.faltan.length) {
    excelJefaturaGuardar_('pasada', JSON.stringify(pasada), '');
    return { ok: true, completa: false, faltan: s.faltan, leidos: pasada.hechos,
      aviso: 'Se ha leído ' + pasada.hechos.join(', ') + '. No ha dado tiempo con ' + s.faltan.join(', ') + ': pulsa otra vez.' };
  }
  excelJefaturaGuardar_('pasada', '', '');
  const resumen = excelJefaturaResumenDe_(pasada.grados, pasada.sinEmparejar, pasada.notasNuevas, s);
  excelJefaturaGuardar_('resumen', JSON.stringify({ completa: true, puedeDejar: resumen.puedeDejar }), '');
  return resumen;
}

function webExcelJefaturaLeer(curso, correo) {
  excelJefaturaComprobarCurso_(curso);
  return excelJefaturaLeerAhora_();
}

/* El «Sí, dejar el Excel»: solo con el resumen leído y ningún código por resolver. */
function webExcelJefaturaDejar(curso, correo) {
  excelJefaturaComprobarCurso_(curso);
  if (excelJefaturaEstado_().dejado) throw new Error('El Excel ya está dejado.');
  const r = excelJefaturaJson_('resumen');
  if (!r || !r.completa) throw new Error('Antes lee el Excel con el botón «Dejar el Excel de Jefatura» y repasa el resumen.');
  const pendientes = codigosExcelSinResolver_().length;
  if (pendientes) throw new Error('Antes resuelve los ' + pendientes + ' códigos de la lista.');
  /* Quién estaba en cada modelo definitivo el día de dejarlo, para poder avisar de quien deje de estar en Séneca. */
  const ahora = new Date().toISOString();
  const filas = excelAlumnosFilas_().filter(function (f) { return f.origen === 'Nuevo'; });
  GRADOS_MESA_.forEach(function (grado) {
    const def = mesaListarModelosCompletos_(grado).filter(function (m) { return m.definitivo; })[0];
    if (!def) return;
    mesaAlumnosDeCurso_(grado).forEach(function (al) {
      const a = def.asignaciones[al.clave];
      if (!a || filas.some(function (f) { return f.clave === al.clave; })) return;
      filas.push({ grado: grado, clave: al.clave, alumno: al.nombre, unidad: a.grupo || al.grupo, materias: '', origen: 'Conocido', fecha: ahora, enSeneca: true });
    });
  });
  excelAlumnosEscribir_(filas);
  excelJefaturaGuardar_('dejado', 'SÍ', correo);
  excelJefaturaGuardar_('resumen', '', '');
  return excelJefaturaEstado_();
}

/* «Volver a leer el Excel»: una copia de cada modelo «Jefatura 26-27» (no definitiva) y el Excel vuelve a mandar. */
function webExcelJefaturaVolver(curso, correo) {
  excelJefaturaComprobarCurso_(curso);
  if (!excelJefaturaEstado_().dejado) throw new Error('El Excel no está dejado.');
  const hoy = fechaCortaExcel_(new Date().toISOString());
  const copias = [];
  GRADOS_MESA_.forEach(function (grado) {
    const modelos = mesaListarModelosCompletos_(grado);
    const propio = modelos.filter(function (m) { return m.nombre === NOMBRE_MODELO_JEFATURA_; })[0];
    if (!propio) return;
    let nombre = NOMBRE_MODELO_JEFATURA_ + ' (copia del ' + hoy + ')', n = 1;
    while (modelos.some(function (m) { return m.nombre === nombre; })) nombre = NOMBRE_MODELO_JEFATURA_ + ' (copia del ' + hoy + ', ' + (++n) + ')';
    mesaCrearModeloAlmacen_(grado, nombre, { asignaciones: propio.asignaciones, reglas: propio.reglas, criterios: propio.criterios, definitivo: false }, correo);
    copias.push(grado);
  });
  excelJefaturaGuardar_('dejado', '', correo);
  excelJefaturaGuardar_('resumen', '', '');
  return { ok: true, copias: copias };
}

/* Una persona fija la materia de un código (o «No comparar»). */
function webExcelJefaturaFijar(curso, grado, columna, codigo, materia, correo) {
  excelJefaturaComprobarCurso_(curso);
  return codigoExcelFijar_(grado, columna, codigo, materia, correo);
}

/*** ---------------- Lo que enseña «Revisión» (solo lee) ---------------- */

const ORDEN_ESTADO_CODIGO_ = {};
ORDEN_ESTADO_CODIGO_[CE_DUDOSO_] = 0; ORDEN_ESTADO_CODIGO_[CE_SIN_] = 0; ORDEN_ESTADO_CODIGO_[CE_SOLO_] = 1;

function webExcelJefatura(curso, correo) {
  curso = cursoOEnMarcha_(curso);
  if (curso !== CURSO_EXCEL_JEFATURA_) return { mostrar: false };
  const e = excelJefaturaEstado_();
  const codigos = codigosExcelFilas_().sort(function (a, b) {
    const ra = ORDEN_ESTADO_CODIGO_[a.estado] === undefined ? 2 : ORDEN_ESTADO_CODIGO_[a.estado];
    const rb = ORDEN_ESTADO_CODIGO_[b.estado] === undefined ? 2 : ORDEN_ESTADO_CODIGO_[b.estado];
    const ka = a.grado + '|' + a.columna + '|' + a.codigo, kb = b.grado + '|' + b.columna + '|' + b.codigo;
    return ra - rb || (ka < kb ? -1 : (ka > kb ? 1 : 0));
  });
  const revisados = revisadosMapa_(libroDelCurso_(curso));
  const conRevisado = function (tipo, f) {
    const clave = tipo + '|' + f.grado + '|' + f.clave;
    return { clave: clave, grado: f.grado, alumno: f.alumno, unidad: f.unidad, materias: f.materias, fecha: f.fecha,
      revisado: revisados['excel|' + clave] || null };
  };
  const registro = excelAlumnosFilas_();
  return {
    mostrar: true, curso: curso, dejado: e.dejado, quien: e.quien, cuando: e.cuando, lectura: e.lectura,
    codigos: codigos, materias: materiasDeOfertaPorGrado_(), notasPasadas: jefaturaNotasContar_(),
    sinResolver: codigos.filter(function (f) { return f.estado === CE_DUDOSO_ || f.estado === CE_SIN_; }).length,
    nuevos: registro.filter(function (f) { return f.origen === 'Nuevo'; }).map(function (f) { return conRevisado('nuevo', f); }),
    bajas: registro.filter(function (f) { return !f.enSeneca; }).map(function (f) { return conRevisado('baja', f); }),
    avisoColores: AVISO_COLORES_EXCEL_, pasadaPendiente: !!excelJefaturaJson_('pasada')
  };
}

/*** Matricula.gs ***/
/*** ================= LA MATRÍCULA, COMPROBADA DE UNA SOLA VEZ =================
 *
 * POR QUÉ EXISTE ESTE FICHERO (BD v62, 10-sep-2026). Lo pidió Francisco:
 *
 *   "Necesito saber si las asignaturas registradas en Séneca de un alumno son
 *    las que tienen que ser, que no sobre ni falte una asignatura no elegible,
 *    y que las elegibles sean las que ha puesto Jefatura de Estudios en su
 *    archivo Agrupamiento. Si no cuadran debes decirme de una manera muy
 *    clara, estructurada y fiable, cuáles son las que están dando la
 *    discrepancia."
 *
 * Hasta la BD v61 esto lo hacían TRES comprobaciones distintas, en tres
 * ficheros, con tres listas de materias escritas a mano que ya no coincidían,
 * y que escribían el mismo fallo en tres sitios con tres frases distintas.
 * Aquí se sustituyen por UNA cuenta por alumno:
 *
 *     Lo que debe tener  =  las obligatorias de su curso (según la oferta del
 *                           centro) + lo que Jefatura ha escrito para él
 *     Lo que tiene       =  lo que está en Séneca (MATR, CONV y APRO)
 *
 *     FALTAN  =  lo que debe tener y no está en Séneca
 *     SOBRAN  =  lo que está en Séneca y no debe tener
 *
 * Donde Jefatura no dice nada de un cuadro de elección, el cuadro se comprueba
 * CONTANDO: el alumno tiene que tener exactamente las que diga el cuadro. Una
 * materia que no está en la oferta de su curso sobra siempre.
 *
 * Es la misma cuenta para la ESO y para Bachillerato. La diversificación, la
 * modalidad y el itinerario solo dicen QUÉ PARTE de la oferta le toca a cada
 * alumno.
 *
 * QUIEN REPITE 2º DE BACHILLERATO (BD v63) tiene materias APRO: las aprobó el
 * año pasado y no las vuelve a cursar. Lo aprobado nunca falta ni sobra, y de
 * los cuadros de elección solo se le exige lo que escribe Jefatura; los
 * cuadros no se cuentan. Lo pidió Francisco el 10-sep-2026 con el caso de un
 * repetidor al que le salían como "sobran" tres materias ya aprobadas.
 *
 * LA ÚNICA LISTA DE MATERIAS: LA PESTAÑA "OFERTA". Una línea por materia y
 * curso, con todo lo que el programa necesita saber de ella:
 *
 *   Curso                     1º, 2º, 3º, 4º, 1º BACH, 2º BACH
 *   Materia                   el nombre EXACTO que le da Séneca en el CSV
 *   Quién la cursa            Todo el alumnado · Todos menos diversificación ·
 *                             Solo diversificación · Solo Ciencias y Tecnología ·
 *                             Solo Humanidades y CC. Sociales ·
 *                             Solo quienes cursan <materia>
 *   Cuadro de elección        vacío = obligatoria. Con texto, las líneas que
 *                             comparten ese texto son un cuadro del que se
 *                             elige UNA, o las que diga "(elegir 2)"
 *   Abreviatura               cómo se escribe en ALUMNADO y en el papel
 *   Código de Jefatura        cómo la escribe Jefatura en AGRUPAMIENTOS.
 *                             Varios, separados por comas. Vacío = la abreviatura
 *   Columna en ALUMNADO       dónde se enseña: OPT, MAT, OPC1..OPC4, REL/Atedu,
 *                             FR -> ALCT, MAT. MODALIDAD, OPTATIVAS. Vacío = no
 *                             se enseña (las comunes)
 *   Notas                     lo que se quiera anotar
 *
 * El programa la escribe UNA VEZ, a partir de la oferta que está más abajo en
 * este fichero, y desde entonces SOLO LA LEE. Cuando el centro cambie la
 * oferta, se cambia en la pestaña, sin tocar código. Si se borra la pestaña,
 * se vuelve a escribir desde aquí.
 *
 * DÓNDE SE VE EL RESULTADO:
 *   - La pestaña MATRÍCULA: una fila por alumno que no cuadra, con dos
 *     columnas que se leen como una orden de trabajo, "FALTAN en Séneca" y
 *     "SOBRAN en Séneca", cada materia con su porqué entre paréntesis.
 *   - La columna MATRÍCULA de ALUMNADO, para todos los cursos: OK, o un
 *     resumen corto de lo que falta y sobra.
 *   - El panel RESUMEN y la portada del PDF cuentan las que quedan.
 *
 * ======================================================================== ***/

/*** ================= INSTRUCCIÓN 110: DÓNDE VIVE CADA COSA =================
 *
 * Este fichero se partió (docs/NAVEGADOR-5-MATRICULA-AL-MOMENTO.md) para que ninguno pase de 400 líneas y para que la cuenta salga a ficheros de regla que cargan también la página:
 *   MatriculaReglas.gs   REGLA COMÚN (servidor y página): las constantes de la cuenta, "Quién la cursa", qué columna del CSV es cada materia, qué le toca a cada alumno y los códigos de Jefatura.
 *   MatriculaCuenta.gs   REGLA COMÚN: LA CUENTA de un alumno (`reglaCuentaDeMatricula_`) y el armado de su entrada desde las capas (`matriculaEntradaDe_`).
 *   MatriculaOferta.gs   la pestaña OFERTA: leerla y escribirla (`leerOferta_`, `ofertaDeCurso_`, `escribirOferta_`).
 *   MatriculaSemilla.gs  la oferta de partida, con la que se escribe la pestaña la primera vez.
 *   MatriculaComprobar.gs  qué es cada columna de un CSV y la cuenta de todo el centro (`comprobarMatriculas_`).
 *   MatriculaEscribir.gs   la pestaña MATRÍCULA, la base para recalcular en la página y las cuentas de la portada.
 * Aquí quedan las constantes que solo usa el servidor.
 *
 * ======================================================================== ***/

/* Valor de Séneca para una materia convalidada. Cuenta como matriculada. */
const OBL_CONVALIDADA = 'CONV';

/* ¿Esta casilla del CSV dice que el alumno tiene la materia? MATR es
   matriculado, CONV convalidada y APRO (solo en 2º de Bachillerato) ya
   aprobada de cuando repitió: las tres cuentan como "la tiene". */
function celdaMatriculada_(v) {
  const t = String(v === null || v === undefined ? '' : v).trim().toUpperCase();
  return t === MARCA || t === OBL_CONVALIDADA || t === MARCA_APROBADA;
}


/*** ================= LAS REGLAS, CON LO QUE SOLO SABE EL SERVIDOR (INSTRUCCIÓN 110) =================
 * Las reglas de MatriculaReglas.gs y MatriculaCuenta.gs reciben la oferta, los códigos del Excel y `abreviar` como argumentos. Aquí están las funciones de siempre (con los mismos nombres y argumentos que antes
 * de partir el fichero), que se los dan leyendo la pestaña OFERTA y `_codigos_excel`. */

/* Lo que las reglas no pueden saber solas: cómo se abrevia una materia y los códigos del Excel de Jefatura. */
function matriculaCtx_() {
  return { abreviar: abreviar, codigosExcel: codigosExcelMapa_() };
}

function cuentaDeMatricula_(a, j, hayJef) {
  return reglaCuentaDeMatricula_(a, j, hayJef, ofertaDeCurso_(a.curso), matriculaCtx_());
}

function asignaturasQueLeTocan_(a) {
  return reglaAsignaturasQueLeTocan_(a, ofertaDeCurso_(a.curso));
}

function lineaDeCodigoJef_(lineas, codigo) {
  return reglaLineaDeCodigoJef_(lineas, codigo, matriculaCtx_());
}

function codigosDeJefatura_(j) {
  return reglaCodigosDeJefatura_(j, matriculaCtx_());
}

