      const cifras = { leida: !!(d.planificacion && d.planificacion.leida), avisos: ((d.planificacion && d.planificacion.avisos) || []).length,
        incompletos: (d.esperados || []).filter(function (e) { return e.incompleto; }).length };
      Object.keys(ficheros).forEach(function (n) { cifras['ficheros-' + n] = Object.keys(ficheros[n]).length; });
