      const lista = function (h) { return h.filas.map(function (f) { return { nombre: cmpCol_(f, 'Alumno/a'), curso: cmpCol_(f, 'Curso') }; }); };
      const e = emparejarConJefatura_(lista(a), lista(j));
      const sin = lista(a).filter(function (x) { return !e.jefPorSeneca[normalizar(x.nombre) + '|' + x.curso]; }).length;
      return cmpDato_({ porParecido: e.parecidos.length, sinFilaDeJefatura: sin });
