        const minutos = Math.max(0, Math.round((Date.now() - new Date(indice.hora).getTime()) / 60000));
        let atraso = 0;
        conLecturaUnica_(function () {
          (indice.cursos || []).forEach(function (c) {
            const l = buscadorLigeroGuardado_(c.curso);
            if (!l || !l.hora) return;
            atraso = Math.max(atraso, Math.round((new Date(l.hora).getTime() - new Date(c.hora).getTime()) / 60000));
          });
        });
        const cifras = { minutosIndice: minutos, atrasoMin: Math.max(0, atraso), cursos: (indice.cursos || []).length };
        return atraso > CMP_LISTADOW_ATRASO_MIN_ ? cmpMal_(cifras) : cmpBien_(cifras);
