/*** ComprobacionesHoyWeb.gs ***/
/*** ================= COMPROBACIONES: «HOY» DE LA WEB NUEVA (INSTRUCCIÓN 138, PARTE 2) =================
 *
 * docs/WEB-NUEVA-3-CONSULTAR.md, punto 4. Solo cifras, nunca el nombre de un alumno (regla del diagnóstico, instrucción 119).
 *   · web-nueva-hoy-igual   los ficheros de «Hoy» de la web nueva (HoyWeb.gs) dan, curso a curso, lo mismo que las partes guardadas que lee la portada de hoy (una vez reducidas a lo que «Hoy» usa), y la lista de cursos
 *                           abiertos del índice es la de ahora. Dice cuántas lecturas difieren. La cola de documentos en marcha (`generacion`) y la línea de estado de la actualización (`portada`) cambian solas y no se comparan.
 *                           Un curso cuyas partes son más nuevas que su fichero no se compara: cuenta como `esperan`.
 *   · web-nueva-hoy-al-dia  los ficheros existen y no van más de tres horas por detrás de los datos guardados.
 *   · web-nueva-hoy-calendario  (instrucción 149) el índice lleva el calendario de cada curso: el menú de la web nueva lo usa para resaltar las tareas de esta época sin cargar los datos de «Inicio».
 *
 * ======================================================== ***/

const CMP_HOYW_ATRASO_MIN_ = 180;
const CMP_HOYW_NO_SE_COMPARA_ = { portada: 1 };

/* Lo comparable de las lecturas de un curso: sin `portada` y sin `generacion` de documentos. */
function cmpHoyWebComparable_(lecturas) {
  const c = {};
  Object.keys(lecturas || {}).forEach(function (k) {
    if (CMP_HOYW_NO_SE_COMPARA_[k]) return;
    if (k === 'doc' && lecturas.doc) { c.doc = Object.assign({}, lecturas.doc); delete c.doc.generacion; return; }
    c[k] = lecturas[k];
  });
  return c;
}

function cmpHoyWeb_() {
  return [
    cmpD_('web-nueva-hoy-igual', 138, 'Que «Hoy» de la web nueva da, curso a curso, lo mismo que las partes guardadas que usa «Hoy» de hoy.', ['HoyWeb.gs', 'hoyWebEscribir_'],
      function () {
        const indice = hoyWebIndiceLeer_(null);
        if (!indice) return cmpSinDatos_();
        const carpeta = buscadorCarpeta_();
        let lecturas = 0, difieren = 0, sinFichero = 0, esperan = 0, cursos = 0;
        conLecturaUnica_(function () {
          const ahora = JSON.stringify((cursosParaSelector_().abiertos) || []);
          if (JSON.stringify(indice.abiertos || []) !== ahora) difieren++;
          (indice.cursos || []).forEach(function (c) {
            const debe = hoyWebLecturasDeCurso_(c.curso);
            if (!debe || (debe.hora && c.hora && debe.hora > c.hora)) { esperan++; return; }
            const f = hoyWebLeerFichero_(carpeta, c.fichero);
            if (!f) { sinFichero++; return; }
            cursos++;
            const a = cmpHoyWebComparable_(debe.lecturas), b = cmpHoyWebComparable_(f.lecturas);
            Object.keys(a).forEach(function (k) { lecturas++; if (JSON.stringify(a[k]) !== JSON.stringify(b[k])) difieren++; });
            Object.keys(b).forEach(function (k) { if (!(k in a)) difieren++; });
          });
        });
        if (!lecturas && !sinFichero) return cmpSinDatos_({ esperan: esperan });
        return cmpCuenta_(difieren + sinFichero, { cursos: cursos, lecturas: lecturas, difieren: difieren, sinFichero: sinFichero, esperan: esperan });
      }),
    cmpD_('web-nueva-hoy-al-dia', 138, 'Que los ficheros de «Hoy» de la web nueva están hechos y no van más de tres horas por detrás de los datos guardados.', ['HoyWeb.gs', 'hoyWebEscribir_'],
      function () {
        const indice = hoyWebIndiceLeer_(null);
        if (!indice) return cmpSinDatos_();
        const minutos = Math.max(0, Math.round((Date.now() - new Date(indice.hora).getTime()) / 60000));
        let atraso = 0;
        conLecturaUnica_(function () {
          (indice.cursos || []).forEach(function (c) {
            const d = hoyWebLecturasDeCurso_(c.curso);
            if (!d || !d.hora || !c.hora) return;
            atraso = Math.max(atraso, Math.round((new Date(d.hora).getTime() - new Date(c.hora).getTime()) / 60000));
          });
        });
        const cifras = { minutosIndice: minutos, atrasoMin: Math.max(0, atraso), cursos: (indice.cursos || []).length };
        return atraso > CMP_HOYW_ATRASO_MIN_ ? cmpMal_(cifras) : cmpBien_(cifras);
      }),
    cmpD_('web-nueva-hoy-calendario', 149, 'Que el índice de «Inicio» de la web nueva lleva el calendario de cada curso: el menú de arriba lo usa para resaltar las tareas de esta época.', ['HoyWeb.gs', 'hoyWebEscribir_'],
      function () {
        const indice = hoyWebIndiceLeer_(null);
        if (!indice) return cmpSinDatos_();
        const cursos = indice.cursos || [];
        const sin = cursos.filter(function (c) { return !c.calendario || !Array.isArray(c.calendario.filas); }).length;
        const estado = hoyWebFilasDeCalendario_(indice);
        const cifras = { cursos: cursos.length, sinCalendario: sin, filas: estado };
        return cursos.length && !sin ? cmpBien_(cifras) : (cursos.length ? cmpMal_(cifras) : cmpSinDatos_());
      })
  ];
}

/* Cuántas filas de fechas lleva el índice en total (solo una cifra). */
function hoyWebFilasDeCalendario_(indice) {
  let n = 0;
  (indice.cursos || []).forEach(function (c) { n += ((c.calendario && c.calendario.filas) || []).length; });
  return n;
}

