/*** ================= COMPROBACIONES: «ESTADÍSTICAS» DE LA WEB NUEVA (INSTRUCCIÓN 138, PARTE 4) =================
 *
 * docs/WEB-NUEVA-3-CONSULTAR.md, punto 4. Solo cifras, nunca el nombre de un alumno (regla del diagnóstico, instrucción 119).
 *   · web-nueva-estadisticas-igual   el fichero del curso en marcha (EstadisticasWeb.gs) lleva, alumno a alumno y dato a dato, lo mismo que devuelve hoy la función de la pantalla de Estadísticas de la app de hoy.
 *                                    Dice cuántos alumnos y cuántos valores difieren. Si los datos del curso han cambiado desde que se hizo el fichero, no se compara: cuenta como `esperan`.
 *   · web-nueva-estadisticas-al-dia  el disparador ha hecho su vuelta en las últimas tres horas y el fichero del curso en marcha existe. Dice cuántos datos esperan a ser rehechos.
 *
 * ======================================================== ***/

const CMP_ESTW_ATRASO_MIN_ = 180;

function cmpEstadisticasWeb_() {
  return [
    cmpD_('web-nueva-estadisticas-igual', 138, 'Que «Estadísticas» de la web nueva da, alumno a alumno, lo mismo que la pantalla de Estadísticas de hoy.', ['EstadisticasWeb.gs', 'estadisticasWebEscribir_'],
      function () {
        const indice = estadisticasWebIndiceLeer_(null);
        if (!indice || !indice.enMarcha) return cmpSinDatos_();
        const clave = 'datos|' + indice.enMarcha, entrada = (indice.ficheros || {})[clave];
        if (!entrada) return cmpCuenta_(1, { sinFichero: 1 });
        const estado = estadisticasWebEstadoLeer_()[clave];
        if (!estado || estado.s !== estadisticasWebSello_(clave, false)) return cmpSinDatos_({ esperan: 1 });
        const f = estadisticasWebLeerFichero_(buscadorCarpeta_(), entrada.fichero);
        if (!f || !f.valor) return cmpCuenta_(1, { sinFichero: 1 });
        const hoy = webEstadisticasCurso(indice.enMarcha), a = f.valor;
        let difieren = 0, valores = 0;
        if (JSON.stringify(a.catalogo) !== JSON.stringify(hoy.catalogo)) difieren++;
        if (a.alumnos.length !== hoy.alumnos.length) difieren++;
        hoy.alumnos.forEach(function (x, i) {
          const y = a.alumnos[i];
          if (!y) return;
          valores += x.v.length;
          if (x.k !== y.k || x.n !== y.n || x.u !== y.u || JSON.stringify(x.v) !== JSON.stringify(y.v)) difieren++;
        });
        return cmpCuenta_(difieren, { alumnos: hoy.alumnos.length, valores: valores, difieren: difieren });
      }),
    cmpD_('web-nueva-estadisticas-al-dia', 138, 'Que los ficheros de «Estadísticas» de la web nueva están hechos y el disparador los repasa al menos cada tres horas.', ['EstadisticasWeb.gs', 'estadisticasWebEscribir_'],
      function () {
        const indice = estadisticasWebIndiceLeer_(null);
        if (!indice) return cmpSinDatos_();
        const estado = estadisticasWebEstadoLeer_();
        const minutos = estado.vuelta ? Math.max(0, Math.round((Date.now() - new Date(estado.vuelta).getTime()) / 60000)) : 0;
        const claves = Object.keys(indice.ficheros || {});
        let esperan = 0;
        claves.forEach(function (c) {
          const e = estado[c];
          if (!e || e.s !== estadisticasWebSello_(c, e.s.indexOf('cerrado|') === 0)) esperan++;
        });
        const cifras = { ficheros: claves.length, esperan: esperan, minutosDesdeLaVuelta: minutos };
        return !(indice.ficheros || {})['datos|' + indice.enMarcha] || minutos > CMP_ESTW_ATRASO_MIN_ ? cmpMal_(cifras) : cmpBien_(cifras);
      })
  ];
}

