/*** ================= INSTRUCCIÓN 16: QUIÉN VIENE ================= ***/

/* Todo lo de la pestaña "Quién viene" de golpe (regla 1.1): esperados,
   matrícula de julio, panel de avance y solicitudes de admisión con su lista
   de espera. En un curso EN MARCHA (proceso extraordinario, punto 3.3) solo
   tiene sentido la parte de solicitudes: esperados/panel se dejan vacíos. */
function webQuienViene(curso) {
  curso = cursoOEnMarcha_(curso);
  return conTiempoMedido_(curso, 'abrir quien viene', 0, function () {
    const info = cursoPorNombre_(curso);
    const esPreparacion = !!info && info.estado === CURSO_EN_PREPARACION;

    let solicitudes = [];
    try { solicitudes = solicitudesAdmision_(curso); } catch (e) { solicitudes = []; }

    /* Instrucción 38: cada solicitante de la lista de espera lleva su gestión (teléfono, pasos,
       llamadas y estado); si la lista está vacía, no se lee nada más (EsperaGestion.gs). */
    /* Instrucción 42 (ResolucionCruce.gs): con la resolución de mayo leída, manda ella (tabla de 4.5); sin ella, todo como antes. */
    let resolucion = { hay: false }, avisoResolucion = [];
    try { resolucion = resolucionAplicar_(curso, solicitudes); } catch (err) {
      avisoResolucion = [{ alumno: '', grado: '', aviso: 'No he podido aplicar la resolución de admisión: ' + err.message }];
    }
    const espera = listaEsperaConGestion_(curso, resolucion.hay ? resolucion.listaEspera : listaEsperaAdmision_(solicitudes));
    const salida = {
      curso: curso, esPreparacion: esPreparacion,
      solicitudes: resolucion.hay ? resolucion.solicitudes : solicitudes,
      resolucion: resolucion.hay ? { leida: true, cuadre: resolucion.cuadre, fecha: resolucion.leida ? resolucion.leida.cuando : '',
        sinEmparejar: resolucion.sinEmparejar } : { leida: false },
      listaEspera: espera.lista,
      avisosAdmision: avisosAdmisionDesconocidos_(solicitudes).concat(espera.avisos, avisoResolucion),
      esperados: [], noEsperados: [], panel: []
    };
    if (esPreparacion) {
      const r = matriculaJulioEstado_(curso);
      /* Instrucción 41 (PlanificacionSobres.gs): qué le falta en el sobre a cada esperado (`incompleto`). Antes que los
         contactos: también los tendrán los «Sobre incompleto» que no son Pendiente. */
      /* Nunca se ha visto un fichero real de planificación: si algo no encaja, «Quién viene» sigue funcionando y lo dice. */
      let plan = { leida: false, niveles: {}, avisos: [], sinEmparejar: [] };
      try { plan = planificacionAplicar_(curso, r.esperados); } catch (err) {
        plan.avisos = ['No he podido leer la planificación de matrícula: ' + err.message];
      }
      contactosParaPendientes_(curso, r.esperados);   // instrucción 39: teléfonos y contactos de los «Pendiente»
      /* Instrucción 40 (Sobres.gs): cómo está el sobre de matrícula de cada «Pendiente», las tres cifras del panel y los
         sobres sin emparejar. Una sola lectura de `_sobres`. */
      const sobres = sobresAplicar_(curso, r.esperados);
      salida.esperados = r.esperados;
      salida.noEsperados = r.noEsperados;
      salida.panel = sobresCifrasPanel_(panelAvanceMatricula_(r.esperados, r.noEsperados), r.esperados);
      salida.fechaGeneral = objetivosAplicarAlPanel_(curso, salida.panel);   // instrucción 44 (Objetivos.gs)
      /* Instrucción 43 (Provisionales.gs, OtroCurso.gs): las filas de matrícula provisional que no se han podido emparejar. */
      salida.provisionalesLeidas = r.provisionalesLeidas;
      salida.provisionalesSinEmparejar = r.provisionalesSinEmparejar;
      salida.sobresLeidos = sobres.leidos;
      salida.sobresSinEmparejar = planificacionMezclarSinEmparejar_(sobres.sinEmparejar, plan.sinEmparejar);
      salida.planificacion = { leida: plan.leida, niveles: plan.niveles, avisos: plan.avisos };
      salida.avisosAdmision = salida.avisosAdmision.concat(sobres.avisos);
    }
    return salida;
  });
}

